			}
			case 10 : {
				bitField0_ |= 0x00000001;
				message_ = input.readBytes();
				break;
			}
			case 16 : {
				int rawValue = input.readEnum();
				org.eclipse.orion.server.cf.loggregator.LoggregatorMessage.Message.MessageType value = org.eclipse.orion.server.cf.loggregator.LoggregatorMessage.Message.MessageType.valueOf(rawValue);
				if (value == null) {
					unknownFields.mergeVarintField(2, rawValue);
				} else {
					bitField0_ |= 0x00000002;
					messageType_ = value;
				}
				break;
			}
			case 24 : {
				bitField0_ |= 0x00000004;
				timestamp_ = input.readSInt64();
				break;
			}
			case 34 : {
				bitField0_ |= 0x00000008;
				appId_ = input.readBytes();
				break;
			}
			case 50 : {
				bitField0_ |= 0x00000010;
				sourceId_ = input.readBytes();
				break;
			}
			case 58 : {
				ensureDrainUrlsIsMutable();
				drainUrls_.add(input.readBytes());
				break;
			}
			case 66 : {
				bitField0_ |= 0x00000040;
				sourceName_ = input.readBytes();
				break;
			}
		}
	}
}

static class CachedReader {
	File file;
	ImageInputStream stream;
	final PHDImage parentImage;
	class ReaderPos {
		int where;
		HeapdumpReader reader;
		ReaderPos(PHDImage parentImage) throws IOException {
			if(stream == null) {
				reader = new HeapdumpReader(file, parentImage);
			} else {
				reader = new HeapdumpReader(stream, parentImage);
			}
			where = 0;
		}
	}
	List<ReaderPos> readers = new ArrayList<ReaderPos>();
	CachedReader(File f, PHDImage parentImage) {
		file = f;
		this.parentImage = parentImage;
	}
	CachedReader(ImageInputStream stream, PHDImage parentImage) {
		this.stream = stream;
		this.parentImage = parentImage;
	}
	ReaderPos getReader(int n) throws IOException {
		ReaderPos best = null;
		for (ReaderPos rp : readers) {
			if (rp.where <= n && (best == null || best.where < rp.where)) {
				best =rp;
			}
		}
		if (best == null) {	
			best = new ReaderPos(parentImage);
		} else {
			readers.remove(best);
		}
		return best;
	}
	void returnReader(ReaderPos rdr) {
		readers.add(rdr);
	}
}

public class InstantTypeAdapter implements JsonSerializer<Instant>, JsonDeserializer<Instant>
{
    public static final InstantTypeAdapter DEFAULT_INSTANCE = new InstantTypeAdapter ();

    private final DateTimeFormatter formatter;

    public InstantTypeAdapter ( final DateTimeFormatter formatter )
    {
        this.formatter = formatter.withLocale ( Locale.US );
    }

    public InstantTypeAdapter ()
    {
        this ( DateTimeFormatter.ISO_INSTANT.withLocale ( Locale.US ) );
    }

    @Override
    public Instant deserialize ( final JsonElement json, final Type typeOfT, final JsonDeserializationContext context ) throws JsonParseException
    {
        if ( ! ( json instanceof JsonPrimitive ) )
        {
            throw new JsonParseException ( "Timestamps should be encoded as JSON strings" );
        }

        return Instant.from ( this.formatter.parse ( json.getAsString () ) );
    }

    @Override
    public JsonElement serialize ( final Instant src, final Type typeOfSrc, final JsonSerializationContext context )
    {
        return new JsonPrimitive ( this.formatter.format ( src ) );
    }

