public class Ping {

    /**
     * Checks the vitality of <code>host</code>. If <code>port</code> '0'
     * is specified (which is the default when configuring just the host), a
     * regular ping is issued. If other ports are specified we try open a new
     * Socket with the given <code>timeout</code>.
     * 
     * @param host
     * @param port
     * @param timeout
     * 
     * @return <code>true</code> when <code>host</code> is reachable on <code>port</code> within the given
     *         <code>timeout</code> and <code>false</code> in all other
     *         cases.
     * 
     * @throws IOException
     * @throws SocketTimeoutException
     */
    public static boolean checkVitality(String host, int port, int timeout) throws IOException, SocketTimeoutException {
        boolean success = false;

        if (host != null && timeout > 0) {
            if (port == 0) {
                success = InetAddress.getByName(host).isReachable(timeout);
            } else {
                SocketAddress socketAddress = new InetSocketAddress(host, port);

                Socket socket = new Socket();
                socket.connect(socketAddress, timeout);
                success = true;
                socket.close();
            }
        }

        return success;
    }

}

public class DatatypeGeneratorTask implements ICodeGeneratorTask<InformationModel> {

  private IFileTemplate<Entity> entityTemplate;
  private IFileTemplate<Enum> enumTemplate;

  public DatatypeGeneratorTask(IFileTemplate<Entity> entityTemplate,
      IFileTemplate<Enum> enumTemplate) {
    this.entityTemplate = entityTemplate;
    this.enumTemplate = enumTemplate;
  }

  @Override
  public void generate(InformationModel ctx, InvocationContext context, IGeneratedWriter writer) {
    Set<Type> allTypesUsedInModel = new HashSet<>();
    for (FunctionblockProperty prop : ctx.getProperties()) {
      allTypesUsedInModel.addAll(getTypes(prop.getType()));
    }

    for (Type type : allTypesUsedInModel) {
      if (type instanceof Entity) {
        writer.write(new Generated(entityTemplate.getFileName((Entity) type),
            entityTemplate.getPath((Entity) type),
            entityTemplate.getContent((Entity) type, context)));
      } else if (type instanceof Enum) {
        writer.write(new Generated(enumTemplate.getFileName((Enum) type),
            enumTemplate.getPath((Enum) type), enumTemplate.getContent((Enum) type, context)));
      }
    }
  }

  private static Set<Type> getTypes(FunctionblockModel model) {
    Set<Type> allTypes = new LinkedHashSet<>();
    TreeIterator<EObject> iterator = model.eAllContents();
    while (iterator.hasNext()) {
      EObject current = iterator.next();
      if (current instanceof RefParam) {
        addTypeAndReferences(((RefParam) current).getType(), allTypes);
      } else if (current instanceof ReturnObjectType) {
        addTypeAndReferences(((ReturnObjectType) current).getReturnType(), allTypes);
      } else if (current instanceof ObjectPropertyType) {
        addTypeAndReferences(((ObjectPropertyType) current).getType(), allTypes);
      }
    }
    return allTypes;
  }

  private static void addTypeAndReferences(Type type, Set<Type> container) {
    if (!container.contains(type)) {
      container.add(type);
      Set<Type> references = getTypesOfType(type, container);
      container.addAll(references);
    }
  }

  private static Set<Type> getTypesOfType(Type type, Set<Type> container) {
    TreeIterator<EObject> iterator = type.eAllContents();
    while (iterator.hasNext()) {
      EObject current = iterator.next();
      if (current instanceof ObjectPropertyType) {
        if (!container.contains(current)) {
          container.add(((ObjectPropertyType) current).getType());
          Set<Type> moreTypes = getTypesOfType(((ObjectPropertyType) current).getType(), container);
          container.addAll(moreTypes);
        }

      }
    }

    return container;
  }
}

public class N4JSLambdaValidator extends AbstractN4JSDeclarativeValidator {

	@Inject
	ContainerTypesHelper containerTypesHelper;

	/**
	 * NEEEDED
	 *
	 * when removed check methods will be called twice once by N4JSValidator, and once by
	 * AbstractDeclarativeN4JSValidator
	 */
	@Override
	public void register(EValidatorRegistrar registrar) {
		// nop
	}

	/**
	 * A top-level arrow function can't include uses of <code>arguments</code> and <code>this</code> as they lack an
	 * outer lexical context that would provide bindings for them.
	 */
	@Check
	public void checkTopLevelLambda(ArrowFunction arrowFun) {
		if (LambdaUtils.isTopLevelLambda(arrowFun)) {
			rejectUsagesOfThisInTopLevelLambda(arrowFun);
		}
	}

	/**
	 * Rejects uses of 'this' in top-level functions, which due to their top-level nature can't capture any 'this' from
	 * the enclosing context (same goes for 'arguments', by the way).
	 * <p>
	 * Precondition: the argument is a top-level lambda.
	 */
	private void rejectUsagesOfThisInTopLevelLambda(ArrowFunction topLevelLambda) {
		assert LambdaUtils.isLambda(topLevelLambda);
		Iterator<EObject> thisUsages = LambdaUtils.thisLiterals(topLevelLambda.getBody());
		while (thisUsages.hasNext()) {
			EObject thisUsage = thisUsages.next();
			String message = IssueCodes.getMessageForKEY_THIS_REJECTED_IN_TOP_LEVEL_LAMBDA();
			addIssue(message, thisUsage, IssueCodes.KEY_THIS_REJECTED_IN_TOP_LEVEL_LAMBDA);
		}
	}
}

