        jComponent.setToolTipText(error == null ? "" : error);
        if (originalBorder == null)
            originalBorder = jComponent.getBorder();

        jComponent.setBorder(error == null ? originalBorder : BorderFactory.createLineBorder(JBColor.RED));

        return (error == null);
