		this.items = items == null ? Collections.emptyList() : items;
		this.queries = queries == null ? Collections.emptyList() : queries;
		this.template = template;
		this.error = error;
	}

	CollectionJson() {
		this("1.0", null, Links.NONE, Collections.emptyList(), null, null, null);
