    String value = getProperty(key);
    if (value == null) {
        key = toSnakeUpperCase(Utils.PROPERTY_NAME_PREFIX + subsystem).replace(".", "");
        key = key + '_' + toSnakeUpperCase(name);
        value = getEnv(key);
        if (value != null) {
            logFoundEnvVar(verboseResolution, key, value);
