public class ItemSorter extends ViewerSorter
{

	/**
	 * Returns a negative, zero, or positive number depending on whether the
	 * first element is less than, equal to, or greater than the second element.
	 * <p>
	 * The default implementation of this method is based on comparing the
	 * elements' categories as computed by the <code>category</code> framework
	 * method. Elements within the same category are further subjected to a case
	 * insensitive compare of their label strings, either as computed by the
	 * content viewer's label provider, or their <code>toString</code> values
	 * in other cases. Subclasses may override.
	 * </p>
	 * 
	 * @param viewer
	 *            the viewer
	 * @param e1
	 *            the first element
	 * @param e2
	 *            the second element
	 * @return a negative number if the first element is less than the second
	 *         element; the value <code>0</code> if the first element is equal
	 *         to the second element; and a positive number if the first element
	 *         is greater than the second element
	 */

	public int compare( Viewer viewer, Object e1, Object e2 )
	{
		/*
		 * if ( e1 instanceof ITreeItemNode && e2 instanceof ITreeItemNode ) {
		 * int type1 = ( (ITreeItemNode) e1 ).getType(); int type2 = (
		 * (ITreeItemNode) e2 ).getType(); if ( type1 == type2 && type1 ==
		 * ITreeItemNode.ITEM ) { return super.compare( viewer, e1, e2 ); } }
		 */
		if ( e1 instanceof DataSourceHandle && e2 instanceof DataSourceHandle )
		{
			return super.compare( viewer, e1, e2 );
		}
		if ( e1 instanceof DataSetHandle && e2 instanceof DataSetHandle )
		{
			return super.compare( viewer, e1, e2 );
		}
		if ( e1 instanceof CubeHandle && e2 instanceof CubeHandle )
		{
			return super.compare( viewer, e1, e2 );
		}
		return 0;
	}

}

public class ReportOSGiLaunchDelegate extends
		EclipseApplicationLaunchConfiguration implements IReportLaunchConstants
{

	ReportLaunchHelper helper;
	public static final String APP_NAME = "application name";//$NON-NLS-1$

	public ReportOSGiLaunchDelegate( )
	{
		helper = new ReportLaunchHelper( );
	}

	public void launch( ILaunchConfiguration configuration, String mode,
			ILaunch launch, IProgressMonitor monitor ) throws CoreException
	{
		helper.init( configuration );

		super.launch( configuration, mode, launch, monitor );
	}

	public String[] getVMArguments( ILaunchConfiguration configuration )
			throws CoreException
	{
		String[] args = super.getVMArguments( configuration );

		List arguments = new ArrayList( );

		for ( int i = 0; i < args.length; i++ )
		{
			arguments.add( args[i] );
		}

		helper.addPortArgs( arguments );
		helper.addUserClassPath( arguments, configuration );
		helper.addFileNameArgs( arguments );
		helper.addEngineHomeArgs( arguments );
		helper.addResourceFolder( arguments );
		helper.addTempFolder( arguments );
		helper.addTypeArgs( arguments );
		helper.addDataLimitArgs(arguments);
		helper.addParameterArgs( arguments );

		return (String[]) arguments.toArray( new String[arguments.size( )] );
	}

	public String[] getProgramArguments( ILaunchConfiguration configuration )
			throws CoreException
	{
		String[] args = super.getProgramArguments( configuration );

		List list = new ArrayList( );

		for ( int i = 0; i < args.length; i++ )
		{
			list.add( args[i] );
		}

		int idx = list.indexOf( "-application" ); //$NON-NLS-1$

		if ( idx != -1 && ( idx + 1 ) < list.size( ) )
		{
			list.set( idx + 1,
					getApplicationName( ) ); //$NON-NLS-1$
		}
		else
		{
			list.add( "-application" ); //$NON-NLS-1$
			list.add( getApplicationName( ) ); //$NON-NLS-1$
		}

		list.add( "-nosplash" ); //$NON-NLS-1$

		return (String[]) list.toArray( new String[list.size( )] );
	}

	private String getApplicationName()
	{
		String name = System.getProperty( APP_NAME );
		if (name == null || name.length( ) == 0)
		{
			name = "org.eclipse.birt.report.debug.core.ReportDebugger";
		}
		return name;
	}

	public IVMRunner getVMRunner( ILaunchConfiguration configuration,
			String mode ) throws CoreException
	{
		if ( ( helper.debugType & DEBUG_TYPE_JAVA_CLASS ) == DEBUG_TYPE_JAVA_CLASS )
		{
			mode = ILaunchManager.DEBUG_MODE;
		}
		else
		{
			mode = ILaunchManager.RUN_MODE;
		}

		return new ReportDebuggerVMRunner( super.getVMRunner( configuration,
				mode ),
				( helper.debugType & DEBUG_TYPE_JAVA_SCRIPT ) == DEBUG_TYPE_JAVA_SCRIPT,
				this );
	}

	protected IProject[] getBuildOrder( ILaunchConfiguration configuration,
			String mode ) throws CoreException
	{
		return super.getBuildOrder( configuration, mode );
	}

	public boolean finalLaunchCheck( final ILaunchConfiguration configuration,
			String mode, IProgressMonitor monitor ) throws CoreException
	{

		boolean bool = super.finalLaunchCheck( configuration, mode, monitor );

		if ( !bool )
		{
			return bool;
		}

		return helper.finalLaunchCheck( configuration, mode, monitor );
	}

}

public class FolderArchiveFile implements IArchiveFile
{

	private static final String METEDATA = ".metadata";
	private static Logger logger = Logger.getLogger( FolderArchiveFile.class
			.getName( ) );
	protected String folderName;
	protected String systemId;
	protected String dependId;
	private HashSet<RAFolderInputStream> inputStreams = new HashSet<RAFolderInputStream>( );
	private HashSet<RAFolderOutputStream> outputStreams = new HashSet<RAFolderOutputStream>( );

	protected Map<String, String> properties = new HashMap<String, String>();

    public FolderArchiveFile( String name ) throws IOException
    {
        if ( name == null || name.length( ) == 0 )
            throw new IOException(
                    CoreMessages
                            .getString( ResourceConstants.FOLDER_NAME_IS_NULL ) );

        File file = new File( name );
        file.mkdirs( );
        this.folderName = file.getCanonicalPath( );
        readMetaData( );
    }

    public String getName( )
    {
        return folderName;
    }

    private void readMetaData( ) throws IOException
    {
        // serialize meta data into .metedata file
        String meta = ArchiveUtil.getFullPath( folderName, METEDATA );
        File file = new File( meta );
        if ( file.exists( ) && file.isFile( ) )
        {
            DataInputStream data = new DataInputStream( new FileInputStream(
                    file ) );
            try
            {
                properties = (Map<String, String>) IOUtil.readMap( data );
            }
            finally
            {
                data.close( );
            }
        }
    }

    private void saveMetaData( ) throws IOException
    {
        // serialize meta data into .metedata file
        String meta = ArchiveUtil.getFullPath( folderName, METEDATA );
        File file = new File( meta );
        DataOutputStream data = new DataOutputStream( new FileOutputStream(
                file ) );
        try
        {
            IOUtil.writeMap( data, this.properties );
        }
        finally
        {
            data.close( );
        }
    }

    public void close( ) throws IOException
    {
        saveMetaData( );

        IOException exception = null;
        synchronized ( outputStreams )
        {
            ArrayList<RAFolderOutputStream> outputs = new ArrayList<RAFolderOutputStream>(
                    outputStreams );
            for ( RAFolderOutputStream output : outputs )
            {
                try
                {
                    output.close( );
                }
                catch ( IOException ex )
                {
                    logger.log( Level.SEVERE, ex.getMessage( ), ex );
                    if ( exception != null )
                    {
                        exception = ex;
                    }
                }
            }
            outputStreams.clear( );
        }
        synchronized ( inputStreams )
        {
            ArrayList<RAFolderInputStream> inputs = new ArrayList<RAFolderInputStream>(
                    inputStreams );
            for ( RAFolderInputStream input : inputs )
            {
                try
                {
                    input.close( );
                }
                catch ( IOException ex )
                {
                    logger.log( Level.SEVERE, ex.getMessage( ), ex );
                    if ( exception != null )
                    {
                        exception = ex;
                    }
                }
            }
            inputStreams.clear( );
        }
        if ( exception != null )
        {
            throw exception;
        }
        // ArchiveUtil.archive( folderName, null, fileName );

    }

	public void flush( ) throws IOException
	{
		IOException ioex = null;
		synchronized ( outputStreams )
		{

			for ( RAOutputStream output : outputStreams )
			{
				try
				{
					output.flush( );
				}
				catch ( IOException ex )
				{
					logger.log(Level.SEVERE, ex.getMessage( ), ex);
					if ( ioex != null )
					{
						ioex = ex;
					}
				}

			}
		}
		if ( ioex != null )
		{
			throw ioex;
		}
	}

	public void refresh( ) throws IOException
	{
	}

	public boolean exists( String name )
	{
		String path = getFilePath( name );
		File fd = new File( path );
		return fd.exists( );
	}

	public void setCacheSize( long cacheSize )
	{
	}

	public long getUsedCache( )
	{
		return 0;
	}

	public ArchiveEntry openEntry( String name ) throws IOException
	{
        String fullPath = getFilePath( name );
		File fd = new File( fullPath );
		if(fd.exists( ))
		{
			return new FolderArchiveEntry( name, fd, inputStreams, outputStreams );
		}
		throw new FileNotFoundException( fullPath );
	}

    public List<String> listEntries( String namePattern )
    {
        ArrayList<String> streamList = new ArrayList<String>( );
        String storagePath = getFolderPath( namePattern );

        ArrayList<File> files = new ArrayList<File>( );
        ArchiveUtil.listAllFiles( new File( storagePath ), files );
        for ( File file : files )
        {
            String relativePath = ArchiveUtil.getRelativePath( folderName,
                    file.getPath( ) );
            if ( !ArchiveUtil.needSkip( relativePath ) )
            {
                String entryName = ArchiveUtil.getEntryName( folderName,
                        file.getPath( ) );
                streamList.add( entryName );
            }
        }
        return streamList;
    }

	public ArchiveEntry createEntry( String name ) throws IOException
	{
		String path = getFilePath( name );
		File fd = new File( path );

		ArchiveUtil.createParentFolder( fd );

		FolderArchiveEntry out = new FolderArchiveEntry( name, fd, inputStreams, outputStreams  );
		return out;
	}

	public boolean removeEntry( String name ) throws IOException
	{
        String path = getFilePath( name );
		try
		{
			File fd = new File( path );
			return ArchiveUtil.removeFileAndFolder( fd );
		}
		finally
		{
			synchronized ( outputStreams )
			{
				ArrayList<RAFolderOutputStream> outputs = new ArrayList<RAFolderOutputStream>(
						outputStreams );
				for ( RAFolderOutputStream output : outputs )
				{
					try
					{
						if(name.equals( output.getName( ) ))
						{
							output.close( );
						}
					}
					catch ( IOException ex )
					{
						logger.log(Level.SEVERE, ex.getMessage( ), ex);
						throw ex;
					}
				}
			}
		}

	}

	public Object lockEntry( String entry ) throws IOException
	{
        String path = getFilePath( entry ) + ".lck";
		IArchiveLockManager lockManager = ArchiveLockManager.getInstance( );
		return lockManager.lock( path );
	}

	public void unlockEntry( Object locker ) throws IOException
	{
		IArchiveLockManager lockManager = ArchiveLockManager.getInstance( );
		lockManager.unlock( locker );

	}

	public String getSystemId( )
	{
		if ( properties.containsKey( ArchiveFileV3.PROPERTY_SYSTEM_ID ) )
		{
			return properties.get( ArchiveFileV3.PROPERTY_SYSTEM_ID )
					.toString( );
		}
		return null;
	}

	public String getDependId( )
	{
