public class RecordColumnarIndexer implements IExternalIndexer {

    private static final long serialVersionUID = 1L;
    public static final int NUM_OF_FIELDS = 3;
    protected final AMutableInt32 fileNumber = new AMutableInt32(0);
    protected final AMutableInt64 offset = new AMutableInt64(0);
    protected long nextOffset;
    protected final AMutableInt32 rowNumber = new AMutableInt32(0);
    protected RecordReader<?, Writable> recordReader;

    @SuppressWarnings("unchecked")
    private ISerializerDeserializer<IAObject> intSerde =
            SerializerDeserializerProvider.INSTANCE.getSerializerDeserializer(BuiltinType.AINT32);
    @SuppressWarnings("unchecked")
    private ISerializerDeserializer<IAObject> longSerde =
            SerializerDeserializerProvider.INSTANCE.getSerializerDeserializer(BuiltinType.AINT64);

    @Override
    public void reset(IIndexingDatasource reader) throws HyracksDataException {
        try {
            //TODO: Make this more generic. right now, it works because we only index hdfs files.
            @SuppressWarnings("unchecked")
            HDFSRecordReader<?, Writable> hdfsReader = (HDFSRecordReader<?, Writable>) reader;
            fileNumber.setValue(hdfsReader.getSnapshot().get(hdfsReader.getCurrentSplitIndex()).getFileNumber());
            recordReader = hdfsReader.getReader();
            offset.setValue(recordReader.getPos());

            nextOffset = offset.getLongValue();
            rowNumber.setValue(0);
        } catch (IOException e) {
            throw HyracksDataException.create(e);
        }
    }

    @Override
    public void index(ArrayTupleBuilder tb) throws HyracksDataException {
        try {
            if (recordReader.getPos() != nextOffset) {
                // start of a new group
                offset.setValue(nextOffset);
                nextOffset = recordReader.getPos();
                rowNumber.setValue(0);
            }
            tb.addField(intSerde, fileNumber);
            tb.addField(longSerde, offset);
            tb.addField(intSerde, rowNumber);
            rowNumber.setValue(rowNumber.getIntegerValue() + 1);
        } catch (IOException e) {
            throw HyracksDataException.create(e);
        }
    }

    @Override
    public int getNumberOfFields() {
        return NUM_OF_FIELDS;
    }

}

@Beta
public interface Transaction<OpResultT> {

    /**
     * An operation executed in a transaction.
     */
    interface Op<OpResultT> {

        /**
         * Execute after the transaction succeeds.
         */
        void commit(OpResultT r);

        /**
         * Execute after the transaction fails.
         */
        void abort(Throwable t, OpResultT r);

    }

    /**
     * Listener on the result of an {@link Transaction.Op}.
     *
     * @param <OpResultT>
     */
    interface OpListener<OpResultT> {

        /**
         * Trigger on operation committed.
         *
         * @param r
         *          result to return
         */
        void onCommit(OpResultT r);

        /**
         * Trigger on operation aborted.
         *
         * @param t
         *          reason to abort
         */
        void onAbort(Throwable t);
    }

    /**
     * Add the operation to current transaction.
     *
     * @param operation
     *          operation to execute under current transaction
     */
    void addOp(Op<OpResultT> operation);

    /**
     * Execute the current transaction. If the transaction succeed, all operations will be
     * committed (via {@link Transaction.Op#commit(Object)}.
     * Otherwise, all operations will be aborted (via {@link Op#abort(Throwable, Object)}).
     *
     * @return future representing the result of transaction execution.
     */
    CompletableFuture<Void> execute();

    /**
     * Abort current transaction. If this is called and the transaction haven't been executed by
     * {@link #execute()}, it would abort all operations. If the transaction has been executed,
     * the behavior is left up to implementation - if transaction is cancellable, the {@link #abort(Throwable)}
     * could attempt to cancel it.
     *
     * @param reason reason to abort the transaction
     */
    void abort(Throwable reason);

}

protected void readPayload(ByteBuf in, boolean copyData) throws IOException {
    int length = in.readInt();
    if (length < 0) {
        throw new EOFException("Log Record is corrupt: Negative length " + length);
    }
    if (copyData) {
        setPayloadBuf(in.slice(in.readerIndex(), length), true);
    } else {
        setPayloadBuf(in.retainedSlice(in.readerIndex(), length), false);
    }
    in.skipBytes(length);
}

