public void crawl(File dirRoot) {
   LOG.info(String.format("Start crawling dir: %s", dirRoot));

   // Reset ingest status.a

   ingestStatus.clear();

   // Load actions.
   loadAndValidateActions();

   // Create Ingester.
   setupIngester();

   // Verify valid crawl directory.
   if (dirRoot == null || !dirRoot.exists()) {
      throw new IllegalArgumentException("dir root is null or non existant!");
   }

   // Start crawling.
   Stack<File> stack = new Stack<File>();
   stack.push(dirRoot.isDirectory() ? dirRoot : dirRoot.getParentFile());
   while (!stack.isEmpty()) {
      File dir = (File) stack.pop();
      LOG.log(Level.INFO, "Crawling " + dir);

      File[] productFiles;
      productFiles = isCrawlForDirs() ? dir.listFiles(DIR_FILTER) : dir.listFiles(FILE_FILTER);

      if(productFiles!=null) {
         for (File productFile : productFiles) {
            ingestStatus.add(handleFile(productFile));
         }
      }

      if (!isNoRecur()) {
         File[] subdirs = dir.listFiles(DIR_FILTER);
         if (subdirs != null) {
            for (File subdir : subdirs) {
               stack.push(subdir);
            }
         }
      }
   }

   LOG.info(String.format("Finished crawling dir: %s", dirRoot));
}

public class TransparencyFilterTrueColor extends TransparencyFilter {
    private final int transparentColor;

    public TransparencyFilterTrueColor(final byte[] bytes) throws IOException {
        super(bytes);

        final ByteArrayInputStream is = new ByteArrayInputStream(bytes);
        final int transparentRed = read2Bytes("transparentRed", is, "tRNS: Missing transparentColor", getByteOrder());
        final int transparentGreen = read2Bytes("transparentGreen", is, "tRNS: Missing transparentColor", getByteOrder());
        final int transparentBlue = read2Bytes("transparentBlue", is, "tRNS: Missing transparentColor", getByteOrder());

        transparentColor = ((0xff & transparentRed) << 16)
                | ((0xff & transparentGreen) << 8)
                | ((0xff & transparentBlue) << 0);

    }

    @Override
    public int filter(final int rgb, final int sample) throws ImageReadException,
            IOException {
        if ((0x00ffffff & rgb) == transparentColor) {
            return 0x00;
        }

        return rgb;
    }
}

