private static class DoubleTreeWriter extends TreeWriter {
  private final PositionedOutputStream stream;
  private final SerializationUtils utils;

  DoubleTreeWriter(int columnId,
                   TypeDescription schema,
                   StreamFactory writer,
                   boolean nullable) throws IOException {
    super(columnId, schema, writer, nullable);
    this.stream = writer.createStream(id,
        OrcProto.Stream.Kind.DATA);
    this.utils = new SerializationUtils();
    recordPosition(rowIndexPosition);
  }

  @Override
  void write(Datum datum) throws IOException {
    super.write(datum);
    if (datum != null && datum.isNotNull()) {
      double val = datum.asFloat8();
      indexStatistics.updateDouble(val);
      if (createBloomFilter) {
        bloomFilter.addDouble(val);
      }
      utils.writeDouble(stream, val);
    }
  }

  @Override
  void writeStripe(OrcProto.StripeFooter.Builder builder,
                   int requiredIndexEntries) throws IOException {
    super.writeStripe(builder, requiredIndexEntries);
    stream.flush();
    recordPosition(rowIndexPosition);
  }

  @Override
  void recordPosition(PositionRecorder recorder) throws IOException {
    super.recordPosition(recorder);
    stream.getPosition(recorder);
  }
}

public class BlueGigaEndProcedureResponse extends BlueGigaResponse {
    public static int COMMAND_CLASS = 0x06;
    public static int COMMAND_METHOD = 0x04;

    /**
     * 0: the command was successful. Non-zero: An error occurred
     * <p>
     * BlueGiga API type is <i>BgApiResponse</i> - Java type is {@link BgApiResponse}
     */
    private BgApiResponse result;

    /**
     * Response constructor
     */
    public BlueGigaEndProcedureResponse(int[] inputBuffer) {
        // Super creates deserializer and reads header fields
        super(inputBuffer);

        event = (inputBuffer[0] & 0x80) != 0;

        // Deserialize the fields
        result = deserializeBgApiResponse();
    }

    /**
     * 0: the command was successful. Non-zero: An error occurred
     * <p>
     * BlueGiga API type is <i>BgApiResponse</i> - Java type is {@link BgApiResponse}
     *
     * @return the current result as {@link BgApiResponse}
     */
