public class IndexDataWriter
{
    static final int VERSION = 1;

    static final int F_INDEXED = 1;

    static final int F_TOKENIZED = 2;

    static final int F_STORED = 4;

    static final int F_COMPRESSED = 8;

    private final DataOutputStream dos;

    private final GZIPOutputStream gos;

    private final BufferedOutputStream bos;

    private final Set<String> allGroups;

    private final Set<String> rootGroups;

    private boolean descriptorWritten;

    public IndexDataWriter( OutputStream os )
        throws IOException
    {
        bos = new BufferedOutputStream( os, 1024 * 8 );
        gos = new GZIPOutputStream( bos, 1024 * 2 );
        dos = new DataOutputStream( gos );

        this.allGroups = new HashSet<String>();
        this.rootGroups = new HashSet<String>();
        this.descriptorWritten = false;
    }

    public int write( IndexingContext context, IndexReader indexReader, List<Integer> docIndexes )
        throws IOException
    {
        writeHeader( context );

        int n = writeDocuments( indexReader, docIndexes );

        writeGroupFields();

        close();

        return n;
    }

    public void close()
        throws IOException
    {
        dos.flush();

        gos.flush();
        gos.finish();

        bos.flush();
    }

    public void writeHeader( IndexingContext context )
        throws IOException
    {
        dos.writeByte( VERSION );

        Date timestamp = context.getTimestamp();
        dos.writeLong( timestamp == null ? -1 : timestamp.getTime() );
    }

    public void writeGroupFields()
        throws IOException
    {
        {
            List<IndexableField> allGroupsFields = new ArrayList<>( 2 );
            allGroupsFields.add( new StringField( ArtifactInfo.ALL_GROUPS, ArtifactInfo.ALL_GROUPS_VALUE, Store.YES ) );
            allGroupsFields.add( new StringField( ArtifactInfo.ALL_GROUPS_LIST, ArtifactInfo.lst2str( allGroups ),
                                                  Store.YES ) );
            writeDocumentFields( allGroupsFields );
        }

        {
            List<IndexableField> rootGroupsFields = new ArrayList<>( 2 );
            rootGroupsFields.add( new StringField( ArtifactInfo.ROOT_GROUPS, ArtifactInfo.ROOT_GROUPS_VALUE,
                                                   Store.YES ) );
            rootGroupsFields.add( new StringField( ArtifactInfo.ROOT_GROUPS_LIST, ArtifactInfo.lst2str( rootGroups ),
                                                   Store.YES ) );
            writeDocumentFields( rootGroupsFields );
        }
    }

    public int writeDocuments( IndexReader r, List<Integer> docIndexes )
        throws IOException
    {
        int n = 0;
        Bits liveDocs = MultiFields.getLiveDocs( r );

        if ( docIndexes == null )
        {
            for ( int i = 0; i < r.maxDoc(); i++ )
            {
                if ( liveDocs == null || liveDocs.get( i ) )
                {
                    if ( writeDocument( r.document( i ) ) )
                    {
                        n++;
                    }
                }
            }
        }
        else
        {
            for ( int i : docIndexes )
            {
                if ( liveDocs == null || liveDocs.get( i ) )
                {
                    if ( writeDocument( r.document( i ) ) )
                    {
                        n++;
                    }
                }
            }
        }

        return n;
    }

    public boolean writeDocument( final Document document )
        throws IOException
    {
        List<IndexableField> fields = document.getFields();

        List<IndexableField> storedFields = new ArrayList<>( fields.size() );

        for ( IndexableField field : fields )
        {
            if ( DefaultIndexingContext.FLD_DESCRIPTOR.equals( field.name() ) )
            {
                if ( descriptorWritten )
                {
                    return false;
                }
                else
                {
                    descriptorWritten = true;
                }
            }

            if ( ArtifactInfo.ALL_GROUPS.equals( field.name() ) )
            {
                final String groupList = document.get( ArtifactInfo.ALL_GROUPS_LIST );

                if ( groupList != null && groupList.trim().length() > 0 )
                {
                    allGroups.addAll( ArtifactInfo.str2lst( groupList ) );
                }

                return false;
            }

            if ( ArtifactInfo.ROOT_GROUPS.equals( field.name() ) )
            {
                final String groupList = document.get( ArtifactInfo.ROOT_GROUPS_LIST );

                if ( groupList != null && groupList.trim().length() > 0 )
                {
                    rootGroups.addAll( ArtifactInfo.str2lst( groupList ) );
                }

                return false;
            }

            if ( field.fieldType().stored() )
            {
                storedFields.add( field );
            }
        }

        writeDocumentFields( storedFields );

        return true;
    }

    public void writeDocumentFields( List<IndexableField> fields )
        throws IOException
    {
        dos.writeInt( fields.size() );

        for ( IndexableField field : fields )
        {
            writeField( field );
        }
    }

    public void writeField( IndexableField field )
        throws IOException
    {
        int flags = ( field.fieldType().indexOptions() != IndexOptions.NONE  ? F_INDEXED : 0 ) //
            + ( field.fieldType().tokenized() ? F_TOKENIZED : 0 ) //
            + ( field.fieldType().stored() ? F_STORED : 0 ); //
        // + ( false ? F_COMPRESSED : 0 ); // Compressed not supported anymore

        String name = field.name();
        String value = field.stringValue();

        dos.write( flags );
        dos.writeUTF( name );
        writeUTF( value, dos );
    }

    private static void writeUTF( String str, DataOutput out )
        throws IOException
    {
        int strlen = str.length();
        int utflen = 0;
        int c;

        // use charAt instead of copying String to char array
        for ( int i = 0; i < strlen; i++ )
        {
            c = str.charAt( i );
            if ( ( c >= 0x0001 ) && ( c <= 0x007F ) )
            {
                utflen++;
            }
            else if ( c > 0x07FF )
            {
                utflen += 3;
            }
            else
            {
                utflen += 2;
            }
        }

        // TODO optimize storing int value
        out.writeInt( utflen );

        byte[] bytearr = new byte[utflen];

        int count = 0;

        int i = 0;
        for ( ; i < strlen; i++ )
        {
            c = str.charAt( i );
            if ( !( ( c >= 0x0001 ) && ( c <= 0x007F ) ) )
            {
                break;
            }
            bytearr[count++] = (byte) c;
        }

        for ( ; i < strlen; i++ )
        {
            c = str.charAt( i );
            if ( ( c >= 0x0001 ) && ( c <= 0x007F ) )
            {
                bytearr[count++] = (byte) c;

            }
            else if ( c > 0x07FF )
            {
                bytearr[count++] = (byte) ( 0xE0 | ( ( c >> 12 ) & 0x0F ) );
                bytearr[count++] = (byte) ( 0x80 | ( ( c >> 6 ) & 0x3F ) );
                bytearr[count++] = (byte) ( 0x80 | ( ( c >> 0 ) & 0x3F ) );
            }
            else
            {
                bytearr[count++] = (byte) ( 0xC0 | ( ( c >> 6 ) & 0x1F ) );
                bytearr[count++] = (byte) ( 0x80 | ( ( c >> 0 ) & 0x3F ) );
            }
        }

        out.write( bytearr, 0, utflen );
    }

}

public class CommandSubscription {

    private static final Logger LOG = LoggerFactory.getLogger(CommandSubscription.class);

    private String endpoint;
    private String req;
    private String tenant;
    private String deviceId;
    private MqttQoS qos;
    private String clientId;
    private String topic;
    private boolean isAuthenticated;

    private CommandSubscription(final String topic) {
        Objects.requireNonNull(topic);
        this.topic = topic;
        final String[] parts = topic.split("\\/");
        if (parts.length != 5 || !"#".equals(parts[4])) {
            throw new IllegalArgumentException("topic filter does not match pattern: control|c/+/+/req|q/#");
        }
        endpoint = parts[0];
        if (!CommandConstants.isCommandEndpoint(endpoint)) {
            throw new IllegalArgumentException(
                    "the endpoint needs to be '" + CommandConstants.COMMAND_ENDPOINT + "' or '"
                            + CommandConstants.COMMAND_ENDPOINT_SHORT + "'");
        }
        req = parts[3];
        if (!CommandConstants.COMMAND_RESPONSE_REQUEST_PART.equals(req)
                && !CommandConstants.COMMAND_RESPONSE_REQUEST_PART_SHORT.equals(req)) {
            throw new IllegalArgumentException(
                    "the request part needs to be '" + CommandConstants.COMMAND_RESPONSE_REQUEST_PART + "' or '"
                            + CommandConstants.COMMAND_RESPONSE_REQUEST_PART_SHORT + "'");
        }
        if (!"+".equals(parts[1])) {
            tenant = parts[1];
        }
        if (!"+".equals(parts[2])) {
            deviceId = parts[2];
        }
    }

    private CommandSubscription(final String topic, final Device authenticatedDevice) {
        this(topic);
        if (authenticatedDevice == null) {
            isAuthenticated = false;
            if (tenant == null || tenant.isEmpty()) {
                throw new IllegalArgumentException(
                        "for unauthenticated devices the tenant needs to be given in the subscription");
            }
            if (deviceId == null || deviceId.isEmpty()) {
                throw new IllegalArgumentException(
                        "for unauthenticated devices the device-id needs to be given in the subscription");
            }
        } else {
            isAuthenticated = true;
            if ((tenant != null && !authenticatedDevice.getTenantId().equals(tenant)) ||
                    (deviceId != null && !authenticatedDevice.getDeviceId().equals(deviceId))) {
                throw new IllegalArgumentException(
                        "for authenticated devices the given device-id and tenant need to match the authentication or be undefined ('+')");
            } else {
                tenant = authenticatedDevice.getTenantId();
                deviceId = authenticatedDevice.getDeviceId();
            }
        }
    }

    private CommandSubscription(final String topic, final Device authenticatedDevice, final MqttQoS qos, final String clientId) {
        this(topic, authenticatedDevice);
        this.qos = qos;
        this.clientId = clientId;
    }

    /**
     * Gets the tenant from topic or authentication .
     *
     * @return The tenant.
     */
    public String getTenant() {
        return tenant;
    }

    /**
     * Gets the device id from topic or authentication.
     *
     * @return The device id.
     */
    public String getDeviceId() {
        return deviceId;
    }

    /**
     * Gets the endpoint of the subscription.
     *
     * @return The endpoint.
     */
    public String getEndpoint() {
        return endpoint;
    }

    /**
     * Gets the QoS of the subscription.
     *
     * @return The QoS value.
     */
    public MqttQoS getQos() {
        return qos;
    }

    /**
     * Gets the clientId of the Mqtt subscription.
     *
     * @return The clientId.
     */
    public String getClientId() {
        return clientId;
    }

    /**
     * Gets the subscription topic.
     *
     * @return The topic.
     */
    public String getTopic() {
        return topic;
    }

    /**
     * Gets the request part of the subscription.
     *
     * @return The request part.
     */
    public String getRequestPart() {
        return req;
    }

    /**
     * Gets the authentication status, which indicates the need to publish on tenant/device-id for unauthenticated
     * devices.
     *
     * @return {@code true} if created with an authenticated device.
     */
    public boolean isAuthenticated() {
        return isAuthenticated;
    }

    /**
     * Creates a command subscription object for the given topic. When the authenticated device is given
     * it is used to either check given tenant and device-id from topic or fill this
     * fields if not given.
     *
     * @param topic The topic to subscribe for commands.
     * @param authenticatedDevice The authenticated device or {@code null}.
     * @return The CommandSubscription object or {@code null} if the topic does not match the rules.
     * @throws NullPointerException if topic is {@code null}.
     */
    public static CommandSubscription fromTopic(final String topic, final Device authenticatedDevice) {
        try {
            return new CommandSubscription(topic, authenticatedDevice);
        } catch (final IllegalArgumentException e) {
            LOG.debug(e.getMessage());
            return null;
        }
    }

    /**
     * Creates a command subscription object for the given topic. When the authenticated device is given
     * it is used to either check given tenant and device-id from topic or fill this
     * fields if not given.
     *
     * @param mqttTopicSub The MqttTopicSubscription request from device for command subscription.
     * @param authenticatedDevice The authenticated device or {@code null}.
     * @param clientId The the client identifier as provided by the remote MQTT client.
     * @return The CommandSubscription object or {@code null} if the topic does not match the rules.
     * @throws NullPointerException if topic is {@code null}.
     */
    public static CommandSubscription fromTopic(final MqttTopicSubscription mqttTopicSub, final Device authenticatedDevice, final String clientId) {
        try {
            return new CommandSubscription(mqttTopicSub.topicName(), authenticatedDevice,
                    mqttTopicSub.qualityOfService(), clientId);
        } catch (final IllegalArgumentException e) {
            LOG.debug(e.getMessage());
            return null;
        }
    }
}

public class PeriodicAccrualAccountingHelper {

    private static final String PERIODIC_ACCRUAL_URL = "/fineract-provider/api/v1/runaccruals";
    private final RequestSpecification requestSpec;
    private final ResponseSpecification responseSpec;

    public PeriodicAccrualAccountingHelper(final RequestSpecification requestSpec, final ResponseSpecification responseSpec) {
        this.requestSpec = requestSpec;
        this.responseSpec = responseSpec;
    }

    public Object runPeriodicAccrualAccounting(String date) {
        String json = getRunPeriodicAccrual(date);
        return Utils.performServerPost(this.requestSpec, this.responseSpec, PERIODIC_ACCRUAL_URL + "?" + Utils.TENANT_IDENTIFIER, json, "");
    }

    private String getRunPeriodicAccrual(String date) {
        final HashMap<String, String> map = new HashMap<>();
        map.put("dateFormat", "dd MMMM yyyy");
        map.put("locale", "en_GB");
        map.put("tillDate", date);
        return new Gson().toJson(map);
    }

}

