public class BulkSetSerializer extends SimpleTypeSerializer<BulkSet> {
    public BulkSetSerializer() {
        super(DataType.BULKSET);
    }

    @Override
    protected BulkSet readValue(final ByteBuf buffer, final GraphBinaryReader context) throws SerializationException {
        final int length = buffer.readInt();

        final BulkSet result = new BulkSet();
        for (int i = 0; i < length; i++) {
            result.add(context.read(buffer), buffer.readLong());
        }

        return result;
    }

    @Override
    protected void writeValue(final BulkSet value, final ByteBuf buffer, final GraphBinaryWriter context) throws SerializationException {
        final Map<Object,Long> raw = value.asBulk();
        buffer.writeInt(raw.size());

        for (Object key : raw.keySet()) {
            context.write(key, buffer);
            buffer.writeLong(value.get(key));
        }
    }
}

public final class LdapProtocolUtils
{
    /** A delimiter for the replicaId */
    public static final String COOKIE_DELIM = ",";

    /** the prefix for replicaId value */
    public static final String REPLICA_ID_PREFIX = "rid=";

    public static final int REPLICA_ID_PREFIX_LEN = REPLICA_ID_PREFIX.length();

    /** the prefix for Csn value */
    public static final String CSN_PREFIX = "csn=";

    private static final int CSN_PREFIX_LEN = CSN_PREFIX.length();

    private static final Logger LOG = LoggerFactory.getLogger( LdapProtocolUtils.class );


    private LdapProtocolUtils()
    {
    }


    /**
     * Extracts request controls from a request to populate into an
     * OperationContext.
     *
     * @param opContext the context to populate with request controls
     * @param request the request to extract controls from
     */
    public static void setRequestControls( OperationContext opContext, Request request )
    {
        if ( request.getControls() != null )
        {
            opContext
                .addRequestControls( request.getControls().values().toArray( LdapProtocolConstants.EMPTY_CONTROLS ) );
        }
    }


    /**
     * Extracts response controls from a an OperationContext to populate into
     * a Response object.
     *
     * @param opContext the context to extract controls from
     * @param response the response to populate with response controls
     */
    public static void setResponseControls( OperationContext opContext, Response response )
    {
        response.addAllControls( opContext.getResponseControls() );
    }


    public static byte[] createCookie( int replicaId, String csn )
    {
        // the syncrepl cookie format (compatible with OpenLDAP)
        // rid=nn,csn=xxxz
        String replicaIdStr = StringUtils.leftPad( Integer.toString( replicaId ), 3, '0' );
        return Strings.getBytesUtf8( REPLICA_ID_PREFIX + replicaIdStr + COOKIE_DELIM + CSN_PREFIX + csn );
    }


    /**
     * Check the cookie syntax. A cookie must have the following syntax :
     * { rid={replicaId},csn={CSN} }
     *
     * @param cookieString The cookie
     * @return <tt>true</tt> if the cookie is valid
     */
    public static boolean isValidCookie( String cookieString )
    {
        if ( ( cookieString == null ) || ( cookieString.trim().length() == 0 ) )
        {
            return false;
        }

        int pos = cookieString.indexOf( COOKIE_DELIM );

        // position should start from REPLICA_ID_PREFIX_LEN or higher cause a cookie can be
        // like "rid=0,csn={csn}" or "rid=11,csn={csn}"
        if ( pos <= REPLICA_ID_PREFIX_LEN )
        {
            return false;
        }

        String replicaId = cookieString.substring( REPLICA_ID_PREFIX_LEN, pos );

        try
        {
            Integer.parseInt( replicaId );
        }
        catch ( NumberFormatException e )
        {
            LOG.debug( "Failed to parse the replica id {}", replicaId );
            return false;
        }

        if ( pos == cookieString.length() )
        {
            return false;
        }

        String csnString = cookieString.substring( pos + 1 + CSN_PREFIX_LEN );

        return Csn.isValid( csnString );
    }


    /**
     * returns the CSN present in cookie
     *
     * @param cookieString the cookie
     * @return The CSN
     */
    public static String getCsn( String cookieString )
    {
        int pos = cookieString.indexOf( COOKIE_DELIM );
        return cookieString.substring( pos + 1 + CSN_PREFIX_LEN );
    }


    /**
     * returns the replica id present in cookie
     *
     * @param cookieString  the cookie
     * @return The replica Id
     */
    public static int getReplicaId( String cookieString )
    {
        String replicaId = cookieString.substring( REPLICA_ID_PREFIX_LEN, cookieString.indexOf( COOKIE_DELIM ) );

        return Integer.parseInt( replicaId );
    }
}

public class DynamicBloomFilter extends Filter {
  /**
   * Threshold for the maximum number of key to record in a dynamic Bloom filter row.
   */
  private int nr;

  /**
   * The number of keys recorded in the current standard active Bloom filter.
   */
  private int currentNbRecord;

  /**
   * The matrix of Bloom filter.
   */
  private BloomFilter[] matrix;

  /**
   * Zero-args constructor for the serialization.
   */
  public DynamicBloomFilter() {}

  /**
   * Constructor.
   * <p>
   * Builds an empty Dynamic Bloom filter.
   *
   * @param vectorSize
   *          The number of bits in the vector.
   * @param nbHash
   *          The number of hash function to consider.
   * @param hashType
   *          type of the hashing function (see {@link org.apache.hadoop.util.hash.Hash}).
   * @param nr
   *          The threshold for the maximum number of keys to record in a dynamic Bloom filter row.
   */
  public DynamicBloomFilter(final int vectorSize, final int nbHash, final int hashType,
      final int nr) {
    super(vectorSize, nbHash, hashType);

    this.nr = nr;
    this.currentNbRecord = 0;

    matrix = new BloomFilter[1];
    matrix[0] = new BloomFilter(this.vectorSize, this.nbHash, this.hashType);
  }

  @Override
  public boolean add(final Key key) {
    if (key == null) {
      throw new NullPointerException("Key can not be null");
    }

    BloomFilter bf = getActiveStandardBF();

    if (bf == null) {
      addRow();
      bf = matrix[matrix.length - 1];
      currentNbRecord = 0;
    }

    boolean added = bf.add(key);

    if (added)
      currentNbRecord++;

    return added;
  }

  @Override
  public void and(final Filter filter) {
    if (filter == null || !(filter instanceof DynamicBloomFilter)
        || filter.vectorSize != this.vectorSize || filter.nbHash != this.nbHash) {
      throw new IllegalArgumentException("filters cannot be and-ed");
    }

    DynamicBloomFilter dbf = (DynamicBloomFilter) filter;

    if (dbf.matrix.length != this.matrix.length || dbf.nr != this.nr) {
      throw new IllegalArgumentException("filters cannot be and-ed");
    }

    for (int i = 0; i < matrix.length; i++) {
      matrix[i].and(dbf.matrix[i]);
    }
  }

  @Override
  public boolean membershipTest(final Key key) {
    if (key == null) {
      return true;
    }

    for (int i = 0; i < matrix.length; i++) {
      if (matrix[i].membershipTest(key)) {
        return true;
      }
    }

    return false;
  }

  @Override
  public void not() {
    for (int i = 0; i < matrix.length; i++) {
      matrix[i].not();
    }
  }

  @Override
  public void or(final Filter filter) {
    if (filter == null || !(filter instanceof DynamicBloomFilter)
        || filter.vectorSize != this.vectorSize || filter.nbHash != this.nbHash) {
      throw new IllegalArgumentException("filters cannot be or-ed");
    }

    DynamicBloomFilter dbf = (DynamicBloomFilter) filter;

    if (dbf.matrix.length != this.matrix.length || dbf.nr != this.nr) {
      throw new IllegalArgumentException("filters cannot be or-ed");
    }
    for (int i = 0; i < matrix.length; i++) {
      matrix[i].or(dbf.matrix[i]);
    }
  }

  @Override
  public void xor(final Filter filter) {
    if (filter == null || !(filter instanceof DynamicBloomFilter)
        || filter.vectorSize != this.vectorSize || filter.nbHash != this.nbHash) {
      throw new IllegalArgumentException("filters cannot be xor-ed");
    }
    DynamicBloomFilter dbf = (DynamicBloomFilter) filter;

    if (dbf.matrix.length != this.matrix.length || dbf.nr != this.nr) {
      throw new IllegalArgumentException("filters cannot be xor-ed");
    }

    for (int i = 0; i < matrix.length; i++) {
      matrix[i].xor(dbf.matrix[i]);
    }
  }

  @Override
  public String toString() {
    StringBuilder res = new StringBuilder();

    for (int i = 0; i < matrix.length; i++) {
      res.append(matrix[i]);
      res.append(Character.LINE_SEPARATOR);
    }
    return res.toString();
  }

  // Writable

  @Override
  public void write(final DataOutput out) throws IOException {
    super.write(out);
    out.writeInt(nr);
    out.writeInt(currentNbRecord);
    out.writeInt(matrix.length);
    for (int i = 0; i < matrix.length; i++) {
      matrix[i].write(out);
    }
  }

  @Override
  public void readFields(final DataInput in) throws IOException {

    super.readFields(in);

    nr = in.readInt();
    currentNbRecord = in.readInt();
    int len = in.readInt();
    matrix = new BloomFilter[len];
    for (int i = 0; i < matrix.length; i++) {
      matrix[i] = new BloomFilter();
      matrix[i].readFields(in);
    }
  }

  /**
   * Adds a new row to <i>this</i> dynamic Bloom filter.
   */
  private void addRow() {
    BloomFilter[] tmp = new BloomFilter[matrix.length + 1];

    for (int i = 0; i < matrix.length; i++) {
      tmp[i] = matrix[i];
    }

    tmp[tmp.length - 1] = new BloomFilter(vectorSize, nbHash, hashType);

    matrix = tmp;
  }

  /**
   * Returns the active standard Bloom filter in <i>this</i> dynamic Bloom filter.
   *
   * @return BloomFilter The active standard Bloom filter. <code>Null</code> otherwise.
   */
  private BloomFilter getActiveStandardBF() {
    if (currentNbRecord >= nr) {
      return null;
    }

    return matrix[matrix.length - 1];
  }
}

