public final class InstanceToNodeMetadata implements Function<Instance, NodeMetadata> {

   private final Map<Instance.Status, NodeMetadata.Status> toPortableNodeStatus;
   private final GroupNamingConvention nodeNamingConvention;
   private final LoadingCache<URI, Optional<Image>> diskURIToImage;
   private final Supplier<Map<URI, Hardware>> hardwares;
   private final Supplier<Map<URI, Location>> locationsByUri;

   @Inject InstanceToNodeMetadata(Map<Instance.Status, NodeMetadata.Status> toPortableNodeStatus,
                                  GroupNamingConvention.Factory namingConvention,
                                  LoadingCache<URI, Optional<Image>> diskURIToImage,
                                  @Memoized Supplier<Map<URI, Hardware>> hardwares,
                                  @Memoized Supplier<Map<URI, Location>> locationsByUri) {
      this.toPortableNodeStatus = toPortableNodeStatus;
      this.nodeNamingConvention = namingConvention.createWithoutPrefix();
      this.diskURIToImage = diskURIToImage;
      this.hardwares = hardwares;
      this.locationsByUri = locationsByUri;
   }

   @Override public NodeMetadata apply(Instance input) {
      String group = groupFromMapOrName(input.metadata().asMap(), input.name(), nodeNamingConvention);
      NodeMetadataBuilder builder = new NodeMetadataBuilder();

      Location zone = locationsByUri.get().get(input.zone());
      if (zone == null) {
         throw new IllegalStateException(
               String.format("zone %s not present in %s", input.zone(), locationsByUri.get().keySet()));
      }

      // The boot disk is the first disk. It may have been created from an image, so look it up.
      //
      // Note: This will be present if we created the node. In the future we could choose to make diskToSourceImage
      // a loading cache. That would be more expensive, but could ensure this isn't null.

      URI diskSource = input.disks().get(0).source();
      Optional<Image> image = diskURIToImage.getUnchecked(diskSource);

      Hardware hardware;
      if (isCustomMachineTypeURI(input.machineType())) {
         hardware = machineTypeURIToCustomHardware(input.machineType());
      }
      else {
         hardware = hardwares.get().get(input.machineType());
      }

      builder.id(input.selfLink().toString())
             .name(input.name())
             .providerId(input.id())
             .hostname(input.name())
             .location(zone)
             .imageId(image.isPresent() ? image.get().selfLink().toString() : null)
             .hardware(hardware)
             .status(input.status() != null ? toPortableNodeStatus.get(input.status()) : Status.UNRECOGNIZED)
             .tags(input.tags().items())
             .uri(input.selfLink())
             .userMetadata(input.metadata().asMap())
             .group(group)
             .privateAddresses(collectPrivateAddresses(input))
             .publicAddresses(collectPublicAddresses(input));
      return builder.build();
   }

   private List<String> collectPrivateAddresses(Instance input) {
      ImmutableList.Builder<String> privateAddressesBuilder = ImmutableList.builder();
      for (Instance.NetworkInterface networkInterface : input.networkInterfaces()) {
         if (networkInterface.networkIP() != null) {
            privateAddressesBuilder.add(networkInterface.networkIP());
         }
      }
      return privateAddressesBuilder.build();
   }

   private List<String> collectPublicAddresses(Instance input) {
      ImmutableList.Builder<String> publicAddressesBuilder = ImmutableList.builder();
      for (Instance.NetworkInterface networkInterface : input.networkInterfaces()) {
         for (Instance.NetworkInterface.AccessConfig accessConfig : networkInterface.accessConfigs()) {
            if (accessConfig.natIP() != null) {
               publicAddressesBuilder.add(accessConfig.natIP());
            }
         }
      }
      return publicAddressesBuilder.build();
   }

   public static boolean isCustomMachineTypeURI(URI machineType) {
      return machineType.toString().contains("machineTypes/custom");
   }

   public static Hardware machineTypeURIToCustomHardware(URI machineType) {
      String uri = machineType.toString();
      String values = uri.substring(uri.lastIndexOf('/') + 8);
      List<String> hardwareValues = Splitter.on('-')
            .trimResults()
            .splitToList(values);
      return new HardwareBuilder()
            .id(uri)
            .providerId(uri)
            .processor(new Processor(Double.parseDouble(hardwareValues.get(0)), 1.0))
            .ram(Integer.parseInt(hardwareValues.get(1)))
            .uri(machineType)
            .build();
   }
}

public final class SwitchStmt extends LabeledStatement {
  private static final long serialVersionUID = -7284973291082281855L;

  @ReflectiveCtor
  public SwitchStmt(
      FilePosition pos, String label, List<? extends ParseTreeNode> children) {
    super(pos, label, ParseTreeNode.class);
    createMutation().appendChildren(children).execute();
  }

  public SwitchStmt(
      FilePosition pos, String label,
      Expression valueExpr, List<SwitchCase> cases) {
    super(pos, label, ParseTreeNode.class);
    createMutation().appendChild(valueExpr).appendChildren(cases).execute();
  }

  @Override
  protected void childrenChanged() {
    super.childrenChanged();
    List<? extends ParseTreeNode> children = children();
    ParseTreeNode valueExpr = children.get(0);
    if (!(valueExpr instanceof Expression)) {
      throw new ClassCastException(
          "Expected " + Expression.class.getName() + " not "
          + valueExpr.getClass().getName());
    }
    for (ParseTreeNode node : children.subList(1, children.size())) {
      if (!(node instanceof SwitchCase)) {
        throw new ClassCastException(
            "Expected " + SwitchCase.class.getName() + " not "
            + (node != null ? node.getClass().getName() : "<null>"));
      }
    }
  }

  @Override
  public void continues(Map<String, List<ContinueStmt>> contsReaching) {
    // switch statements don't intercept continues
    for (ParseTreeNode child : children()) {
      if (child instanceof Statement) {
        ((Statement) child).continues(contsReaching);
      }
    }
  }

  @Override
  public boolean isTargetForContinue() { return false; }

  public void render(RenderContext rc) {
    TokenConsumer out = rc.getOut();
    out.mark(getFilePosition());
    String label = getRenderedLabel();
    if (null != label) {
      out.consume(label);
      out.consume(":");
    }
    Iterator<? extends ParseTreeNode> it = children().iterator();
    out.consume("switch");
    out.consume("(");
    it.next().render(rc);
    out.consume(")");
    out.consume("{");
    while (it.hasNext()) {
      SwitchCase caseStmt = (SwitchCase) it.next();
      caseStmt.render(rc);
    }
    out.mark(FilePosition.endOfOrNull(getFilePosition()));
    out.consume("}");
  }

  @Override
  public boolean isTerminal() {
    return true;
  }

  public boolean hasHangingConditional() { return false; }
}

public class ExternalValueList<K, V> implements BTreeValues<V>
{

	private BTree<K, V> btree;
	private int valueCount;
	private int firstNodeId;
	private int lastNodeId;

	public ExternalValueList( BTree<K, V> btree )
	{
		this.btree = btree;
		this.valueCount = 0;
		this.firstNodeId = -1;
		this.lastNodeId = -1;
	}

	public int getType( )
	{
		return EXTERNAL_VALUES;
	}

	public int getValueSize( )
	{
		return 12;
	}

	public int getFirstNodeId( )
	{
		return firstNodeId;
	}

	public int getLastNodeId( )
	{
		return lastNodeId;
	}

	public void read( DataInput input ) throws IOException
	{
		valueCount = input.readInt( );
		firstNodeId = input.readInt( );
		lastNodeId = input.readInt( );
	}

	public void write( DataOutput output ) throws IOException
	{
		output.writeInt( valueCount );
		output.writeInt( firstNodeId );
		output.writeInt( lastNodeId );
	}

	public Value<V> getFirstValue( ) throws IOException
	{
		if ( firstNodeId != -1 )
		{
			ValueNode<K, V> valueNode = btree.loadValueNode( firstNodeId );
			try
			{
				ValueEntry<V> entry = valueNode.getFirstEntry( );
				return new ExternalValue( valueNode, entry );
			}
			finally
			{
				valueNode.unlock( );
			}
		}
		return null;
	}

	public Value<V> getLastValue( ) throws IOException
	{
		if ( lastNodeId != -1 )
		{
			ValueNode<K, V> valueNode = btree.loadValueNode( lastNodeId );
			try
			{
				ValueEntry<V> entry = valueNode.getLastEntry( );
				return new ExternalValue( valueNode, entry );
			}
			finally
			{
				valueNode.unlock( );
			}
		}
		return null;
	}

	public int getValueCount( )
	{
		return valueCount;
	}

	public Value<V> append( BTreeValue<V> value ) throws IOException
	{
		if ( lastNodeId == -1 )
		{
			ValueNode<K, V> valueNode = btree.createValueNode( );
			try
			{
				firstNodeId = valueNode.getNodeId( );
				lastNodeId = valueNode.getNodeId( );
				ValueEntry<V> entry = valueNode.append( value );
				valueCount++;
				return new ExternalValue( valueNode, entry );
			}
			finally
			{
				valueNode.unlock( );
			}
		}

		ValueNode<K, V> lastNode = btree.loadValueNode( lastNodeId );
		try
		{
			int valueSize = btree.getValueSize( value );
			int nodeSize = lastNode.getNodeSize( );
			if ( nodeSize + valueSize <= BTreeConstants.MAX_NODE_SIZE )
			{
				// append it to the new node
				ValueEntry<V> entry = lastNode.append( value );
				valueCount++;
				return new ExternalValue( lastNode, entry );
			}

			// append the value into the new node
			ValueNode<K, V> valueNode = btree.createValueNode( );
			try
			{
				ValueEntry<V> entry = valueNode.append( value );
				valueNode.setPrevNodeId( lastNode.getNodeId( ) );
				lastNode.setNextNodeId( valueNode.getNodeId( ) );
				lastNode.setDirty( true );
				lastNodeId = valueNode.getNodeId( );
				valueCount++;
				return new ExternalValue( valueNode, entry );
			}
			finally
			{
				valueNode.unlock( );
			}
		}
		finally
		{
			lastNode.unlock( );
		}
	}

	class ExternalValue implements Value<V>
	{

		ValueNode<K, V> node;
		ValueEntry<V> entry;

		ExternalValue( ValueNode<K, V> node, ValueEntry<V> entry )
		{
			this.node = node;
			this.entry = entry;
		}

		public Value<V> getPrev( ) throws IOException
		{
			ValueEntry<V> prev = entry.getPrev( );
			if ( prev != null )
			{
				return new ExternalValue( node, prev );
			}

			int prevNodeId = node.getPrevNodeId( );
			if ( prevNodeId != -1 )
			{
				ValueNode<K, V> prevNode = btree.loadValueNode( prevNodeId );
				try

				{
					prev = prevNode.getLastEntry( );
					if ( prev != null )
					{
						return new ExternalValue( prevNode, prev );
					}
				}
				finally
				{
					prevNode.unlock( );
				}
			}
			return null;
		}

		public Value<V> getNext( ) throws IOException
		{
			ValueEntry<V> next = entry.getNext( );
			if ( next != null )
			{
				return new ExternalValue( node, next );
			}
			int nextNodeId = node.getNextNodeId( );
			if ( nextNodeId != -1 )
			{
				ValueNode<K, V> nextNode = btree.loadValueNode( nextNodeId );
				try
				{
					next = nextNode.getFirstEntry( );
					if ( next != null )
					{
						return new ExternalValue( nextNode, next );
					}
				}
				finally
				{
					nextNode.unlock( );
				}
			}
			return null;
		}

		public BTreeValue<V> getValue( )
		{
			return entry.getValue( );
		}
	}
}

