public class PerforceScmProvider
    extends AbstractScmProvider
{
    private static final String[] PROTOCOLS = { "tcp", "tcp4", "tcp6", "tcp46", "tcp64", "ssl", "ssl4", "ssl6",
        "ssl46", "ssl64" };

