private static void walker(List<List<String>> finalResult, final List<List<String>> input,
    List<String> listSoFar, final int level) throws SemanticException {
  // Base case.
  if (level == (input.size() - 1)) {
    assert (input.get(level) != null) : "Unique skewed element list has null list in " + level
        + "th position.";
    for (String v : input.get(level)) {
      List<String> oneCompleteIndex = new ArrayList<String>(listSoFar);
      oneCompleteIndex.add(v);
      finalResult.add(oneCompleteIndex);
    }
    return;
  }

  // Recursive.
  for (String v : input.get(level)) {
    List<String> clonedListSoFar = new ArrayList<String>(listSoFar);
    clonedListSoFar.add(v);
    int nextLevel = level + 1;
    walker(finalResult, input, clonedListSoFar, nextLevel);
  }
}

class LinuxThread implements ThreadProxy {
    private LinuxDebugger debugger;
    private int           lwp_id;

    /** The address argument must be the address of the _thread_id in the
        OSThread. It's value is result ::gettid() call. */
    LinuxThread(LinuxDebugger debugger, Address addr) {
        this.debugger = debugger;
        // FIXME: size of data fetched here should be configurable.
        // However, making it so would produce a dependency on the "types"
        // package from the debugger package, which is not desired.
        int pid = (int)addr.getCIntegerAt(0, 4, true);
        if (debugger instanceof LinuxDebuggerLocal) {
            int hostPID = ((LinuxDebuggerLocal)debugger).getHostPID(pid);
            // Debuggee is not running in the container
            if (hostPID != -1) {
                pid = hostPID;
            }
        }
        this.lwp_id = pid;

    }

    LinuxThread(LinuxDebugger debugger, long id) {
        this.debugger = debugger;
        this.lwp_id = (int) id;
    }

    public boolean equals(Object obj) {
        if ((obj == null) || !(obj instanceof LinuxThread)) {
            return false;
        }

        return (((LinuxThread) obj).lwp_id == lwp_id);
    }

    public int hashCode() {
        return lwp_id;
    }

    public String toString() {
        return Integer.toString(lwp_id);
    }

    public ThreadContext getContext() throws IllegalThreadStateException {
        long[] data = debugger.getThreadIntegerRegisterSet(lwp_id);
        ThreadContext context = LinuxThreadContextFactory.createThreadContext(debugger);
        for (int i = 0; i < data.length; i++) {
            context.setRegister(i, data[i]);
        }
        return context;
    }

    public boolean canSetContext() throws DebuggerException {
        return false;
    }

    public void setContext(ThreadContext context)
      throws IllegalThreadStateException, DebuggerException {
        throw new DebuggerException("Unimplemented");
    }
}

