public class StringBlob {

    private byte[] rawBlob;
    private String string;

    /**
     * Construct string blob from compressed byte array
     *
     * @param byteArray the byte array
     */
    public StringBlob(byte[] byteArray) {
        this.rawBlob = ByteArrayUtils.weakIntern(byteArray);
    }

    /**
     * Construct StringBlob with uncompressed string
     *
     * @param inputString the string
     */
    public StringBlob(String inputString) {
        this.string = StringUtils.intern(inputString);
        this.rawBlob = null;
    }

    /**
     * Set string
     *
     * @param str the string
     */
    public void setString(String str) {
        this.string = StringUtils.intern(str);
        this.rawBlob = null;
    }

    /**
     * Get uncompressed string
     *
     * @return uncompressed string
     */
    public String getString() {
        if (string != null) {
            return string;
        }
        if (rawBlob == null) {
            return null;
        }
        try {
            DataInputStream dais = new DataInputStream(new ByteArrayInputStream(rawBlob));
            CompressionCodec codec = CodecFactory.getDeCompressionCodec(dais);
            if (codec != null) {
                string = StringUtils.intern(codec.decompressToString(dais));
            }
            else {
                string = StringUtils.intern((new String(rawBlob, CodecFactory.UTF_8_ENCODING)));
            }
            dais.close();

        }
        catch (IOException ex) {
            throw new RuntimeException(ex);
        }
        rawBlob = null;
        return string;
    }

    /**
     * Get raw blob
     *
     * @return raw blob
     */
    public byte[] getRawBlob() {
        if (rawBlob != null) {
            return rawBlob;
        }
        if (string == null) {
            return null;
        }
        if (CodecFactory.isCompressionEnabled()) {
            byte[] bytes = CodecFactory.getHeaderBytes();
            try {
                rawBlob = ByteArrayUtils.weakIntern(CodecFactory.getCompressionCodec().compressString(bytes, string));
            }
            catch (IOException ex) {
                throw new RuntimeException(ex);
            }
        }
        else {
            rawBlob = ByteArrayUtils.weakIntern(string.getBytes(Charsets.UTF_8));
        }
        return rawBlob;
    }

}

public class MutableAlteredFiles extends AlteredFiles {

  /**
   * Parses raw git diff string and creates advanced representation.
   *
   * @param project the project under diff operation
   * @param diff plain result of git diff operation
   */
  public MutableAlteredFiles(Project project, String diff) {
    super(project, diff);
  }

  /**
   * Creates mutable altered files list based on changes from another project.
   *
   * @param project the project under diff operation
   * @param alteredFiles changes from another project
   */
  public MutableAlteredFiles(Project project, AlteredFiles alteredFiles) {
    super(project, "");
    this.alteredFilesStatuses.putAll(alteredFiles.alteredFilesStatuses);
    this.alteredFilesList.addAll(alteredFiles.alteredFilesList);
  }

  /**
   * Creates an empty list of altered files.
   *
   * @param project the project under diff operation
   */
  public MutableAlteredFiles(Project project) {
    super(project, "");
  }

  /**
   * Adds or updates a file in altered file list. If given file is already exists does nothing.
   *
   * @param file full path to file and its name relatively to project root
   * @param status git status of the file
   * @return true if file was added or updated and false if the file is already exists in this list
   */
  public boolean addFile(String file, Status status) {
    if (status.equals(alteredFilesStatuses.get(file))) {
      return false;
    }

    if (alteredFilesStatuses.put(file, status) == null) {
      // it's not a status change, new file was added
      alteredFilesList.add(file);
    }
    return true;
  }

  /**
   * Removes given file from the altered files list. If given file isn't present does nothing.
   *
   * @param file full path to file and its name relatively to project root
   * @return true if the file was deleted and false otherwise
   */
  public boolean removeFile(String file) {
    alteredFilesStatuses.remove(file);
    return alteredFilesList.remove(file);
  }
}

private NameRegion[] findLinkComponentsInClosure(ClosureExpression firstArg,
        int offset) {
    if (! (firstArg.getCode() instanceof BlockStatement)) {
        return null;
    }

    BlockStatement code = (BlockStatement) firstArg.getCode();
    if (code.getStatements() == null) {
        return null;
    }
    NameRegion controllerName = null;
    NameRegion actionName = null;
    NameRegion viewName = null;

    for (Statement state : code.getStatements()) {
        if (state instanceof ExpressionStatement) {
            if (((ExpressionStatement) state).getExpression() instanceof BinaryExpression) {
                BinaryExpression bexpr = (BinaryExpression) ((ExpressionStatement) state).getExpression();
                Expression left = bexpr.getLeftExpression();
                if (bexpr.getOperation().getText().equals("=") && left instanceof VariableExpression) {
                    Expression right = bexpr.getRightExpression();
                    Region region;
                    if (right.getStart() <= offset && right.getEnd() >= offset) {
                        region = new Region(right.getStart(), right.getLength());
                    } else {
                        region = null;
                    }

                    String name = left.getText();
                    if (name.equals("controller")) {
                        controllerName = new NameRegion(right.getText(), region);
                    } else if (name.equals("action")) {
                        actionName = new NameRegion(right.getText(), region);
                    } else if (name.equals("view")) {
                        viewName = new NameRegion(right.getText(), region);
                    }
                }
            }
        }
    }
    return new NameRegion[] { controllerName, actionName, viewName };
}

protected Item parseItem(Element rssRoot, Element eItem) {
    Item item = super.parseItem(rssRoot,eItem);
    Element e = eItem.getChild("description", getRSSNamespace());
    if (e!=null) {
        item.setDescription(parseItemDescription(rssRoot,e));
    }
    Element ce = eItem.getChild("encoded", getContentNamespace());
    if (ce != null) {
        Content content = new Content();
        content.setType(Content.HTML);
        content.setValue(ce.getText());
        item.setContent(content);
    }
    return item;
}

