@Override
public BytesRef next() {
  if (input.position() < end) {
    try {
      int code = input.readVInt();
      boolean newField = (code & 1) != 0;
      if (newField) {
        field = input.readString();
      }
      int prefix = code >>> 1;
      int suffix = input.readVInt();
      readTermBytes(prefix, suffix);
      return bytes;
    } catch (IOException e) {
      throw new RuntimeException(e);
    }
  } else {
    field = null;
    return null;
  }
}

public final class HelloREEFEnvironment {

  private static final Logger LOG = Logger.getLogger(HelloREEFEnvironment.class.getName());

  private static final Configuration DRIVER_CONFIG = DriverConfiguration.CONF
      .set(DriverConfiguration.DRIVER_IDENTIFIER, "HelloREEF_Env")
      .set(DriverConfiguration.GLOBAL_LIBRARIES, EnvironmentUtils.getClassLocation(HelloDriver.class))
      .set(DriverConfiguration.ON_DRIVER_STARTED, HelloDriver.StartHandler.class)
      .set(DriverConfiguration.ON_EVALUATOR_ALLOCATED, HelloDriver.EvaluatorAllocatedHandler.class)
      .build();

  private static final Configuration LOCAL_DRIVER_MODULE = LocalDriverConfiguration.CONF
      .set(LocalDriverConfiguration.RUNTIME_NAMES, RuntimeIdentifier.RUNTIME_NAME)
      .set(LocalDriverConfiguration.CLIENT_REMOTE_IDENTIFIER, ClientRemoteIdentifier.NONE)
      .set(LocalDriverConfiguration.JOB_IDENTIFIER, "LOCAL_ENV_DRIVER_TEST")
      .set(LocalDriverConfiguration.ROOT_FOLDER, "./REEF_LOCAL_RUNTIME")
      .set(LocalDriverConfiguration.MAX_NUMBER_OF_EVALUATORS, 2)
      .set(LocalDriverConfiguration.JVM_HEAP_SLACK, 0.0)
      .build();

  private static final Configuration ENVIRONMENT_CONFIG =
      Tang.Factory.getTang().newConfigurationBuilder()
          .bindNamedParameter(RemoteConfiguration.ManagerName.class, "REEF_ENVIRONMENT")
          .bindNamedParameter(RemoteConfiguration.MessageCodec.class, REEFMessageCodec.class)
          .build();

  /**
   * Start Hello REEF job with Driver and Client sharing the same process.
   *
   * @param args command line parameters - not used.
   * @throws InjectionException configuration error.
   */
  public static void main(final String[] args) throws InjectionException {

    try (final REEFEnvironment reef = REEFEnvironment.fromConfiguration(
        LOCAL_DRIVER_MODULE, DRIVER_CONFIG, ENVIRONMENT_CONFIG)) {
      reef.run();
      final ReefServiceProtos.JobStatusProto status = reef.getLastStatus();
      LOG.log(Level.INFO, "REEF job completed: {0}", status);
    }
  }

  /**
   * Empty private constructor to prohibit instantiation of all-static class.
   */
  private HelloREEFEnvironment() {
  }
}

@Override
public Serializable getRoutingObject(EntryOperation opDetails) {
  Date date = (Date) opDetails.getKey();
  Calendar cal = Calendar.getInstance();
  cal.setTime(date);
  int month = cal.get(Calendar.MONTH);
  // if(true){
  // return month;
  // }
  switch (month) {
    case 0:
      return "January";
    case 1:
      return "February";
    case 2:
      return "March";
    case 3:
      return "April";
    case 4:
      return "May";
    case 5:
      return "June";
    case 6:
      return "July";
    case 7:
      return "August";
    case 8:
      return "September";
    case 9:
      return "October";
    case 10:
      return "November";
    case 11:
      return "December";
    default:
      return null;
  }

}

final int readIntBigEndian() throws SQLServerException {
    if (payloadOffset + 4 <= currentPacket.payloadLength) {
        int value = Util.readIntBigEndian(currentPacket.payload, payloadOffset);
        payloadOffset += 4;
        return value;
    }

    return Util.readIntBigEndian(readWrappedBytes(4), 0);
}

private Set<Taglet> collectTaglets()
    throws MavenReportException
{
    Set<Taglet> result = new LinkedHashSet<>();

    if ( includeDependencySources )
    {
        try
        {
            resolveDependencyBundles();
        }
        catch ( IOException e )
        {
            throw new MavenReportException(
                "Failed to resolve javadoc bundles from dependencies: " + e.getMessage(), e );
        }

        if ( isNotEmpty( dependencyJavadocBundles ) )
        {
            for ( JavadocBundle bundle : dependencyJavadocBundles )
            {
                JavadocOptions options = bundle.getOptions();
                if ( options != null && isNotEmpty( options.getTaglets() ) )
                {
                    result.addAll( options.getTaglets() );
                }
            }
        }
    }

    if ( taglets != null && taglets.length > 0 )
    {
        result.addAll( Arrays.asList( taglets ) );
    }

    return result;
}

public int lastIndexOf(Object o) {
    int index = size;
    if (o == null) {
        for (Node<E> x = last; x != null; x = x.prev) {
            index--;
            if (x.item == null)
                return index;
        }
    } else {
        for (Node<E> x = last; x != null; x = x.prev) {
            index--;
            if (o.equals(x.item))
                return index;
        }
    }
    return -1;
}

