@Contract(threading = ThreadingBehavior.IMMUTABLE)
public class RequestValidateHost implements HttpRequestInterceptor {

    public RequestValidateHost() {
        super();
    }

    @Override
    public void process(final HttpRequest request, final EntityDetails entity, final HttpContext context)
            throws HttpException, IOException {
        Args.notNull(request, "HTTP request");

        final Header header = request.getHeader(HttpHeaders.HOST);
        if (header != null) {
            final URIAuthority authority;
            try {
                authority = URIAuthority.create(header.getValue());
            } catch (final URISyntaxException ex) {
                throw new ProtocolException(ex.getMessage(), ex);
            }
            request.setAuthority(authority);
        } else {
            final ProtocolVersion version = request.getVersion() != null ? request.getVersion() : HttpVersion.HTTP_1_1;
            if (version.greaterEquals(HttpVersion.HTTP_1_1)) {
                throw new ProtocolException("Host header is absent");
            }
        }
    }

}

@Nullable
public Interceptor getEntityInterceptor() throws IllegalStateException, BeansException {
	if (this.entityInterceptor instanceof Interceptor) {
		return (Interceptor) this.entityInterceptor;
	}
	else if (this.entityInterceptor instanceof String) {
		if (this.beanFactory == null) {
			throw new IllegalStateException("Cannot get entity interceptor via bean name if no bean factory set");
		}
		String beanName = (String) this.entityInterceptor;
		return this.beanFactory.getBean(beanName, Interceptor.class);
	}
	else {
		return null;
	}
}

public static class put<I extends AsyncIface> extends org.apache.thrift.AsyncProcessFunction<I, put_args, Void> {
  public put() {
    super("put");
  }

  public put_args getEmptyArgsInstance() {
    return new put_args();
  }

  public org.apache.thrift.async.AsyncMethodCallback<Void> getResultHandler(final org.apache.thrift.server.AbstractNonblockingServer.AsyncFrameBuffer fb, final int seqid) {
    final org.apache.thrift.AsyncProcessFunction fcall = this;
    return new org.apache.thrift.async.AsyncMethodCallback<Void>() {
      public void onComplete(Void o) {
        put_result result = new put_result();
        try {
          fcall.sendResponse(fb, result, org.apache.thrift.protocol.TMessageType.REPLY,seqid);
        } catch (org.apache.thrift.transport.TTransportException e) {
          _LOGGER.error("TTransportException writing to internal frame buffer", e);
          fb.close();
        } catch (java.lang.Exception e) {
          _LOGGER.error("Exception writing to internal frame buffer", e);
          onError(e);
        }
      }
      public void onError(java.lang.Exception e) {
        byte msgType = org.apache.thrift.protocol.TMessageType.REPLY;
        org.apache.thrift.TSerializable msg;
        put_result result = new put_result();
        if (e instanceof TIOError) {
          result.io = (TIOError) e;
          result.setIoIsSet(true);
          msg = result;
        } else if (e instanceof org.apache.thrift.transport.TTransportException) {
          _LOGGER.error("TTransportException inside handler", e);
          fb.close();
          return;
        } else if (e instanceof org.apache.thrift.TApplicationException) {
          _LOGGER.error("TApplicationException inside handler", e);
          msgType = org.apache.thrift.protocol.TMessageType.EXCEPTION;
          msg = (org.apache.thrift.TApplicationException)e;
        } else {
          _LOGGER.error("Exception inside handler", e);
          msgType = org.apache.thrift.protocol.TMessageType.EXCEPTION;
          msg = new org.apache.thrift.TApplicationException(org.apache.thrift.TApplicationException.INTERNAL_ERROR, e.getMessage());
        }
        try {
          fcall.sendResponse(fb,msg,msgType,seqid);
        } catch (java.lang.Exception ex) {
          _LOGGER.error("Exception writing to internal frame buffer", ex);
          fb.close();
        }
      }
    };
  }

  protected boolean isOneway() {
    return false;
  }

  public void start(I iface, put_args args, org.apache.thrift.async.AsyncMethodCallback<Void> resultHandler) throws org.apache.thrift.TException {
    iface.put(args.table, args.tput,resultHandler);
  }
}

@Override
public boolean hasReferences() {
  // Grab the read lock here, because we need to ensure that: only when the atomic
  // replaceStoreFiles(..) finished, we can get all the complete store file list.
  this.lock.readLock().lock();
  try {
    // Merge the current store files with compacted files here due to HBASE-20940.
    Collection<HStoreFile> allStoreFiles = new ArrayList<>(getStorefiles());
    allStoreFiles.addAll(getCompactedFiles());
    return StoreUtils.hasReferences(allStoreFiles);
  } finally {
    this.lock.readLock().unlock();
  }
}

public class EscherBitmapBlip extends EscherBlipRecord {
    public static final short RECORD_ID_JPEG = (short) 0xF018 + 5;
    public static final short RECORD_ID_PNG = (short) 0xF018 + 6;
    public static final short RECORD_ID_DIB = (short) 0xF018 + 7;

    private static final int HEADER_SIZE = 8;

    private final byte[] field_1_UID = new byte[16];
    private byte field_2_marker = (byte) 0xFF;

    @Override
    public int fillFields(byte[] data, int offset, EscherRecordFactory recordFactory) {
        int bytesAfterHeader = readHeader( data, offset );
        int pos = offset + HEADER_SIZE;

        System.arraycopy( data, pos, field_1_UID, 0, 16 ); pos += 16;
        field_2_marker = data[pos]; pos++;

        setPictureData(data, pos, bytesAfterHeader - 17);

        return bytesAfterHeader + HEADER_SIZE;
    }

    @Override
    public int serialize( int offset, byte[] data, EscherSerializationListener listener ) {
        listener.beforeRecordSerialize(offset, getRecordId(), this);

        LittleEndian.putShort( data, offset, getOptions() );
        LittleEndian.putShort( data, offset + 2, getRecordId() );
        LittleEndian.putInt( data, offset + 4, getRecordSize() - HEADER_SIZE );
        int pos = offset + HEADER_SIZE;

        System.arraycopy( field_1_UID, 0, data, pos, 16 );
        data[pos + 16] = field_2_marker;
        byte[] pd = getPicturedata();
        System.arraycopy( pd, 0, data, pos + 17, pd.length );

        listener.afterRecordSerialize(offset + getRecordSize(), getRecordId(), getRecordSize(), this);
        return HEADER_SIZE + 16 + 1 + pd.length;
    }

    @Override
    public int getRecordSize() {
        return 8 + 16 + 1 + getPicturedata().length;
    }

    /**
     * Gets the first MD4, that specifies the unique identifier of the
     * uncompressed blip data
     *
     * @return the first MD4
     */
    public byte[] getUID() {
        return field_1_UID;
    }

    /**
     * Sets the first MD4, that specifies the unique identifier of the
     * uncompressed blip data
     *
     * @param field_1_UID the first MD4
     */
    public void setUID( byte[] field_1_UID ) {
        if (field_1_UID == null || field_1_UID.length != 16) {
            throw new IllegalArgumentException("field_1_UID must be byte[16]");
        }
        System.arraycopy(field_1_UID, 0, this.field_1_UID , 0, 16);
    }

    /**
     * Gets an unsigned integer that specifies an application-defined internal
     * resource tag. This value MUST be 0xFF for external files.
     *
     * @return the marker
     */
    public byte getMarker() {
        return field_2_marker;
    }

    /**
     * Sets an unsigned integer that specifies an application-defined internal
     * resource tag. This value MUST be 0xFF for external files.
     *
     * @param field_2_marker the marker
     */
    public void setMarker( byte field_2_marker ) {
        this.field_2_marker = field_2_marker;
    }

    @Override
    protected Object[][] getAttributeMap() {
        return new Object[][] {
            { "Marker", field_2_marker },
            { "Extra Data", getPicturedata() }
        };
    }
}

