@DefaultAnnotation(NonNull.class)
public interface MongoDocumentUpdater<T, V> {
    public default void update(final T key, final DocumentMutator<V> mutator) throws IndexingException {
        requireNonNull(mutator);

        // Fetch the current state of the Entity.
        boolean completed = false;
        while(!completed) {
            //this cast is safe since the mutator interface is defined below to use Optional<V>
            final Optional<V> old = getOld(key);
            final Optional<V> updated = mutator.apply(old);

            final boolean doWork = updated.isPresent();
            if(doWork) {
                if(!old.isPresent()) {
                    create(updated.get());
                } else {
                    update(old.get(), updated.get());
                }
            }
            completed = true;
        }
    }

    Optional<V> getOld(T key) throws IndexingException;

    void create(final V newObj) throws IndexingException;

    void update(final V old, final V updated) throws IndexingException;

    /**
     * Implementations of this interface are used to update the state of a
     * {@link MongoDocumentUpdater#V} in unison with a {@link MongoDocumentUpdater}.
     * </p>
     * This table describes what the updater will do depending on if the object
     * exists and if an updated object is returned.
     * </p>
     * <table border="1px">
     *     <tr><th>Object Provided</th><th>Update Returned</th><th>Effect</th></tr>
     *     <tr>
     *         <td>true</td>
     *         <td>true</td>
     *         <td>The old Object will be updated using the returned state.</td>
     *     </tr>
     *     <tr>
     *         <td>true</td>
     *         <td>false</td>
     *         <td>No work is performed.</td>
     *     </tr>
     *     <tr>
     *         <td>false</td>
     *         <td>true</td>
     *         <td>A new Object will be created using the returned state.</td>
     *     </tr>
     *     <tr>
     *         <td>false</td>
     *         <td>false</td>
     *         <td>No work is performed.</td>
     *     </tr>
     * </table>
     */
    public interface DocumentMutator<V> extends Function<Optional<V>, Optional<V>> { }
}

private Atom getSTTSAtom() {
    Atom atom = new Atom("stts", (byte)0, 0);
    int numAudioFrames = mFrameSize.length - 1;
    atom.setData(new byte[] {
            0, 0, 0, 0x02,  // entry count
            0, 0, 0, 0x01,  // first frame contains no audio
            0, 0, 0, 0,
            (byte)((numAudioFrames >> 24) & 0xFF), (byte)((numAudioFrames >> 16) & 0xFF),
            (byte)((numAudioFrames >> 8) & 0xFF), (byte)(numAudioFrames & 0xFF),
            0, 0, 0x04, 0,  // delay between frames = 1024 samples (cf. timescale = Fs)
    });
    return atom;
}

public class CreateProcedureAction extends CayenneAction {

    public CreateProcedureAction(Application application) {
        super(getActionName(), application);
    }

    public static String getActionName() {
        return "Create Stored Procedure";
    }

    /**
     * Fires events when a procedure was added
     */
    static void fireProcedureEvent(Object src, ProjectController mediator, DataMap dataMap, Procedure procedure) {
        mediator.fireProcedureEvent(new ProcedureEvent(src, procedure, MapEvent.ADD));
        mediator.fireProcedureDisplayEvent(new ProcedureDisplayEvent(src, procedure, mediator.getCurrentDataMap(),
                (DataChannelDescriptor) mediator.getProject().getRootNode()));
    }

    public void performAction(ActionEvent e) {
        ProjectController mediator = getProjectController();
        DataMap map = mediator.getCurrentDataMap();

        Procedure procedure = new Procedure();
        procedure.setName(NameBuilder.builder(procedure, map).name());
        createProcedure(map, procedure);

        application.getUndoManager().addEdit(new CreateProcedureUndoableEdit(map, procedure));
    }

    public void createProcedure(DataMap map, Procedure procedure) {
        ProjectController mediator = getProjectController();
        procedure.setSchema(map.getDefaultSchema());
        procedure.setCatalog(map.getDefaultCatalog());
        map.addProcedure(procedure);
        fireProcedureEvent(this, mediator, map, procedure);
    }

    /**
     * Returns <code>true</code> if path contains a DataMap object.
     */
    public boolean enableForPath(ConfigurationNode object) {
        if (object == null) {
            return false;
        }

        return ((Procedure) object).getDataMap() != null;
    }

    public String getIconName() {
        return "icon-stored-procedure.png";
    }
}

public final class ValueInstance extends TransientInstance
    implements CompositeInstance, MixinsInstance
{
    public ValueInstance( ValueModel compositeModel, Object[] mixins, ValueStateInstance state )
    {
        super( compositeModel, mixins, state );
    }

    /**
     * Perform equals with {@code o} argument.
     * <p>
     * The definition of equals() for the Value is that if both the state and descriptor are equal,
     * then the values are equal.
     * </p>
     *
     * @param o The other object to compare.
     *
     * @return Returns a {@code boolean} indicator whether this object is equals the other.
     */
    @Override
    public boolean equals( Object o )
    {
        if( this == o )
        {
            return true;
        }
        if( o == null || !Proxy.isProxyClass( o.getClass() ) )
        {
            return false;
        }

        try
        {
            ValueInstance that = (ValueInstance) Proxy.getInvocationHandler( o );
            // Descriptor equality
            if( !descriptor().equals( that.descriptor() ) )
            {
                return false;
            }
            // State equality
            return state.equals( that.state );
        }
        catch( ClassCastException e )
        {
            return false;
        }
    }

    @Override
    public ValueStateInstance state()
    {
        return (ValueStateInstance) state;
    }

    @Override
    public ValueModel descriptor()
    {
        return (ValueModel) compositeModel;
    }

    /**
     * When a ValueBuilder is about to start, ensure that all state has builder infos, i.e. they are mutable.
     */
    public void prepareToBuild()
    {
        descriptor().state().properties().forEach(
            descriptor -> ( (PropertyInstance<Object>) state.propertyFor( descriptor.accessor() ) )
                .prepareToBuild( descriptor ) );

        descriptor().state().associations().forEach(
            descriptor -> state().associationFor( descriptor.accessor() )
                                 .setAssociationInfo( descriptor.builderInfo() ) );

        descriptor().state().manyAssociations().forEach(
            descriptor -> state().manyAssociationFor( descriptor.accessor() )
                                 .setAssociationInfo( descriptor.builderInfo() ) );

        descriptor().state().namedAssociations().forEach(
            descriptor -> state().namedAssociationFor( descriptor.accessor() )
                                 .setAssociationInfo( descriptor.builderInfo() ) );
    }

    /**
     * When a ValueBuilder is finished and is about to instantiate a Value, call this to ensure that the state has correct
     * settings, i.e. is immutable.
     */
    public void prepareBuilderState()
    {
        descriptor().state().properties().forEach(
            descriptor -> ( (PropertyInstance<Object>) state.propertyFor( descriptor.accessor() ) )
                .prepareBuilderState( descriptor ) );

        descriptor().state().associations().forEach(
            descriptor -> state().associationFor( descriptor.accessor() ).setAssociationInfo( descriptor ) );

        descriptor().state().manyAssociations().forEach(
            descriptor -> state().manyAssociationFor( descriptor.accessor() ).setAssociationInfo( descriptor ) );

        descriptor().state().namedAssociations().forEach(
            descriptor -> state().namedAssociationFor( descriptor.accessor() ).setAssociationInfo( descriptor ) );
    }

    /**
     * Calculate hash code.
     *
     * @return the hashcode of this instance.
     */
    @Override
    public int hashCode()
    {
        int hash = compositeModel.hashCode() * 23; // Descriptor
        return hash + state.hashCode() * 5; // State
    }

    public String toJsonString()
    {
        Serializer serialization = ( (ModuleSpi) module().instance() ).serialization();
        if( serialization != null )
        {
            return serialization.serialize( Serializer.Options.NO_TYPE_INFO, proxy() );
        }
        return null;
    }

    @Override
    public String toString()
    {
        String json = toJsonString();
        if( json != null )
        {
            return json;
        }
        return "ValueInstance{" +
               "mixins=" + Arrays.toString( mixins ) +
               ", state=" + state +
               ", compositeModel=" + compositeModel +
               '}';
    }
}

@Singleton
public class ProjectClasspathChangeListener implements IElementChangedListener {

	private final static Logger log = Logger.getLogger(ProjectClasspathChangeListener.class);

	@Inject
	private IWorkspace workspace;

	@Inject
	@Deprecated
	private org.eclipse.xtext.builder.impl.BuildScheduler buildManager;

	@Inject 
	private IDirtyStateManager dirtyStateManager;

	@Inject 
	private JavaProjectClasspathChangeAnalyzer javaProjectClasspathChangeAnalyzer;

	@Override
	public void elementChanged(ElementChangedEvent event) {
		if (workspace != null && workspace.isAutoBuilding()) {
			try {
				if (event.getDelta() != null) {
					Set<IJavaProject> javaProjects = getJavaProjectsWithClasspathChange(event.getDelta());
					if (!javaProjects.isEmpty()) {
						Set<IProject> projects = FluentIterable.from(javaProjects)
								.filter(Predicates.notNull())
								.transform(IJavaProject::getProject).toSet();
						dirtyStateManager.notifyListeners(new CoarseGrainedChangeEvent());
						scheduleBuildIfNecessary(projects);
					}
				}
			} catch (WrappedException e) {
				log.error(e.getCause().getMessage(), e.getCause());
			} catch (RuntimeException e) {
				log.error(e.getMessage(), e);
			}
		}
	}

	@Deprecated
	private void scheduleBuildIfNecessary(Set<IProject> projects) {
		buildManager.scheduleBuildIfNecessary(projects, IBuildFlag.FORGET_BUILD_STATE_ONLY);
	}

	protected Set<IJavaProject> getJavaProjectsWithClasspathChange(IJavaElementDelta delta) {
		return javaProjectClasspathChangeAnalyzer.getJavaProjectsWithClasspathChange(delta);
	}

}

