private QuantileBuffer<T> collapse(Iterable<QuantileBuffer<T>> buffers) {
  int newLevel = 0;
  long newWeight = 0;
  for (QuantileBuffer<T> buffer : buffers) {
    // As presented in the paper, there should always be at least two
    // buffers of the same (minimal) level to collapse, but it is possible
    // to violate this condition when combining buffers from independently
    // computed shards.  If they differ we take the max.
    newLevel = Math.max(newLevel, buffer.level + 1);
    newWeight += buffer.weight;
  }
  List<T> newElements = interpolate(buffers, bufferSize, newWeight, offset(newWeight));
  return new QuantileBuffer<>(newLevel, newWeight, newElements);
}

private class JobRunner implements Runnable {

    private final AbstractExecutable executable;

    public JobRunner(AbstractExecutable executable) {
        this.executable = executable;
    }

    @Override
    public void run() {
        try (SetThreadName ignored = new SetThreadName("Scheduler %s Job %s",
                System.identityHashCode(DistributedScheduler.this), executable.getId())) {
            if (jobLock.lock(getLockPath(executable.getId()))) {
                logger.info(executable.toString() + " scheduled in server: " + serverName);

                context.addRunningJob(executable);
                jobWithLocks.add(executable.getId());
                executable.execute(context);
            }
        } catch (ExecuteException e) {
            logger.error("ExecuteException job:" + executable.getId() + " in server: " + serverName, e);
        } catch (Exception e) {
            logger.error("unknown error execute job:" + executable.getId() + " in server: " + serverName, e);
        } finally {
            context.removeRunningJob(executable);
            releaseJobLock(executable);
            // trigger the next step asap
            fetcherPool.schedule(fetcher, 0, TimeUnit.SECONDS);
        }
    }

    //release job lock when job state is ready or running and the job server keep the cube lock.
    private void releaseJobLock(AbstractExecutable executable) {
        if (executable instanceof DefaultChainedExecutable) {
            ExecutableState state = executable.getStatus();

            if (state != ExecutableState.READY && state != ExecutableState.RUNNING) {
                if (jobWithLocks.contains(executable.getId())) {
                    logger.info(
                            executable.toString() + " will release the lock for the job: " + executable.getId());
                    jobLock.unlock(getLockPath(executable.getId()));
                    jobWithLocks.remove(executable.getId());
                }
            }
        }
    }
}

public class Lease<T> {

  /**
   * The resource for which this lease is created.
   */
  private final T resource;

  private final long creationTime;

  /**
   * Lease lifetime in milliseconds.
   */
  private volatile long leaseTimeout;

  private boolean expired;

  /**
   * Functions to be called in case of timeout.
   */
  private List<Callable<Void>> callbacks;


  /**
   * Creates a lease on the specified resource with given timeout.
   *
   * @param resource
   *        Resource for which the lease has to be created
   * @param timeout
   *        Lease lifetime in milliseconds
   */
  public Lease(T resource, long timeout) {
    this.resource = resource;
    this.leaseTimeout = timeout;
    this.callbacks = Collections.synchronizedList(new ArrayList<>());
    this.creationTime = Time.monotonicNow();
    this.expired = false;
  }

  /**
   * Returns true if the lease has expired, else false.
   *
   * @return true if expired, else false
   */
  public boolean hasExpired() {
    return expired;
  }

  /**
   * Registers a callback which will be executed in case of timeout. Callbacks
   * are executed in a separate Thread.
   *
   * @param callback
   *        The Callable which has to be executed
   * @throws LeaseExpiredException
   *         If the lease has already timed out
   */
  public void registerCallBack(Callable<Void> callback)
      throws LeaseExpiredException {
    if(hasExpired()) {
      throw new LeaseExpiredException("Resource: " + resource);
    }
    callbacks.add(callback);
  }

  /**
   * Returns the time elapsed since the creation of lease.
   *
   * @return elapsed time in milliseconds
   * @throws LeaseExpiredException
   *         If the lease has already timed out
   */
  public long getElapsedTime() throws LeaseExpiredException {
    if(hasExpired()) {
      throw new LeaseExpiredException("Resource: " + resource);
    }
    return Time.monotonicNow() - creationTime;
  }

  /**
   * Returns the time available before timeout.
   *
   * @return remaining time in milliseconds
   * @throws LeaseExpiredException
   *         If the lease has already timed out
   */
  public long getRemainingTime() throws LeaseExpiredException {
    if(hasExpired()) {
      throw new LeaseExpiredException("Resource: " + resource);
    }
    return leaseTimeout - getElapsedTime();
  }

  /**
   * Returns total lease lifetime.
   *
   * @return total lifetime of lease in milliseconds
   * @throws LeaseExpiredException
   *         If the lease has already timed out
   */
  public long getLeaseLifeTime() throws LeaseExpiredException {
    if(hasExpired()) {
      throw new LeaseExpiredException("Resource: " + resource);
    }
    return leaseTimeout;
  }

  /**
   * Renews the lease timeout period.
   *
   * @param timeout
   *        Time to be added to the lease in milliseconds
   * @throws LeaseExpiredException
   *         If the lease has already timed out
   */
  public void renew(long timeout) throws LeaseExpiredException {
    if(hasExpired()) {
      throw new LeaseExpiredException("Resource: " + resource);
    }
    leaseTimeout += timeout;
  }

  @Override
  public int hashCode() {
    return resource.hashCode();
  }

  @Override
  public boolean equals(Object obj) {
    if(obj instanceof Lease) {
      return resource.equals(((Lease) obj).resource);
    }
    return false;
  }

  @Override
  public String toString() {
    return "Lease<" + resource.toString() + ">";
  }

  /**
   * Returns the callbacks to be executed for the lease in case of timeout.
   *
   * @return callbacks to be executed
   */
  List<Callable<Void>> getCallbacks() {
    return callbacks;
  }

  /**
   * Expires/Invalidates the lease.
   */
  void invalidate() {
    callbacks = null;
    expired = true;
  }

}

