private static final class DefaultLoggerProxy extends LoggerProxy {
    /**
     * Default platform logging support - output messages to System.err -
     * equivalent to ConsoleHandler with SimpleFormatter.
     */
    private static PrintStream outputStream() {
        return System.err;
    }

    volatile Level effectiveLevel; // effective level (never null)
    volatile Level level;          // current level set for this node (may be null)

    DefaultLoggerProxy(String name) {
        super(name);
        this.effectiveLevel = deriveEffectiveLevel(null);
        this.level = null;
    }

    boolean isEnabled() {
        return effectiveLevel != Level.OFF;
    }

    Level getLevel() {
        return level;
    }

    void setLevel(Level newLevel) {
        Level oldLevel = level;
        if (oldLevel != newLevel) {
            level = newLevel;
            effectiveLevel = deriveEffectiveLevel(newLevel);
        }
    }

    void doLog(Level level, String msg) {
        if (isLoggable(level)) {
            outputStream().print(format(level, msg, null));
        }
    }

    void doLog(Level level, String msg, Throwable thrown) {
        if (isLoggable(level)) {
            outputStream().print(format(level, msg, thrown));
        }
    }

    void doLog(Level level, String msg, Object... params) {
        if (isLoggable(level)) {
            String newMsg = formatMessage(msg, params);
            outputStream().print(format(level, newMsg, null));
        }
    }

    boolean isLoggable(Level level) {
        Level effectiveLevel = this.effectiveLevel;
        return level.intValue() >= effectiveLevel.intValue() && effectiveLevel != Level.OFF;
    }

    // derive effective level (could do inheritance search like j.u.l.Logger)
    private Level deriveEffectiveLevel(Level level) {
        return level == null ? DEFAULT_LEVEL : level;
    }

    // Copied from java.util.logging.Formatter.formatMessage
    private String formatMessage(String format, Object... parameters) {
        // Do the formatting.
        try {
            if (parameters == null || parameters.length == 0) {
                // No parameters.  Just return format string.
                return format;
            }
            // Is it a java.text style format?
            // Ideally we could match with
            // Pattern.compile("\\{\\d").matcher(format).find())
            // However the cost is 14% higher, so we cheaply check for
            // 1 of the first 4 parameters
            if (format.indexOf("{0") >= 0 || format.indexOf("{1") >=0 ||
                        format.indexOf("{2") >=0|| format.indexOf("{3") >=0) {
                return java.text.MessageFormat.format(format, parameters);
            }
            return format;
        } catch (Exception ex) {
            // Formatting failed: use format string.
            return format;
        }
    }

    private static final String formatString =
        LoggingSupport.getSimpleFormat(false); // don't check logging.properties

    // minimize memory allocation
    private Date date = new Date();
    private synchronized String format(Level level, String msg, Throwable thrown) {
        date.setTime(System.currentTimeMillis());
        String throwable = "";
        if (thrown != null) {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            pw.println();
            thrown.printStackTrace(pw);
            pw.close();
            throwable = sw.toString();
        }

        return String.format(formatString,
                             date,
                             getCallerInfo(),
                             name,
                             level.name(),
                             msg,
                             throwable);
    }

    // Returns the caller's class and method's name; best effort
    // if cannot infer, return the logger's name.
    private String getCallerInfo() {
        String sourceClassName = null;
        String sourceMethodName = null;

        Throwable throwable = new Throwable();

        String logClassName = "sun.util.logging.PlatformLogger";
        boolean lookingForLogger = true;
        for (StackTraceElement frame : throwable.getStackTrace()) {
            String cname = frame.getClassName();
            if (lookingForLogger) {
                // Skip all frames until we have found the first logger frame.
                if (cname.equals(logClassName)) {
                    lookingForLogger = false;
                }
            } else {
                if (!cname.equals(logClassName)) {
                    // We've found the relevant frame.
                    sourceClassName = cname;
                    sourceMethodName = frame.getMethodName();
                    break;
                }
            }
        }

        if (sourceClassName != null) {
            return sourceClassName + " " + sourceMethodName;
        } else {
            return name;
        }
    }
}

@BuiltInProcessor("PageViewTelemetryFilter")
public final class PageViewTelemetryFilter implements TelemetryProcessor {

    private long durationThresholdInMS = 0l;
    private final Set<String> notNeededUrls = new HashSet<String>();
    private final Set<String> notNeededNames = new HashSet<String>();

    public PageViewTelemetryFilter() {
    }

    @Override
    public boolean process(Telemetry telemetry) {
        if (telemetry == null) {
            return true;
        }

        if (!(telemetry instanceof PageViewTelemetry)) {
            return true;
        }

        PageViewTelemetry asPVT = (PageViewTelemetry) telemetry;
        URI uri = asPVT.getUri();
        if (uri == null) {
            return true;
        } else {
            String uriPath = uri.toString();
            for (String notNeededUri : notNeededUrls) {
                if (uriPath.contains(notNeededUri)) {
                    return false;
                }
            }
        }

        if (notNeededNames.contains(asPVT.getName())) {
            return false;
        }

        long pvtDuration = asPVT.getDuration();
        if (durationThresholdInMS <= pvtDuration) {
            return true;
        }

        return false;
    }

    public void setDurationThresholdInMS(String durationThresholdInMS) throws NumberFormatException {
        try {
            this.durationThresholdInMS = Long.valueOf(durationThresholdInMS);
            InternalLogger.INSTANCE.trace("PageViewTelemetryFilter: successfully set DurationThresholdInMS to %s", durationThresholdInMS);
        } catch (NumberFormatException e) {
            InternalLogger.INSTANCE.error("PageViewTelemetryFilter: failed to set DurationThresholdInMS:%s Exception : %s ",
                    durationThresholdInMS, ExceptionUtils.getStackTrace(e));
            throw e;
        }
    }

    public void setNotNeededNames(String notNeededNames) throws Throwable {
        try {
            List<String> notNeededAsList = Arrays.asList(notNeededNames.split(","));
            for (String notNeeded : notNeededAsList) {
                String ready = notNeeded.trim();
                if (LocalStringsUtils.isNullOrEmpty(ready)) {
                    continue;
                }

                this.notNeededNames.add(ready);
            }

            InternalLogger.INSTANCE.trace(String.format("PageViewTelemetryFilter: set NotNeededNames: %s", notNeededNames));
        } catch (ThreadDeath td) {
            throw td;
        } catch (Throwable t) {
            try {
                InternalLogger.INSTANCE.trace("PageViewTelemetryFilter: failed to parse NotNeededNames: %s Exception : %s", notNeededNames,
                        ExceptionUtils.getStackTrace(t));
            } catch (ThreadDeath td) {
                throw td;
            } catch (Throwable t2) {
                // chomp
            }
            throw t;
        }
    }

    public void setNotNeededUrls(String notNeededUrls) throws Throwable {
        try {
            List<String> notNeededAsList = Arrays.asList(notNeededUrls.split(","));
            for (String notNeeded : notNeededAsList) {
                String ready = notNeeded.trim();
                if (LocalStringsUtils.isNullOrEmpty(ready)) {
                    continue;
                }

                this.notNeededUrls.add(ready);
            }
            InternalLogger.INSTANCE.trace("PageViewTelemetryFilter: set %s", notNeededUrls);
        } catch (ThreadDeath td) {
            throw td;
        } catch (Throwable t) {
            try {
                InternalLogger.INSTANCE.error("PageViewTelemetryFilter: failed to parse NotNeededUrls: %s Exception : %s", notNeededUrls,
                        ExceptionUtils.getStackTrace(t));
            } catch (ThreadDeath td) {
                throw td;
            } catch (Throwable t2) {
                // chomp
            }
            throw t;
        }
    }
}

public class MethodEffector<T> extends AbstractEffector<T> {

    private static final long serialVersionUID = 6989688364011965968L;
    private static final Logger log = LoggerFactory.getLogger(MethodEffector.class);

    @SuppressWarnings("rawtypes")
    public static Effector<?> create(Method m) {
        return new MethodEffector(m);
    }

    protected static class AnnotationsOnMethod {
        final Class<?> clazz;
        final String name;
        final String description;
        final Class<?> returnType;
        final List<ParameterType<?>> parameters;

        public AnnotationsOnMethod(Class<?> clazz, String methodName) {
            this(clazz, inferBestMethod(clazz, methodName));
        }

        public AnnotationsOnMethod(Class<?> clazz, Method method) {
            this.clazz = clazz;
            this.name = method.getName();
            this.returnType = method.getReturnType();

            // Get the description
            org.apache.brooklyn.core.annotation.Effector effectorAnnotation = method.getAnnotation(org.apache.brooklyn.core.annotation.Effector.class);
            description = (effectorAnnotation != null) ? effectorAnnotation.description() : null;

            // Get the parameters
            parameters = Lists.newArrayList();
            int numParameters = method.getParameterTypes().length;
            for (int i = 0; i < numParameters; i++) {
                parameters.add(toParameterType(method, i));
            }
        }

        @SuppressWarnings({ "rawtypes", "unchecked" })
        protected static ParameterType<?> toParameterType(Method method, int paramIndex) {
            Annotation[] anns = method.getParameterAnnotations()[paramIndex];
            Class<?> type = method.getParameterTypes()[paramIndex];
            EffectorParam paramAnnotation = findAnnotation(anns, EffectorParam.class);

            // TODO if blank, could do "param"+(i+1); would that be better?
            // TODO this will now give "" if name is blank, rather than previously null. Is that ok?!
            String name = (paramAnnotation != null) ? paramAnnotation.name() : null;

            String paramDescription = (paramAnnotation == null || EffectorParam.MAGIC_STRING_MEANING_NULL.equals(paramAnnotation.description())) ? null : paramAnnotation.description();
            String description = (paramDescription != null) ? paramDescription : null;

            String paramDefaultValue = (paramAnnotation == null || EffectorParam.MAGIC_STRING_MEANING_NULL.equals(paramAnnotation.defaultValue())) ? null : paramAnnotation.defaultValue();
            Object defaultValue = (paramDefaultValue != null) ? TypeCoercions.coerce(paramDefaultValue, type) : null;

            return new BasicParameterType(name, type, description, defaultValue);
        }

        @SuppressWarnings("unchecked")
        protected static <T extends Annotation> T findAnnotation(Annotation[] anns, Class<T> type) {
            for (Annotation ann : anns) {
                if (type.isInstance(ann)) return (T) ann;
            }
            return null;
        }

        protected static Method inferBestMethod(Class<?> clazz, String methodName) {
            Method best = null;
            for (Method it : clazz.getMethods()) { 
                if (it.getName().equals(methodName)) {
                    if (best==null || best.getParameterTypes().length < it.getParameterTypes().length) best=it;
                }
            }
            if (best==null) {
                throw new IllegalStateException("Cannot find method "+methodName+" on "+clazz.getCanonicalName());
            }
            return best;
        }
    }

    /** Defines a new effector whose details are supplied as annotations on the given type and method name */
    public MethodEffector(Class<?> whereEffectorDefined, String methodName) {
        this(new AnnotationsOnMethod(whereEffectorDefined, methodName), null);
    }

    public MethodEffector(Method method) {
        this(new AnnotationsOnMethod(method.getDeclaringClass(), method), null);
    }

    /**
     * @deprecated since 0.11.0; explicit groovy utilities/support will be deleted.
     */
    @Deprecated
    public MethodEffector(MethodClosure mc) {
        this(new AnnotationsOnMethod((Class<?>)mc.getDelegate(), mc.getMethod()), null);
    }

    @SuppressWarnings("unchecked")
    protected MethodEffector(AnnotationsOnMethod anns, String description) {
        super(anns.name, (Class<T>)anns.returnType, anns.parameters, JavaGroovyEquivalents.elvis(description, anns.description));
    }

    @Override
    @SuppressWarnings({ "rawtypes", "unchecked" })
    public T call(Entity entity, Map parameters) {
        if (entity instanceof AbstractEntity) {
            return EffectorUtils.invokeMethodEffector(entity, this, (Map<String,?>)parameters);
        } else {
            // we are dealing with a proxy here
            // this implementation invokes the method on the proxy
            // (requiring it to be on the interface)
            // and letting the proxy deal with the remoting / runAtEntity;
            // alternatively we could create the task here and pass it to runAtEntity;
            // the latter may allow us to simplify/remove a lot of the stuff from 
            // EffectorUtils and possibly Effectors and Entities

            // TODO Should really find method with right signature, rather than just the right args.
            // TODO prepareArgs can miss things out that have "default values"! Code below will probably fail if that happens.
            Object[] parametersArray = EffectorUtils.prepareArgsForEffector(this, parameters);
            Method[] methods = entity.getClass().getMethods();
            for (Method method : methods) {
                if (method.getName().equals(getName())) {
                    if (parametersArray.length == method.getParameterTypes().length) {
                        try {
                            return (T) method.invoke(entity, parametersArray);
                        } catch (Exception e) {
                            // exception handled by the proxy invocation (which leads to EffectorUtils.invokeEffectorMethod...)
                            throw Exceptions.propagate(e);
                        }
                    }
                }
            }
            String msg = "Could not find method for effector "+getName()+" with "+parametersArray.length+" parameters on "+entity;
            log.warn(msg+" (throwing); available methods are: "+Arrays.toString(methods));
            throw new IllegalStateException(msg);
        }
    }

}

public class StAXCatalogWriter implements ICatalogXMLConstants
{

    /**
     * Create an catalog.xml writer.
     * 
     * @param swc SWC model
     * @param writer writer
     * @throws XMLStreamException XML error
     * @throws FactoryConfigurationError factory error
     */
    public StAXCatalogWriter(final ISWC swc, final Writer writer) throws XMLStreamException, FactoryConfigurationError
    {
        assert swc != null : "expect SWC model";
        assert writer != null : "expect Writer";

        this.swc = swc;

        final XMLOutputFactory xmlOutputFactory = XMLOutputFactory.newInstance();
        assert xmlOutputFactory != null : "Expect XMLOutputFactory implementation.";
        this.xmlWriter = new XMLFormatter(xmlOutputFactory.createXMLStreamWriter(writer));
    }

    private final XMLStreamWriter xmlWriter;
    private final ISWC swc;

    /**
     * Write serialized XML to output.
     * 
     * @throws XMLStreamException error
     */
    public void write() throws XMLStreamException
    {
        xmlWriter.writeStartDocument(); // start XML

        {
            xmlWriter.writeStartElement(TAG_SWC);
            xmlWriter.writeAttribute(ATTR_XMLNS, XMLNS_SWC_CATALOG_9);
            writeVersions();
            writeFeatures();
            writeComponents();
            writeLibraries();
            writeFiles();
            xmlWriter.writeEndElement();
        }

        xmlWriter.writeEndDocument(); // end XML

        xmlWriter.flush();
        xmlWriter.close();
    }

    private static final Comparator<ISWCComponent> COMPONENT_COMPARATOR =
        new Comparator<ISWCComponent>() {

            @Override
            public int compare(ISWCComponent o1, ISWCComponent o2)
            {
                return o1.getQName().compareTo(o2.getQName());
            }
        };

    private void writeComponents() throws XMLStreamException
    {
        Collection<ISWCComponent> componentsList = swc.getComponents();
        if (componentsList.isEmpty())
            return;
        xmlWriter.writeStartElement(TAG_COMPONENTS);
        ISWCComponent[] components = componentsList.toArray(new ISWCComponent[componentsList.size()]);
        Arrays.sort(components, COMPONENT_COMPARATOR);
        for (final ISWCComponent component : components)
        {
            xmlWriter.writeEmptyElement(TAG_COMPONENT);
            if (component.getQName() != null)
                xmlWriter.writeAttribute(ATTR_CLASS_NAME, dottedQNameToColonQName(component.getQName()));
            if (component.getName() != null)
                xmlWriter.writeAttribute(ATTR_NAME, component.getName());
            if (component.getURI() != null)
                xmlWriter.writeAttribute(ATTR_URI, component.getURI());
            if (component.getIcon() != null)
                xmlWriter.writeAttribute(ATTR_ICON, component.getIcon());
            if (component.getPreview() != null)
                xmlWriter.writeAttribute(ATTR_PREVIEW, component.getPreview());
        }
        xmlWriter.writeEndElement();
    }

    private static final Comparator<ISWCFileEntry> FILE_COMPARATOR =
        new Comparator<ISWCFileEntry>()
        {

            @Override
            public int compare(ISWCFileEntry o1, ISWCFileEntry o2)
            {
                return o1.getPath().compareTo(o2.getPath());
            }

        };

    private void writeFiles() throws XMLStreamException
    {
        Collection<ISWCFileEntry> filesCollection = swc.getFiles().values();
        if (filesCollection.isEmpty())
            return;
        xmlWriter.writeStartElement(TAG_FILES);
        ISWCFileEntry[] files = filesCollection.toArray(new ISWCFileEntry[filesCollection.size()]);
        Arrays.sort(files, FILE_COMPARATOR);
        for (final ISWCFileEntry file : files)
        {
            xmlWriter.writeEmptyElement(TAG_FILE);
            xmlWriter.writeAttribute(ATTR_PATH, file.getPath());
            xmlWriter.writeAttribute(ATTR_MOD, String.valueOf(file.getLastModified()));
        }
        xmlWriter.writeEndElement();
    }

    private static final Comparator<ISWCLibrary> LIBRARY_COMPARATOR =
        new Comparator<ISWCLibrary>() {

            @Override
            public int compare(ISWCLibrary o1, ISWCLibrary o2)
            {
                return o1.getPath().compareTo(o2.getPath());
            }
        };

    private static final Comparator<ISWCScript> SCRIPT_COMPARATOR =
        new Comparator<ISWCScript>() {

            @Override
            public int compare(ISWCScript o1, ISWCScript o2)
            {
                return o1.getName().compareTo(o2.getName());
            }
        };

    private static final Comparator<ISWCDigest> DIGEST_COMPARATOR =
        new Comparator<ISWCDigest>() {

            @Override
            public int compare(ISWCDigest o1, ISWCDigest o2)
            {
                return o1.getValue().compareTo(o2.getValue());
            }
        };

    private void writeLibraries() throws XMLStreamException
    {
        xmlWriter.writeStartElement(TAG_LIBRARIES);

        final Collection<ISWCLibrary> librariesCollection = swc.getLibraries();
        final ISWCLibrary[] libraries = librariesCollection.toArray(new ISWCLibrary[librariesCollection.size()]);
        Arrays.sort(libraries, LIBRARY_COMPARATOR);

        for (final ISWCLibrary library : libraries)
        {
            xmlWriter.writeStartElement(TAG_LIBRARY);
            xmlWriter.writeAttribute(ATTR_PATH, library.getPath());
            {
                final Collection<ISWCScript> scriptsList = library.getScripts();
                final ISWCScript[] scripts = scriptsList.toArray(new ISWCScript[scriptsList.size()]);
                Arrays.sort(scripts, SCRIPT_COMPARATOR);
                for (final ISWCScript script : scripts)
                {
                    writeLibraryScript(script);
                }

                final Collection<String> keepAS3MetadataList = library.getKeepAS3MetadataSet();
                if (!keepAS3MetadataList.isEmpty())
                {
                    xmlWriter.writeStartElement(TAG_KEEP_AS3_METADATA);

                    final String[] keepAS3Metadata = keepAS3MetadataList.toArray(new String[keepAS3MetadataList.size()]);
                    Arrays.sort(keepAS3Metadata);
                    for (final String metadata : keepAS3Metadata)
                    {
                        xmlWriter.writeEmptyElement(TAG_METADATA);
                        xmlWriter.writeAttribute(ATTR_NAME, metadata);
                    }
                    xmlWriter.writeEndElement(); // end of <keep-as3-metadata>
                }

                xmlWriter.writeStartElement(TAG_DIGESTS);

                final Collection<ISWCDigest> digestsList = library.getDigests();
                final ISWCDigest[] digests = digestsList.toArray(new ISWCDigest[digestsList.size()]);
                Arrays.sort(digests, DIGEST_COMPARATOR);
                for (final ISWCDigest digest : digests)
                {
                    xmlWriter.writeEmptyElement(TAG_DIGEST);
                    xmlWriter.writeAttribute(ATTR_TYPE, digest.getType());
                    xmlWriter.writeAttribute(ATTR_SIGNED, digest.isSigned() ? "true" : "false"); 
                    xmlWriter.writeAttribute(TAG_VALUE, digest.getValue());
                }
                xmlWriter.writeEndElement(); // end of <digests>
            }
            xmlWriter.writeEndElement(); // end of <library>
        }

        xmlWriter.writeEndElement(); // end of <libraries>
    }

    private static String dottedQNameToColonQName(String qname)
    {
        int lastDotIndex = qname.lastIndexOf('.');
        if (lastDotIndex == -1)
            return qname;
        final String packageName = qname.substring(0, lastDotIndex);
        final String baseName = qname.substring(lastDotIndex + 1);
        return packageName + ":" + baseName; 
    }

    private static final Comparator<Map.Entry<String, DependencyType>> DEPENDENCY_MAP_ENTRY_COMPARATOR =
        new Comparator<Map.Entry<String, DependencyType>>()
        {

            @Override
            public int compare(Entry<String, DependencyType> arg0, Entry<String, DependencyType> arg1)
            {
                int result = arg0.getKey().compareTo(arg1.getKey());
                if (result != 0)
                    return result;
                return arg0.getValue().ordinal() - arg1.getValue().ordinal();
            }

        };

    private void writeLibraryScript(final ISWCScript script) throws XMLStreamException
    {
        xmlWriter.writeStartElement(TAG_SCRIPT);
        xmlWriter.writeAttribute(ATTR_NAME, script.getName());
        xmlWriter.writeAttribute(ATTR_MOD, String.valueOf(script.getLastModified()));
        if (script.getSignatureChecksum() != null)
            xmlWriter.writeAttribute(ATTR_SIGNATURE_CHECKSUM, script.getSignatureChecksum());

        final Set<String> definitionsSet = script.getDefinitions();
        final String[] definitions = definitionsSet.toArray(new String[definitionsSet.size()]);
        Arrays.sort(definitions);
        for (final String def : definitions)
        {
            xmlWriter.writeEmptyElement(TAG_DEF);
            xmlWriter.writeAttribute(ATTR_ID, dottedQNameToColonQName(def));
        }

        final Set<Map.Entry<String, DependencyType>> dependenciesSet = script.getDependencies().entries();
        final ArrayList<Map.Entry<String, DependencyType>> dependencies =
            new ArrayList<Map.Entry<String, DependencyType>>(dependenciesSet.size());
        Iterables.addAll(dependencies, dependenciesSet);
        Collections.sort(dependencies, DEPENDENCY_MAP_ENTRY_COMPARATOR);


        for (final Map.Entry<String, DependencyType> dep : dependencies)
        {
            xmlWriter.writeEmptyElement(TAG_DEP);
            xmlWriter.writeAttribute(ATTR_ID, dottedQNameToColonQName(dep.getKey()));
            xmlWriter.writeAttribute(ATTR_TYPE, String.valueOf(dep.getValue().getSymbol()));
        }

        xmlWriter.writeEndElement();
    }

    private void writeFeatures() throws XMLStreamException
    {
        xmlWriter.writeStartElement(TAG_FEATURES);
        {
            // Like the pre-Royale compiler,
            // Royale unconditionally writes out script dependencies.
            xmlWriter.writeEmptyElement(TAG_FEATURE_SCRIPT_DEPS);

            if (!swc.getComponents().isEmpty())
                xmlWriter.writeEmptyElement(TAG_FEATURE_COMPONENTS);

            if (!swc.getFiles().isEmpty())
                xmlWriter.writeEmptyElement(TAG_FEATURE_FILES);
        }
        xmlWriter.writeEndElement();
    }

    private void writeVersions() throws XMLStreamException
    {
        final ISWCVersion version = swc.getVersion();
        if (version == null)
            return;

        xmlWriter.writeStartElement(TAG_VERSIONS);

        // SWC version
        final String swcVersion = version.getSWCVersion();
        if (swcVersion != null)
        {
            xmlWriter.writeEmptyElement(TAG_SWC);
            xmlWriter.writeAttribute(ATTR_VERSION, swcVersion);
        }

        // Royale version
        final String royaleVersion = version.getRoyaleVersion();
        if (royaleVersion != null)
        {
            xmlWriter.writeEmptyElement(TAG_ROYALE);
            xmlWriter.writeAttribute(ATTR_VERSION, royaleVersion);

            final String royaleBuild = version.getRoyaleBuild();
            if (royaleBuild != null)
                xmlWriter.writeAttribute(ATTR_BUILD, royaleBuild);

            final String royaleMinSupportedVersion = version.getRoyaleMinSupportedVersion();
            if (royaleMinSupportedVersion != null)
                xmlWriter.writeAttribute(ATTR_MINIMUM_SUPPORTED_VERSION, royaleMinSupportedVersion);
        }

        // Compiler version
        final String compilerVersion = version.getCompilerVersion();
        if (compilerVersion != null)
        {
            xmlWriter.writeEmptyElement(TAG_COMPILER);

            final String compilerName = version.getCompilerName();
            if (compilerName != null)
                xmlWriter.writeAttribute(ATTR_NAME, compilerName);

            xmlWriter.writeAttribute(ATTR_VERSION, compilerVersion);

            final String compilerBuild = version.getCompilerBuild();
            if (compilerBuild != null)
                xmlWriter.writeAttribute(ATTR_BUILD, compilerBuild);
        }

        xmlWriter.writeEndElement();
    }
}

