public abstract class NumericRange<T extends Number & Comparable<T>> extends AbstractRange<T, T> {

    /**
     * Construct a new {@link NumericRange}.
     * @param leftEndpoint left endpoint
     * @param rightEndpoint right endpoint
     * @param step increment step
     * @param nextValue function to implement the taking of a step
     */
    protected NumericRange(Endpoint<T> leftEndpoint, Endpoint<T> rightEndpoint, T step,
            BinaryFunction<T, T, T> nextValue) {
        super(leftEndpoint, rightEndpoint, step, nextValue);
    }

    /**
     * {@inheritDoc}
     */
    public boolean contains(T obj) {
        if (obj == null) {
            return false;
        }
        double leftValue = this.getLeftEndpoint().getValue().doubleValue();
        double rightValue = this.getRightEndpoint().getValue().doubleValue();
        boolean includeLeft = this.getLeftEndpoint().getBoundType() == BoundType.CLOSED;
        boolean includeRight = this.getRightEndpoint().getBoundType() == BoundType.CLOSED;
        double step = this.getStep().doubleValue();
        double value = obj.doubleValue();

        double firstValue = 0;
        double lastValue = 0;

        if (step < 0.0) {
            firstValue = includeLeft ? leftValue : leftValue + step;
            lastValue = includeRight ? rightValue : Math.nextUp(rightValue);
            if (value > firstValue || value < lastValue) {
                return false;
            }
        } else {
            firstValue = includeLeft ? leftValue : leftValue + step;
            lastValue = includeRight ? rightValue : rightValue
                                                    - (rightValue - Math
                                                        .nextUp(rightValue));
            if (value < firstValue || value > lastValue) {
                return false;
            }
        }
        return ((value - firstValue) / step + 1) % 1.0 == 0.0;
    }

}

@Override
public boolean equals(Object obj)
{
  if (this == obj)
  {
    return true;
  }

  if (obj == null)
  {
    return false;
  }

  if (getClass() != obj.getClass())
  {
    return false;
  }

  final MethodIdentity other = (MethodIdentity) obj;
  return new EqualsBuilder().
      append(_methodQualifiedName, other._methodQualifiedName).
      append(_parameterTypeNames, other._parameterTypeNames).
      isEquals();
}

private static final class FixNegativeLocalDeletionTimeIterator extends AbstractIterator<Unfiltered> implements UnfilteredRowIterator
{
    /**
     * The decorated iterator.
     */
    private final UnfilteredRowIterator iterator;

    private final OutputHandler outputHandler;
    private final NegativeLocalDeletionInfoMetrics negativeLocalExpirationTimeMetrics;

    public FixNegativeLocalDeletionTimeIterator(UnfilteredRowIterator iterator, OutputHandler outputHandler,
                                                NegativeLocalDeletionInfoMetrics negativeLocalDeletionInfoMetrics)
    {
        this.iterator = iterator;
        this.outputHandler = outputHandler;
        this.negativeLocalExpirationTimeMetrics = negativeLocalDeletionInfoMetrics;
    }

    public TableMetadata metadata()
    {
        return iterator.metadata();
    }

    public boolean isReverseOrder()
    {
        return iterator.isReverseOrder();
    }

    public RegularAndStaticColumns columns()
    {
        return iterator.columns();
    }

    public DecoratedKey partitionKey()
    {
        return iterator.partitionKey();
    }

    public Row staticRow()
    {
        return iterator.staticRow();
    }

    @Override
    public boolean isEmpty()
    {
        return iterator.isEmpty();
    }

    public void close()
    {
        iterator.close();
    }

    public DeletionTime partitionLevelDeletion()
    {
        return iterator.partitionLevelDeletion();
    }

    public EncodingStats stats()
    {
        return iterator.stats();
    }

    protected Unfiltered computeNext()
    {
        if (!iterator.hasNext())
            return endOfData();

        Unfiltered next = iterator.next();
        if (!next.isRow())
            return next;

        if (hasNegativeLocalExpirationTime((Row) next))
        {
            outputHandler.debug(String.format("Found row with negative local expiration time: %s", next.toString(metadata(), false)));
            negativeLocalExpirationTimeMetrics.fixedRows++;
            return fixNegativeLocalExpirationTime((Row) next);
        }

        return next;
    }

    private boolean hasNegativeLocalExpirationTime(Row next)
    {
        Row row = next;
        if (row.primaryKeyLivenessInfo().isExpiring() && row.primaryKeyLivenessInfo().localExpirationTime() < 0)
        {
            return true;
        }

        for (ColumnData cd : row)
        {
            if (cd.column().isSimple())
            {
                Cell cell = (Cell)cd;
                if (cell.isExpiring() && cell.localDeletionTime() < 0)
                    return true;
            }
            else
            {
                ComplexColumnData complexData = (ComplexColumnData)cd;
                for (Cell cell : complexData)
                {
                    if (cell.isExpiring() && cell.localDeletionTime() < 0)
                        return true;
                }
            }
        }

        return false;
    }

    private Unfiltered fixNegativeLocalExpirationTime(Row row)
    {
        Row.Builder builder = HeapAllocator.instance.cloningBTreeRowBuilder();
        builder.newRow(row.clustering());
        builder.addPrimaryKeyLivenessInfo(row.primaryKeyLivenessInfo().isExpiring() && row.primaryKeyLivenessInfo().localExpirationTime() < 0 ?
                                          row.primaryKeyLivenessInfo().withUpdatedTimestampAndLocalDeletionTime(row.primaryKeyLivenessInfo().timestamp() + 1, AbstractCell.MAX_DELETION_TIME)
                                          :row.primaryKeyLivenessInfo());
        builder.addRowDeletion(row.deletion());
        for (ColumnData cd : row)
        {
            if (cd.column().isSimple())
            {
                Cell cell = (Cell)cd;
                builder.addCell(cell.isExpiring() && cell.localDeletionTime() < 0 ? cell.withUpdatedTimestampAndLocalDeletionTime(cell.timestamp() + 1, AbstractCell.MAX_DELETION_TIME) : cell);
            }
            else
            {
                ComplexColumnData complexData = (ComplexColumnData)cd;
                builder.addComplexDeletion(complexData.column(), complexData.complexDeletion());
                for (Cell cell : complexData)
                {
                    builder.addCell(cell.isExpiring() && cell.localDeletionTime() < 0 ? cell.withUpdatedTimestampAndLocalDeletionTime(cell.timestamp() + 1, AbstractCell.MAX_DELETION_TIME) : cell);
                }
            }
        }
        return builder.build();
    }
}

