public static class Offset implements  FileOffset {
  public long lastSyncPoint;
  public long recordsSinceLastSync;
  public long currentRecord;
  private long currRecordEndOffset;
  private long prevRecordEndOffset;

  public Offset(long lastSyncPoint, long recordsSinceLastSync, long currentRecord) {
    this(lastSyncPoint, recordsSinceLastSync, currentRecord, 0, 0 );
  }

  public Offset(long lastSyncPoint, long recordsSinceLastSync, long currentRecord
                , long currRecordEndOffset, long prevRecordEndOffset) {
    this.lastSyncPoint = lastSyncPoint;
    this.recordsSinceLastSync = recordsSinceLastSync;
    this.currentRecord = currentRecord;
    this.prevRecordEndOffset = prevRecordEndOffset;
    this.currRecordEndOffset = currRecordEndOffset;
  }

  public Offset(String offset) {
    try {
      if(offset==null) {
        throw new IllegalArgumentException("offset cannot be null");
      }
      if(offset.equalsIgnoreCase("0")) {
        this.lastSyncPoint = 0;
        this.recordsSinceLastSync = 0;
        this.currentRecord = 0;
        this.prevRecordEndOffset = 0;
        this.currRecordEndOffset = 0;
      } else {
        String[] parts = offset.split(":");
        this.lastSyncPoint = Long.parseLong(parts[0].split("=")[1]);
        this.recordsSinceLastSync = Long.parseLong(parts[1].split("=")[1]);
        this.currentRecord = Long.parseLong(parts[2].split("=")[1]);
        this.prevRecordEndOffset = 0;
        this.currRecordEndOffset = 0;
      }
    } catch (Exception e) {
      throw new IllegalArgumentException("'" + offset +
              "' cannot be interpreted. It is not in expected format for SequenceFileReader." +
              " Format e.g. {sync=123:afterSync=345:record=67}");
    }
  }

  @Override
  public String toString() {
    return '{' +
            "sync=" + lastSyncPoint +
            ":afterSync=" + recordsSinceLastSync +
            ":record=" + currentRecord +
            ":}";
  }

  @Override
  public boolean isNextOffset(FileOffset rhs) {
    if(rhs instanceof Offset) {
      Offset other = ((Offset) rhs);
      return  other.currentRecord > currentRecord+1;
    }
    return false;
  }

  @Override
  public int compareTo(FileOffset o) {
    Offset rhs = ((Offset) o);
    if(currentRecord<rhs.currentRecord) {
      return -1;
    }
    if(currentRecord==rhs.currentRecord) {
      return 0;
    }
    return 1;
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) { return true; }
    if (!(o instanceof Offset)) { return false; }

    Offset offset = (Offset) o;

    return currentRecord == offset.currentRecord;
  }

  @Override
  public int hashCode() {
    return (int) (currentRecord ^ (currentRecord >>> 32));
  }

  void increment(boolean syncSeen, long newBytePosition) {
    if(!syncSeen) {
      ++recordsSinceLastSync;
    }  else {
      recordsSinceLastSync = 1;
      lastSyncPoint = prevRecordEndOffset;
    }
    ++currentRecord;
    prevRecordEndOffset = currRecordEndOffset;
    currentRecord = newBytePosition;
  }

  @Override
  public Offset clone() {
    return new Offset(lastSyncPoint, recordsSinceLastSync, currentRecord, currRecordEndOffset, prevRecordEndOffset);
  }

} //class Offset

@Override
public void run() {
    while (!shutdown) {
        try {
            sleep(factoryData.reconnectIntervalMillis);
            reconnect();
        } catch (final InterruptedException | SQLException e) {
            logger().debug("Cannot reestablish JDBC connection to {}: {}", factoryData, e.getLocalizedMessage(),
                    e);
        } finally {
            latch.countDown();
        }
    }
}

@Path("token")
@ApplicationScoped
public class OAuth2TokenService extends AccessTokenService implements OAuth2Application.Defaults {
    @Inject
    private OAuth2Configurer configurer;

    @Inject
    private LazyImpl delegate;

    @POST
    @Consumes(APPLICATION_FORM_URLENCODED)
    @Produces(APPLICATION_JSON)
    public Response handleTokenRequest(final MultivaluedMap<String, String> params) {
        return getDelegate().handleTokenRequest(params);
    }

    private AccessTokenService getDelegate() {
        delegate.setMessageContext(getMessageContext());
        configurer.accept(delegate);
        return delegate;
    }

    @RequestScoped
    @Typed(LazyImpl.class)
    static class LazyImpl extends AccessTokenService implements OAuth2Application.Defaults {
        @Inject
        private OAuth2Configurer configurer;

        @Override // don't fail without a client
        protected Client getClientFromBasicAuthScheme(final MultivaluedMap<String, String> params) {
            final List<String> authorization = getMessageContext().getHttpHeaders().getRequestHeader("Authorization");
            if (authorization == null || authorization.isEmpty()) {
                if (!configurer.getConfiguration().isForceClient()) {
                    return DEFAULT_CLIENT;
                }
            }
            return super.getClientFromBasicAuthScheme(params);
        }
    }
}

public class BuckAddDependencyIntention extends BaseIntentionAction {
  private static Logger LOGGER = Logger.getInstance(BuckAddDependencyIntention.class);

  /**
   * Creates an {@link com.intellij.codeInsight.intention.IntentionAction} that will create an
   * dependency edge in both the Buck target graph and IntelliJ module graph from the nodes for the
   * given reference element to those of the given psiClass.
   *
   * <p>Note that this intention can fail to be created if either side of the edge cannot be
   * resolved to a buck file in a buck cell, in which case this method returns null. Also, invoking
   * this intention may fail to create edges in either the Buck target graph or the IntelliJ module
   * graph (or both).
   */
  @Nullable
  public static BuckAddDependencyIntention create(
      PsiJavaCodeReferenceElement referenceElement, PsiClass psiClass) {
    VirtualFile editSourceFile = referenceElement.getContainingFile().getVirtualFile();
    if (editSourceFile == null) {
      return null;
    }
    Project project = referenceElement.getProject();
    BuckTargetLocator buckTargetLocator = BuckTargetLocator.getInstance(project);
    VirtualFile editBuildFile =
        buckTargetLocator.findBuckFileForVirtualFile(editSourceFile).orElse(null);
    if (editBuildFile == null) {
      return null;
    }
    VirtualFile importSourceFile = psiClass.getContainingFile().getVirtualFile();
    if (importSourceFile == null) {
      return null;
    }
    VirtualFile importBuildFile =
        buckTargetLocator.findBuckFileForVirtualFile(importSourceFile).orElse(null);
    if (importBuildFile == null) {
      return null;
    }
    if (importBuildFile.equals(editBuildFile)) {
      return null;
    }
    ProjectFileIndex projectFileIndex = ProjectFileIndex.getInstance(project);
    Module editModule = projectFileIndex.getModuleForFile(editSourceFile);
    if (editModule == null) {
      return null;
    }
    Module importModule = projectFileIndex.getModuleForFile(importSourceFile);
    if (importModule == null) {
      return null;
    }
    BuckTarget editSourceTarget =
        buckTargetLocator
            .findTargetPatternForVirtualFile(editSourceFile)
            .flatMap(BuckTargetPattern::asBuckTarget)
            .orElse(null);
    if (editSourceTarget == null) {
      return null;
    }
    BuckTarget importSourceTarget =
        buckTargetLocator
            .findTargetPatternForVirtualFile(importSourceFile)
            .flatMap(BuckTargetPattern::asBuckTarget)
            .orElse(null);
    if (importSourceTarget == null) {
      return null;
    }
    return new BuckAddDependencyIntention(
        project,
        referenceElement,
        editBuildFile,
        editSourceFile,
        editSourceTarget,
        editModule,
        psiClass,
        importBuildFile,
        importSourceFile,
        importSourceTarget,
        importModule);
  }

