@Override
public int nextDoc() throws IOException {
    if (docNo == NO_MORE_DOCS) {
        return docNo;
    }

    if (firstTime) {
        firstTime = false;
        // get first doc of context scorer
        int docId = contextScorer.nextDoc();
        if (docId != NO_MORE_DOCS) {
            contextNo = docId;
        }
    }
    // move to next candidate
    do {
        docNo++;
    } while (reader.isDeleted(docNo) && docNo < reader.maxDoc());

    // check with contextScorer
    while (contextNo != -1 && contextNo == docNo) {
        docNo++;
        int docId = contextScorer.nextDoc();
        contextNo = docId == NO_MORE_DOCS ? -1 : docId;
    }
    if (docNo >= reader.maxDoc()) {
        docNo = NO_MORE_DOCS;
    }
    return docNo;
}

public class CurrentStateSnapshot extends AbstractDataSnapshot<CurrentState> {
  private Set<PropertyKey> _updatedStateKeys = null;
  private Map<PropertyKey, CurrentState> _prevStateMap = null;

  public CurrentStateSnapshot(final Map<PropertyKey, CurrentState> currentStateMap) {
    super(currentStateMap);
  }

  public CurrentStateSnapshot(final Map<PropertyKey, CurrentState> currentStateMap,
      final Map<PropertyKey, CurrentState> prevStateMap, final Set<PropertyKey> updatedStateKeys) {
    this(currentStateMap);
    _updatedStateKeys = Collections.unmodifiableSet(new HashSet<>(updatedStateKeys));
    _prevStateMap = Collections.unmodifiableMap(new HashMap<>(prevStateMap));
  }

  /**
   * Return the end times of all recent changed current states update.
   */
  public Map<PropertyKey, Map<String, Long>> getNewCurrentStateEndTimes() {
    Map<PropertyKey, Map<String, Long>> endTimeMap = new HashMap<>();
    if (_updatedStateKeys != null && _prevStateMap != null) {
      // Note if the prev state map is empty, this is the first time refresh.
      // So the update is not considered as "recent" change.
      for (PropertyKey propertyKey : _updatedStateKeys) {
        CurrentState prevState = _prevStateMap.get(propertyKey);
        CurrentState curState = _properties.get(propertyKey);

        Map<String, Long> partitionUpdateEndTimes = null;
        for (String partition : curState.getPartitionStateMap().keySet()) {
          long newEndTime = curState.getEndTime(partition);
          if (prevState == null || prevState.getEndTime(partition) < newEndTime) {
            if (partitionUpdateEndTimes == null) {
              partitionUpdateEndTimes = new HashMap<>();
            }
            partitionUpdateEndTimes.put(partition, newEndTime);
          }
        }

        if (partitionUpdateEndTimes != null) {
          endTimeMap.put(propertyKey, partitionUpdateEndTimes);
        }
      }
    }
    return endTimeMap;
  }
}

public class OpenJDK8ServerALPNProcessor implements ALPNProcessor.Server
{
    private static final Logger LOG = Log.getLogger(OpenJDK8ServerALPNProcessor.class);

    @Override
    public void init()
    {
        if (JavaVersion.VERSION.getPlatform()!=8)
            throw new IllegalStateException(this + " not applicable for java "+JavaVersion.VERSION);
        if (ALPN.class.getClassLoader()!=null)
            throw new IllegalStateException(ALPN.class.getName() + " must be on JVM boot classpath");
        if (LOG.isDebugEnabled())
            ALPN.debug = true;
    }

    @Override
    public boolean appliesTo(SSLEngine sslEngine)
    {
        return sslEngine.getClass().getName().startsWith("sun.security.ssl.");
    }

    @Override
    public void configure(SSLEngine sslEngine, Connection connection)
    {
        connection.addListener(new ALPNListener((ALPNServerConnection)connection));
    }

    private final class ALPNListener implements ALPN.ServerProvider, Connection.Listener
    {
        private final ALPNServerConnection alpnConnection;

        private ALPNListener(ALPNServerConnection connection)
        {
            alpnConnection = connection;
        }

        @Override
        public void onOpened(Connection connection)
        {
            if (LOG.isDebugEnabled())
                LOG.debug("onOpened {}", alpnConnection);
            ALPN.put(alpnConnection.getSSLEngine(), this);
        }

        @Override
        public void onClosed(Connection connection)
        {
            if (LOG.isDebugEnabled())
                LOG.debug("onClosed {}", alpnConnection);
            ALPN.remove(alpnConnection.getSSLEngine());
        }

        @Override
        public void unsupported()
        {
            if (LOG.isDebugEnabled())
                LOG.debug("unsupported {}", alpnConnection);
            alpnConnection.select(Collections.emptyList());
        }

        @Override
        public String select(List<String> protocols) throws SSLException
        {
            if (LOG.isDebugEnabled())
                LOG.debug("select {} {}", alpnConnection, protocols);
            alpnConnection.select(protocols);
            return alpnConnection.getProtocol();
        }
    }
}

public String toString() {

    if (subject == null || pubKey == null || interval == null
        || issuer == null || algId == null || serialNum == null) {
            throw new NullPointerException("X.509 cert is incomplete");
    }
    StringBuilder sb = new StringBuilder();

    sb.append("[\n");
    sb.append("  " + version.toString() + "\n");
    sb.append("  Subject: " + subject.toString() + "\n");
    sb.append("  Signature Algorithm: " + algId.toString() + "\n");
    sb.append("  Key:  " + pubKey.toString() + "\n");
    sb.append("  " + interval.toString() + "\n");
    sb.append("  Issuer: " + issuer.toString() + "\n");
    sb.append("  " + serialNum.toString() + "\n");

    // optional v2, v3 extras
    if (issuerUniqueId != null) {
        sb.append("  Issuer Id:\n" + issuerUniqueId.toString() + "\n");
    }
    if (subjectUniqueId != null) {
        sb.append("  Subject Id:\n" + subjectUniqueId.toString() + "\n");
    }
    if (extensions != null) {
        Collection<Extension> allExts = extensions.getAllExtensions();
        Extension[] exts = allExts.toArray(new Extension[0]);
        sb.append("\nCertificate Extensions: " + exts.length);
        for (int i = 0; i < exts.length; i++) {
            sb.append("\n[" + (i+1) + "]: ");
            Extension ext = exts[i];
            try {
                if (OIDMap.getClass(ext.getExtensionId()) == null) {
                    sb.append(ext.toString());
                    byte[] extValue = ext.getExtensionValue();
                    if (extValue != null) {
                        DerOutputStream out = new DerOutputStream();
                        out.putOctetString(extValue);
                        extValue = out.toByteArray();
                        HexDumpEncoder enc = new HexDumpEncoder();
                        sb.append("Extension unknown: "
                                  + "DER encoded OCTET string =\n"
                                  + enc.encodeBuffer(extValue) + "\n");
                    }
                } else
                    sb.append(ext.toString()); //sub-class exists
            } catch (Exception e) {
                sb.append(", Error parsing this extension");
            }
        }
        Map<String,Extension> invalid = extensions.getUnparseableExtensions();
        if (invalid.isEmpty() == false) {
            sb.append("\nUnparseable certificate extensions: " + invalid.size());
            int i = 1;
            for (Extension ext : invalid.values()) {
                sb.append("\n[" + (i++) + "]: ");
                sb.append(ext);
            }
        }
    }
    sb.append("\n]");
    return sb.toString();
}

