@RBuiltin(name = "isatty", kind = INTERNAL, parameterNames = {"con"}, behavior = PURE)
public abstract class IsATTY extends RBuiltinNode.Arg1 {

    static {
        Casts.noCasts(IsATTY.class);
    }

    @Specialization
    @TruffleBoundary
    protected byte isATTYNonConnection(RAbstractIntVector con) {
        if (con.getLength() == 1) {
            RStringVector clazz = ClassHierarchyNode.getClassHierarchy(con);
            for (int i = 0; i < clazz.getLength(); i++) {
                if ("connection".equals(clazz.getDataAt(i))) {
                    RConnection connection = RContext.getInstance().stateRConnection.getConnection(con.getDataAt(0), false);
                    if (connection != null) {
                        return RRuntime.asLogical(connection instanceof StdConnection);
                    } else {
                        return RRuntime.LOGICAL_FALSE;
                    }
                }
            }
        }
        return RRuntime.LOGICAL_FALSE;
    }

    @Fallback
    @TruffleBoundary
    protected byte isATTYNonConnection(@SuppressWarnings("unused") Object con) {
        return RRuntime.LOGICAL_FALSE;
    }
}

private static class ModelElementDetermingModelVisitor implements IModelElementVisitor {

	private int startLine;

	private int endLine;

	private final IFile file;

	private IModelElement element;

	public ModelElementDetermingModelVisitor(final int startLine, final int endLine, final IFile file) {
		if (startLine + 1 == endLine) {
			this.startLine = startLine + 1;
		}
		else {
			this.startLine = startLine;
		}
		this.endLine = endLine;
		this.file = file;
	}

	public IModelElement getElement() {
		return element;
	}

	public boolean visit(IModelElement element, IProgressMonitor monitor) {
		if (element instanceof ISourceModelElement) {
			ISourceModelElement sourceElement = (ISourceModelElement) element;
			if (sourceElement.getElementResource().equals(file)
					&& (sourceElement.getElementStartLine() <= startLine || sourceElement.getElementStartLine() - 1 <= startLine)
					&& endLine <= sourceElement.getElementEndLine()) {
				this.element = element;

				if (sourceElement.getElementStartLine() == startLine
						&& endLine == sourceElement.getElementEndLine()) {
					startLine = -1;
					endLine = -1;
					return false;
				}
				return true;
			}
			return false;
		}
		else if (element instanceof IBeansConfig) {
			return true;
		}
		else {
			return false;
		}
	}
}

