public boolean readFont(FontFileReader in, String header, String name) throws IOException {
    initializeFont(in);
    /*
     * Check if TrueType collection, and that the name
     * exists in the collection
     */
    if (!checkTTC(header, name)) {
        if (name == null) {
            throw new IllegalArgumentException(
                "For TrueType collection you must specify which font "
                + "to select (-ttcname)");
        } else {
            throw new IOException(
                "Name does not exist in the TrueType collection: " + name);
        }
    }

    readDirTabs();
    readFontHeader();
    getNumGlyphs();
    if (log.isDebugEnabled()) {
        log.debug("Number of glyphs in font: " + numberOfGlyphs);
    }
    readHorizontalHeader();
    readHorizontalMetrics();
    initAnsiWidths();
    readPostScript();
    readOS2();
    determineAscDesc();

    readName();
    boolean pcltFound = readPCLT();
    // Read cmap table and fill in ansiwidths
    boolean valid = readCMAP();
    if (!valid) {
        return false;
    }

    // Create cmaps for bfentries
    createCMaps();
    updateBBoxAndOffset();

    if (useKerning) {
        readKerning();
    }
    handleCharacterSpacing(in);

    guessVerticalMetricsFromGlyphBBox();
    return true;
}

public class RunRuleActionHandler extends BaseModuleHandler<Action> implements ActionHandler {

    /**
     * The UID for this handler for identification in the factory.
     */
    public static final String UID = "core.RunRuleAction";

    /**
     * the key for the 'rulesUIDs' property of the {@link Action}.
     */
    private static final String RULE_UIDS_KEY = "ruleUIDs";
    private static final String CONSIDER_CONDITIONS_KEY = "considerConditions";

    /**
     * The logger
     */
    private final Logger logger = LoggerFactory.getLogger(RunRuleActionHandler.class);

    /**
     * the UIDs of the rules to be executed.
     */
    private final List<String> ruleUIDs;

    /**
     * boolean to express if the conditions should be considered, defaults to
     * true;
     */
    private boolean considerConditions = true;

    @SuppressWarnings("unchecked")
    public RunRuleActionHandler(final Action module) {
        super(module);
        final Configuration config = module.getConfiguration();
        if (config.getProperties().isEmpty()) {
            throw new IllegalArgumentException("'Configuration' can not be empty.");
        }

        ruleUIDs = (List<String>) config.get(RULE_UIDS_KEY);
        if (ruleUIDs == null) {
            throw new IllegalArgumentException("'ruleUIDs' property must not be null.");
        }
        if (config.get(CONSIDER_CONDITIONS_KEY) != null && config.get(CONSIDER_CONDITIONS_KEY) instanceof Boolean) {
            this.considerConditions = ((Boolean) config.get(CONSIDER_CONDITIONS_KEY)).booleanValue();
        }
    }

    @Override
    public Map<String, Object> execute(Map<String, Object> context) {
        // execute each rule after the other; at the moment synchronously
        for (String uid : ruleUIDs) {
            if (callback != null) {
                callback.runNow(uid, considerConditions, context);
            } else {
                logger.warn("Action is not applied to {} because rule engine is not available.", uid);
            }
        }
        // no outputs from this module
        return null;
    }
}

private static boolean parseMsAcmCodecPrivate(ParsableByteArray buffer) throws ParserException {
  try {
    int formatTag = buffer.readLittleEndianUnsignedShort();
    if (formatTag == WAVE_FORMAT_PCM) {
      return true;
    } else if (formatTag == WAVE_FORMAT_EXTENSIBLE) {
      buffer.setPosition(WAVE_FORMAT_SIZE + 6); // unionSamples(2), channelMask(4)
      return buffer.readLong() == WAVE_SUBFORMAT_PCM.getMostSignificantBits()
          && buffer.readLong() == WAVE_SUBFORMAT_PCM.getLeastSignificantBits();
    } else {
      return false;
    }
  } catch (ArrayIndexOutOfBoundsException e) {
    throw new ParserException("Error parsing MS/ACM codec private");
  }
}

private static boolean handleAspectAnnotation(RuntimeAnnos runtimeAnnotations, AjAttributeStruct struct) {
	AnnotationGen aspect = getAnnotation(runtimeAnnotations, AjcMemberMaker.ASPECT_ANNOTATION);
	if (aspect != null) {
		// semantic check for inheritance (only one level up)
		boolean extendsAspect = false;
		if (!"java.lang.Object".equals(struct.enclosingType.getSuperclass().getName())) {
			if (!struct.enclosingType.getSuperclass().isAbstract() && struct.enclosingType.getSuperclass().isAspect()) {
				reportError("cannot extend a concrete aspect", struct);
				return false;
			}
			extendsAspect = struct.enclosingType.getSuperclass().isAspect();
		}

		NameValuePair aspectPerClause = getAnnotationElement(aspect, VALUE);
		final PerClause perClause;
		if (aspectPerClause == null) {
			// empty value means singleton unless inherited
			if (!extendsAspect) {
				perClause = new PerSingleton();
			} else {
				perClause = new PerFromSuper(struct.enclosingType.getSuperclass().getPerClause().getKind());
			}
		} else {
			String perX = aspectPerClause.getValue().stringifyValue();
			if (perX == null || perX.length() <= 0) {
				perClause = new PerSingleton();
			} else {
				perClause = parsePerClausePointcut(perX, struct);
			}
		}
		if (perClause == null) {
			// could not parse it, ignore the aspect
			return false;
		} else {
			perClause.setLocation(struct.context, -1, -1);// struct.context.getOffset(),
			// struct.context.getOffset()+1);//FIXME
			// AVASM
			// Not setting version here
			// struct.ajAttributes.add(new AjAttribute.WeaverVersionInfo());
			AjAttribute.Aspect aspectAttribute = new AjAttribute.Aspect(perClause);
			struct.ajAttributes.add(aspectAttribute);
			FormalBinding[] bindings = new org.aspectj.weaver.patterns.FormalBinding[0];
			final IScope binding;
			binding = new BindingScope(struct.enclosingType, struct.context, bindings);

			// // we can't resolve here since the perclause typically refers
			// to pointcuts
			// // defined in the aspect that we haven't told the
			// BcelObjectType about yet.
			//
			// perClause.resolve(binding);

			// so we prepare to do it later...
			aspectAttribute.setResolutionScope(binding);
			return true;
		}
	}
	return false;
}

