	@Override
	public TypingJudgmentEnvironment getEnvironment() {
		return env_G;
	}

	@Override
	public void setEnvironment(TypingJudgmentEnvironment environment) {
		if (environment != null)
			env_G = environment;
	}

	@Override
	public RuntimeRule newInstance() {
		return new NotOccurVarInArrowTypeRule("NotOccurVarInArrow", "|-", "!-");
	}

	@Override
	public void applyImpl() throws RuleFailedException {

		applyNotoccurRule(env_G, var_t1, var_t2.getValue().getLeft());

		applyNotoccurRule(env_G, var_t1, var_t2.getValue().getRight());

		// final check for variable initialization

	}

	@Override
	protected String ruleFailureMessage() {
		return "type variable " + stringRep(var_t1.getValue().getTypevarName())
				+ " occurs in (" + stringRep(var_t2.getValue().getLeft())
				+ ") -> (" + stringRep(var_t2.getValue().getRight()) + ")";
	}

}

public class FoldLeft<T> implements Function<Generator<T>, T>, BinaryFunction<Generator<T>, T, T> {

    /**
     * Helper procedure.
     *
     * @param <T> the returned evaluation type.
     */
    private static class FoldLeftHelper<T> implements Procedure<T> {
        /**
         * The wrapped function.
         */
        private final BinaryFunction<? super T, ? super T, ? extends T> function;
        /**
         * The seed object.
         */
        private T seed;
        /**
         * Flag to check the helper started or not.
         */
        private boolean started;

        /**
         * Create a seedless FoldLeftHelper.
         *
         * @param function The wrapped function
         */
        public FoldLeftHelper(BinaryFunction<? super T, ? super T, ? extends T> function) {
            this(null, function);
        }

        /**
         * Create a new FoldLeftHelper.
         *
         * @param seed initial left-side argument
         * @param function The wrapped function
         */
        FoldLeftHelper(T seed, BinaryFunction<? super T, ? super T, ? extends T> function) {
            this.seed = seed;
            started = seed != null ? true : false;
            this.function = function;
        }

        /**
         * {@inheritDoc}
         */
        public void run(T obj) {
            if (!started) {
                seed = obj;
                started = true;
            } else {
                seed = function.evaluate(seed, obj);
            }
        }

        /**
         * Get current result.
         * @return Object
         */
        T getResult() {
            return started ? seed : null;
        }

    }

    /**
     * {@link BinaryFunction} to apply to each (seed, next).
     */
    private final BinaryFunction<? super T, ? super T, ? extends T> function;

    /**
     * Create a new FoldLeft.
     * @param func {@link BinaryFunction} to apply to each (seed, next)
     */
    public FoldLeft(BinaryFunction<? super T, ? super T, ? extends T> func) {
        this.function = func;
    }

    /**
     * {@inheritDoc}
     * @param obj {@link Generator} to transform
     */
    public final T evaluate(Generator<T> obj) {
        FoldLeftHelper<T> helper = new FoldLeftHelper<T>(function);
        obj.run(helper);
        return helper.getResult();
    }

    /**
     * {@inheritDoc}
     * @param left {@link Generator} to transform
     * @param right initial left-side seed object
     */
    public final T evaluate(Generator<T> left, T right) {
        FoldLeftHelper<T> helper = new FoldLeftHelper<T>(right, function);
        left.run(helper);
        return helper.getResult();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof FoldLeft<?>)) {
            return false;
        }
        return ((FoldLeft<?>) obj).function.equals(function);
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public int hashCode() {
        return "FoldLeft".hashCode() << 2 ^ function.hashCode();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toString() {
        return "FoldLeft<" + function + ">";
    }

}

public int tightMarshal1(OpenWireFormat wireFormat, Object o, BooleanStream bs) throws IOException {

    MessageDispatchNotification info = (MessageDispatchNotification)o;

    int rc = super.tightMarshal1(wireFormat, o, bs);
    rc += tightMarshalCachedObject1(wireFormat, (DataStructure)info.getConsumerId(), bs);
    rc += tightMarshalCachedObject1(wireFormat, (DataStructure)info.getDestination(), bs);
    rc += tightMarshalLong1(wireFormat, info.getDeliverySequenceId(), bs);
    rc += tightMarshalNestedObject1(wireFormat, (DataStructure)info.getMessageId(), bs);

    return rc + 0;
}

public float computeTableUnit(PercentBaseContext percentBaseContext, int contentAreaIPD) {

    int sumCols = 0;
    float factors = 0;
    float unit = 0;

    /* calculate the total width (specified absolute/percentages),
     * and work out the total number of factors to use to distribute
     * the remaining space (if any)
     */
    for (Object colWidth1 : colWidths) {
        Length colWidth = (Length) colWidth1;
        if (colWidth != null) {
            sumCols += colWidth.getValue(percentBaseContext);
            if (colWidth instanceof RelativeNumericProperty) {
                factors += ((RelativeNumericProperty) colWidth).getTableUnits();
            } else if (colWidth instanceof TableColLength) {
                factors += ((TableColLength) colWidth).getTableUnits();
            }
        }
    }

    /* distribute the remaining space over the accumulated
     * factors (if any)
     */
    if (factors > 0) {
        if (sumCols < contentAreaIPD) {
            unit = (contentAreaIPD - sumCols) / factors;
        } else {
            log.warn("No space remaining to distribute over columns.");
        }
    }

    return unit;
}

