	/**
	 * An action depending on another action for providing additional information like the id of a parent entity.
	 *
	 * @author Jens Schauder
	 */
	interface WithDependingOn<T> extends WithPropertyPath<T>, WithEntity<T> {

		/**
		 * The {@link DbAction} of a parent entity, possibly the aggregate root. This is used to obtain values needed to
		 * persist the entity, that are not part of the current entity, especially the id of the parent, which might only
		 * become available once the parent entity got persisted.
		 *
		 * @return Guaranteed to be not {@code null}.
		 * @see #getQualifiers()
		 */
		WithEntity<?> getDependingOn();

		/**
		 * Additional values to be set during insert or update statements.
		 * <p>
		 * Values come from parent entities but one might also add values manually.
		 *
		 * @return Guaranteed to be not {@code null}.
		 */
		Map<PersistentPropertyPath<RelationalPersistentProperty>, Object> getQualifiers();

		@Override
		default Class<T> getEntityType() {
			return WithEntity.super.getEntityType();
		}
	}

	/**
	 * A {@link DbAction} that stores the information of a single entity in the database.
	 *
	 * @author Jens Schauder
	 */
	interface WithEntity<T> extends DbAction<T> {

		/**
		 * @return the entity to persist. Guaranteed to be not {@code null}.
		 */
		T getEntity();

		@SuppressWarnings("unchecked")
		@Override
		default Class<T> getEntityType() {
			return (Class<T>) getEntity().getClass();
		}
	}

	/**
	 * A {@link DbAction} that may "update" its entity. In order to support immutable entities this requires at least
	 * potentially creating a new instance, which this interface makes available.
	 *
	 * @author Jens Schauder
	 */
	interface WithGeneratedId<T> extends WithEntity<T> {

		/**
		 * @return the entity to persist. Guaranteed to be not {@code null}.
		 */
		@Nullable
		Object getGeneratedId();

		@SuppressWarnings("unchecked")
		@Override
		default Class<T> getEntityType() {
			return (Class<T>) getEntity().getClass();
		}
	}

	/**
	 * A {@link DbAction} not operation on the root of an aggregate but on its contained entities.
	 *
	 * @author Jens Schauder
	 */
	interface WithPropertyPath<T> extends DbAction<T> {

		/**
		 * @return the path from the aggregate root to the affected entity
		 */
		PersistentPropertyPath<RelationalPersistentProperty> getPropertyPath();

		@SuppressWarnings("unchecked")
		@Override
		default Class<T> getEntityType() {
			return (Class<T>) getPropertyPath().getRequiredLeafProperty().getActualType();
		}
	}
}

public class ClientIdentity implements Serializable {

    private static final long serialVersionUID = -8262100681930834834L;
    private String            destination;
    private short             clientId;
    private String            filter;

    public ClientIdentity(){

    }

    public ClientIdentity(String destination, short clientId){
        this.clientId = clientId;
        this.destination = destination;
    }

    public ClientIdentity(String destination, short clientId, String filter){
        this.clientId = clientId;
        this.destination = destination;
        this.filter = filter;
    }

    public Boolean hasFilter() {
        if (filter == null) {
            return false;
        }
        return StringUtils.isNotBlank(filter);
    }

    // ======== setter =========

    public String getDestination() {
        return destination;
    }

    public short getClientId() {
        return clientId;
    }

    public void setClientId(short clientId) {
        this.clientId = clientId;
    }

    public void setDestination(String destination) {
        this.destination = destination;
    }

    public String getFilter() {
        return filter;
    }

    public void setFilter(String filter) {
        this.filter = filter;
    }

    public String toString() {
        return ToStringBuilder.reflectionToString(this, CanalToStringStyle.DEFAULT_STYLE);
    }

    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + clientId;
        result = prime * result + ((destination == null) ? 0 : destination.hashCode());
        return result;
    }

    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj == null) {
            return false;
        }
        if (!(obj instanceof ClientIdentity)) {
            return false;
        }
        ClientIdentity other = (ClientIdentity) obj;
        if (clientId != other.clientId) {
            return false;
        }
        if (destination == null) {
            if (other.destination != null) {
                return false;
            }
        } else if (!destination.equals(other.destination)) {
            return false;
        }
        return true;
    }

}

public static class PackageMapDistributor extends AtlasVirtualFile.DistributorBase {
    private final PackageDistribution packageDistribution;
    private final ExecutorService executorService;

    PackageMapDistributor(ApplicationWriter writer, PackageDistribution packageDistribution, ExecutorService executorService) {
        super(writer);
        this.packageDistribution = packageDistribution;
        this.executorService = executorService;
    }

    public Map<Integer, AtlasVirtualFile> run() throws ExecutionException, IOException {
        assert this.nameToFileMap.size() == 1;

        assert this.nameToFileMap.containsKey(0);

        int maxReferencedIndex = this.packageDistribution.maxReferencedIndex();

        for(int index = 1; index <= maxReferencedIndex; ++index) {
            AtlasVirtualFile file = new AtlasVirtualFile(index, this.writer.namingLens);
            this.nameToFileMap.put(index, file);
        }

        this.fillForMainDexList(this.classes);
        this.classes = this.sortClassesByPackage(this.classes, this.originalNames);
        Set<String> usedPrefixes = this.fillForDistribution(this.classes, this.originalNames);
        Map newAssignments;
        if (this.classes.isEmpty()) {
            newAssignments = Collections.emptyMap();
        } else {
            newAssignments = (new AtlasVirtualFile.PackageSplitPopulator(this.nameToFileMap, this.classes, this.originalNames, usedPrefixes, this.application.dexItemFactory, AtlasVirtualFile.FillStrategy.LEAVE_SPACE_FOR_GROWTH, this.writer.namingLens)).call();
            if (!newAssignments.isEmpty() && this.nameToFileMap.size() > 1) {
                System.err.println(" * The used package map is missing entries. The following default mappings have been used:");
                this.writeAssignments(newAssignments, new OutputStreamWriter(System.err));
                System.err.println(" * Consider updating the map.");
            }
        }

        Path newPackageMap = Paths.get("package.map");
        System.out.println(" - " + newPackageMap.toString());
        PackageDistribution.writePackageToFileMap(newPackageMap, newAssignments, this.packageDistribution);
        return this.nameToFileMap;
    }

    private Set<String> fillForDistribution(Set<DexProgramClass> classes, Map<DexProgramClass, String> originalNames) throws ExecutionException {
        Set<String> usedPrefixes = null;
        if (this.packageDistribution != null) {
            ArrayList<Future<List<DexProgramClass>>> futures = new ArrayList(this.nameToFileMap.size());
            usedPrefixes = this.packageDistribution.getFiles();
            Iterator var5 = this.nameToFileMap.values().iterator();

            while(var5.hasNext()) {
                AtlasVirtualFile file = (AtlasVirtualFile)var5.next();
                AtlasVirtualFile.PackageMapPopulator populator = new AtlasVirtualFile.PackageMapPopulator(file, classes, this.packageDistribution, originalNames);
                futures.add(this.executorService.submit(populator));
            }

            ThreadUtils.awaitFutures(futures).forEach(classes::removeAll);
        }

        return usedPrefixes;
    }

    private void writeAssignments(Map<String, Integer> assignments, Writer output) throws IOException {
        Iterator var3 = assignments.entrySet().iterator();

        while(var3.hasNext()) {
            Map.Entry<String, Integer> entry = (Map.Entry)var3.next();
            output.write("    ");
            PackageDistribution.formatEntry(entry, output);
            output.write("\n");
        }

        output.flush();
    }
}

	private void createTriggerDependencies
	(
        TriggerDescriptorList       tdl,
		Dependent					dependent
	)
		throws StandardException
	{
		CompilerContext 			compilerContext = getCompilerContext();

        for (TriggerDescriptor td : tdl) {
            /*
            ** The dependent now depends on this trigger.
            ** The default dependent is the statement being compiled.
            */
            if (dependent == null) {
                compilerContext.createDependency(td);
            } else {
                compilerContext.createDependency(dependent, td);
            }
        }
	}

private void setOptionalAttribute(BeanDefinitionBuilder builder,
			Map<String, Object> providedProperties,
			String propertyPrefix,
			String attributeValue,
			String attributeName) {
	String propertyKey;
	if ("username".equals(attributeName)) {
		String userKey = (propertyPrefix != null ?
				propertyPrefix + "user" :
				"user");
		if (providedProperties.containsKey(userKey)) {
			propertyKey = userKey;
		}
		else {
			propertyKey = (propertyPrefix != null ?
					propertyPrefix + attributeName :
					attributeName);
		}
	}
	else {
		propertyKey = (propertyPrefix != null ?
				propertyPrefix + attributeToPropertyMap.get(attributeName) :
				attributeToPropertyMap.get(attributeName));
	}

	if (StringUtils.hasText(attributeValue)) {
		if (logger.isDebugEnabled()) {
			if ("password".equals(attributeName)) {
				logger.debug("Registering optional attribute " + attributeToPropertyMap.get(attributeName) +
						" with attribute value ******");
			}
			else {
				logger.debug("Registering optional attribute " + attributeToPropertyMap.get(attributeName) +
						" with attribute value " + attributeValue);
			}
		}
		builder.addPropertyValue(attributeToPropertyMap.get(attributeName), attributeValue);
	}
	else if (providedProperties.containsKey(propertyKey)) {
		if (logger.isDebugEnabled()) {
			logger.debug("Registering optional attribute " + attributeToPropertyMap.get(attributeName) +
					" with property value " +
					("password".equals(attributeName) ? "******" : providedProperties.get(propertyKey)));
		}
		builder.addPropertyValue(attributeToPropertyMap.get(attributeName), providedProperties.get(propertyKey));
	}
	removeProvidedProperty(providedProperties, propertyKey);
}

