public class ParamTypeSpecVisitor extends VisitorBase {

    public ParamTypeSpecVisitor(Scope scope,
                                Definition defn,
                                XmlSchema schemaRef,
                                WSDLASTVisitor wsdlVisitor) {
        super(scope, defn, schemaRef, wsdlVisitor);
    }

    public void visit(AST node) {
        // <param_type_spec> ::= <base_type_spec>
        //                     | <string_type>
        //                     | <wstring_type>
        //                     | <scoped_name>


        Visitor visitor = null;


        if (PrimitiveTypesVisitor.accept(node)) {
            // base_type_spec
            visitor = new PrimitiveTypesVisitor(getScope(), definition, schema, schemas);
        } else if (StringVisitor.accept(node)) {
            // string_type_spec
            // wstring_type_spec
            visitor = new StringVisitor(getScope(), definition, schema, wsdlVisitor, null);

        } else if (ScopedNameVisitor.accept(getScope(), definition, schema, node, wsdlVisitor)) {
            // scoped_name
            visitor = new ScopedNameVisitor(getScope(), definition, schema, wsdlVisitor);

        } else {
            throw new RuntimeException("[ParamTypeSpecVisitor] Invalid IDL: unknown element "
                                       + node.toString());
        }

        visitor.visit(node);
        setSchemaType(visitor.getSchemaType());
        setCorbaType(visitor.getCorbaType());
        setFullyQualifiedName(visitor.getFullyQualifiedName());
    }
}

public abstract class AbstractSimpleExtractor<T> implements Extractor<T> {

  private static final Logger LOG = LoggerFactory.getLogger(AbstractSimpleExtractor.class);
  private static final int LOG_ERROR_LIMIT = 100;

  private int errors;
  private boolean errorOnLast;
  private final T defaultValue;
  private final TokenizerFactory scannerFactory;

  protected AbstractSimpleExtractor(T defaultValue) {
    this(defaultValue, TokenizerFactory.getDefaultInstance());
  }

  protected AbstractSimpleExtractor(T defaultValue, TokenizerFactory scannerFactory) {
    this.defaultValue = defaultValue;
    this.scannerFactory = scannerFactory;
  }

  @Override
  public void initialize() {
    this.errors = 0;
    this.errorOnLast = false;
  }

  @Override
  public T extract(String input) {
    errorOnLast = false;
    T res = defaultValue;
    try {
      res = doExtract(scannerFactory.create(input));
    } catch (Exception e) {
      errorOnLast = true;
      errors++;
      if (errors < LOG_ERROR_LIMIT) {
        LOG.error("Error occurred parsing input '{}' using extractor {}", input, this);
      }
    }
    return res;
  }

  @Override
  public boolean errorOnLastRecord() {
    return errorOnLast;
  }

  @Override
  public T getDefaultValue() {
    return defaultValue;
  }

  @Override
  public ExtractorStats getStats() {
    return new ExtractorStats(errors);
  }

  /**
   * Subclasses must override this method to return a new instance of the
   * class that this {@code Extractor} instance is designed to parse.
   * <p>Any runtime parsing exceptions from the given {@code Tokenizer} instance
   * should be thrown so that they may be caught by the error handling logic
   * inside of this class.
   * 
   * @param tokenizer The {@code Tokenizer} instance for the current record
   * @return A new instance of the type defined for this class
   */
  protected abstract T doExtract(Tokenizer tokenizer);
}

public static class setBlobMeta<I extends AsyncIface> extends org.apache.storm.thrift.AsyncProcessFunction<I, setBlobMeta_args, Void> {
  public setBlobMeta() {
    super("setBlobMeta");
  }

  public setBlobMeta_args getEmptyArgsInstance() {
    return new setBlobMeta_args();
  }

  public org.apache.storm.thrift.async.AsyncMethodCallback<Void> getResultHandler(final org.apache.storm.thrift.server.AbstractNonblockingServer.AsyncFrameBuffer fb, final int seqid) {
    final org.apache.storm.thrift.AsyncProcessFunction fcall = this;
    return new org.apache.storm.thrift.async.AsyncMethodCallback<Void>() { 
      public void onComplete(Void o) {
        setBlobMeta_result result = new setBlobMeta_result();
        try {
          fcall.sendResponse(fb, result, org.apache.storm.thrift.protocol.TMessageType.REPLY,seqid);
        } catch (org.apache.storm.thrift.transport.TTransportException e) {
          _LOGGER.error("TTransportException writing to internal frame buffer", e);
          fb.close();
        } catch (java.lang.Exception e) {
          _LOGGER.error("Exception writing to internal frame buffer", e);
          onError(e);
        }
      }
      public void onError(java.lang.Exception e) {
        byte msgType = org.apache.storm.thrift.protocol.TMessageType.REPLY;
        org.apache.storm.thrift.TSerializable msg;
        setBlobMeta_result result = new setBlobMeta_result();
        if (e instanceof AuthorizationException) {
          result.aze = (AuthorizationException) e;
          result.set_aze_isSet(true);
          msg = result;
        } else if (e instanceof KeyNotFoundException) {
          result.knf = (KeyNotFoundException) e;
          result.set_knf_isSet(true);
          msg = result;
        } else if (e instanceof org.apache.storm.thrift.transport.TTransportException) {
          _LOGGER.error("TTransportException inside handler", e);
          fb.close();
          return;
        } else if (e instanceof org.apache.storm.thrift.TApplicationException) {
          _LOGGER.error("TApplicationException inside handler", e);
          msgType = org.apache.storm.thrift.protocol.TMessageType.EXCEPTION;
          msg = (org.apache.storm.thrift.TApplicationException)e;
        } else {
          _LOGGER.error("Exception inside handler", e);
          msgType = org.apache.storm.thrift.protocol.TMessageType.EXCEPTION;
          msg = new org.apache.storm.thrift.TApplicationException(org.apache.storm.thrift.TApplicationException.INTERNAL_ERROR, e.getMessage());
        }
        try {
          fcall.sendResponse(fb,msg,msgType,seqid);
        } catch (java.lang.Exception ex) {
          _LOGGER.error("Exception writing to internal frame buffer", ex);
          fb.close();
        }
      }
    };
  }

  protected boolean isOneway() {
    return false;
  }

  public void start(I iface, setBlobMeta_args args, org.apache.storm.thrift.async.AsyncMethodCallback<Void> resultHandler) throws org.apache.storm.thrift.TException {
    iface.setBlobMeta(args.key, args.meta,resultHandler);
  }
}

