public static class PutAllEntryData {

  final Object key;

  private Object value;

  private final Object oldValue;

  private final Operation op;

  private EventID eventID;

  transient EntryEventImpl event;

  private Integer bucketId = Integer.valueOf(-1);

  protected transient boolean callbacksInvoked = false;

  public FilterRoutingInfo filterRouting;

  // One flags byte for all booleans
  protected byte flags = 0x00;

  // TODO: Yogesh, this should be intialized and sent on wire only when
  // parallel wan is enabled
  private Long tailKey = 0L;

  public VersionTag versionTag;

  transient boolean inhibitDistribution;

  /**
   * Constructor to use when preparing to send putall data out
   */
  public PutAllEntryData(EntryEventImpl event) {

    this.key = event.getKey();
    this.value = event.getRawNewValueAsHeapObject();
    Object oldValue = event.getRawOldValueAsHeapObject();

    if (oldValue == Token.NOT_AVAILABLE || Token.isRemoved(oldValue)) {
      this.oldValue = null;
    } else {
      this.oldValue = oldValue;
    }

    this.op = event.getOperation();
    this.eventID = event.getEventId();
    this.tailKey = event.getTailKey();
    this.versionTag = event.getVersionTag();

    setNotifyOnly(!event.getInvokePRCallbacks());
    setCallbacksInvoked(event.callbacksInvoked());
    setPossibleDuplicate(event.isPossibleDuplicate());
    setInhibitDistribution(event.getInhibitDistribution());
  }

  /**
   * Constructor to use when receiving a putall from someone else
   */
  public PutAllEntryData(DataInput in, EventID baseEventID, int idx, Version version,
      ByteArrayDataInput bytesIn) throws IOException, ClassNotFoundException {
    this.key = DataSerializer.readObject(in);
    byte flgs = in.readByte();
    if ((flgs & IS_OBJECT) != 0) {
      this.value = DataSerializer.readObject(in);
    } else {
      byte[] bb = DataSerializer.readByteArray(in);
      if ((flgs & IS_CACHED_DESER) != 0) {
        this.value = new FutureCachedDeserializable(bb);
      } else {
        this.value = bb;
      }
    }
    this.oldValue = null;
    this.op = Operation.fromOrdinal(in.readByte());
    this.flags = in.readByte();
    if ((this.flags & FILTER_ROUTING) != 0) {
      this.filterRouting = (FilterRoutingInfo) DataSerializer.readObject(in);
    }
    if ((this.flags & VERSION_TAG) != 0) {
      boolean persistentTag = (this.flags & PERSISTENT_TAG) != 0;
      this.versionTag = VersionTag.create(persistentTag, in);
    }
    if (isUsedFakeEventId()) {
      this.eventID = new EventID();
      InternalDataSerializer.invokeFromData(this.eventID, in);
    } else {
      this.eventID = new EventID(baseEventID, idx);
    }
    if ((this.flags & HAS_TAILKEY) != 0) {
      this.tailKey = DataSerializer.readLong(in);
    }
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder(50);
    sb.append("(").append(getKey()).append(",").append(this.value).append(",")
        .append(getOldValue());
    if (this.bucketId > 0) {
      sb.append(", b").append(this.bucketId);
    }
    if (versionTag != null) {
      sb.append(versionTag);
      // sb.append(",v").append(versionTag.getEntryVersion()).append(",rv"+versionTag.getRegionVersion());
    }
    if (filterRouting != null) {
      sb.append(", ").append(filterRouting);
    }
    sb.append(")");
    return sb.toString();
  }

  void setSender(InternalDistributedMember sender) {
    if (this.versionTag != null) {
      this.versionTag.replaceNullIDs(sender);
    }
  }

  /**
   * Used to serialize this instances data to <code>out</code>. If changes are made to this method
   * make sure that it is backwards compatible by creating toDataPreXX methods. Also make sure
   * that the callers to this method are backwards compatible by creating toDataPreXX methods for
   * them even if they are not changed. <br>
   * Callers for this method are: <br>
   * {@link PutAllMessage#toData(DataOutput)} <br>
   * {@link PutAllPRMessage#toData(DataOutput)} <br>
   * {@link RemotePutAllMessage#toData(DataOutput)} <br>
   */
  public void toData(final DataOutput out) throws IOException {
    Object key = this.key;
    final Object v = this.value;
    DataSerializer.writeObject(key, out);

    if (v instanceof byte[] || v == null) {
      out.writeByte(0);
      DataSerializer.writeByteArray((byte[]) v, out);
    } else if (v instanceof CachedDeserializable) {
      CachedDeserializable cd = (CachedDeserializable) v;
      out.writeByte(IS_CACHED_DESER);
      DataSerializer.writeByteArray(cd.getSerializedValue(), out);
    } else {
      out.writeByte(IS_CACHED_DESER);
      DataSerializer.writeObjectAsByteArray(v, out);
    }
    out.writeByte(this.op.ordinal);
    byte bits = this.flags;
    if (this.filterRouting != null)
      bits |= FILTER_ROUTING;
    if (this.versionTag != null) {
      bits |= VERSION_TAG;
      if (this.versionTag instanceof DiskVersionTag) {
        bits |= PERSISTENT_TAG;
      }
    }
    // TODO: Yogesh, this should be conditional,
    // make sure that we sent it on wire only
    // when parallel wan is enabled
    bits |= HAS_TAILKEY;
    out.writeByte(bits);

    if (this.filterRouting != null) {
      DataSerializer.writeObject(this.filterRouting, out);
    }
    if (this.versionTag != null) {
      InternalDataSerializer.invokeToData(this.versionTag, out);
    }
    if (isUsedFakeEventId()) {
      // fake event id should be serialized
      InternalDataSerializer.invokeToData(this.eventID, out);
    }
    // TODO: Yogesh, this should be conditional,
    // make sure that we sent it on wire only
    // when parallel wan is enabled
    DataSerializer.writeLong(this.tailKey, out);
  }

  /**
   * Returns the key
   */
  public Object getKey() {
    return this.key;
  }

  /**
   * Returns the value
   */
  public Object getValue(InternalCache cache) {
    Object result = this.value;
    if (result instanceof FutureCachedDeserializable) {
      FutureCachedDeserializable future = (FutureCachedDeserializable) result;
      result = future.create(cache);
      this.value = result;
    }
    return result;
  }

  /**
   * Returns the old value
   */
  public Object getOldValue() {
    return this.oldValue;
  }

  public Long getTailKey() {
    return this.tailKey;
  }

  public void setTailKey(Long key) {
    this.tailKey = key;
  }

  /**
   * Returns the operation
   */
  public Operation getOp() {
    return this.op;
  }

  public EventID getEventID() {
    return this.eventID;
  }

  /**
   * change event id for the entry
   *
   * @param eventId new event id
   */
  public void setEventId(EventID eventId) {
    this.eventID = eventId;
  }

  /**
   * change bucket id for the entry
   *
   * @param bucketId new bucket id
   */
  public void setBucketId(Integer bucketId) {
    this.bucketId = bucketId;
  }

  /**
   * get bucket id for the entry
   *
   * @return bucket id
   */
  public Integer getBucketId() {
    return this.bucketId;
  }

  /**
   * change event id into fake event id The algorithm is to change the threadid into
   * bucketid*MAX_THREAD_PER_CLIENT+oldthreadid. So from the log, we can derive the original
   * thread id.
   *
   * @return wether current event id is fake or not new bucket id
   */
  public boolean setFakeEventID() {
    if (bucketId.intValue() < 0) {
      return false;
    }

    if (!isUsedFakeEventId()) {
      // assign a fake big thread id. bucket id starts from 0. In order to distinguish
      // with other read thread, let bucket id starts from 1 in fake thread id
      long threadId = ThreadIdentifier.createFakeThreadIDForBulkOp(bucketId.intValue(),
          eventID.getThreadID());
      this.eventID = new EventID(eventID.getMembershipID(), threadId, eventID.getSequenceID());
      this.setUsedFakeEventId(true);
    }
    return true;
  }

  public boolean isUsedFakeEventId() {
    return (flags & USED_FAKE_EVENT_ID) != 0;
  }

  public void setUsedFakeEventId(boolean usedFakeEventId) {
    if (usedFakeEventId) {
      flags |= USED_FAKE_EVENT_ID;
    } else {
      flags &= ~(USED_FAKE_EVENT_ID);
    }
  }

  public boolean isNotifyOnly() {
    return (flags & NOTIFY_ONLY) != 0;
  }

  public void setNotifyOnly(boolean notifyOnly) {
    if (notifyOnly) {
      flags |= NOTIFY_ONLY;
    } else {
      flags &= ~(NOTIFY_ONLY);
    }
  }

  boolean isPossibleDuplicate() {
    return (this.flags & POSDUP) != 0;
  }

  public void setPossibleDuplicate(boolean possibleDuplicate) {
    if (possibleDuplicate) {
      flags |= POSDUP;
    } else {
      flags &= ~(POSDUP);
    }
  }

  public boolean isInhibitDistribution() {
    return this.inhibitDistribution;
  }

  public void setInhibitDistribution(boolean inhibitDistribution) {
    this.inhibitDistribution = inhibitDistribution;
  }

  public boolean isCallbacksInvoked() {
    return this.callbacksInvoked;
  }

  public void setCallbacksInvoked(boolean callbacksInvoked) {
    this.callbacksInvoked = callbacksInvoked;
  }
}

public class JarArchiveInputStream extends ZipArchiveInputStream {

    /**
     * Creates an instance from the input stream using the default encoding.
     *
     * @param inputStream the input stream to wrap
     */
    public JarArchiveInputStream( final InputStream inputStream ) {
        super(inputStream);
    }

    /**
     * Creates an instance from the input stream using the specified encoding.
     *
     * @param inputStream the input stream to wrap
     * @param encoding the encoding to use
     * @since 1.10
     */
    public JarArchiveInputStream( final InputStream inputStream, final String encoding ) {
        super(inputStream, encoding);
    }

    public JarArchiveEntry getNextJarEntry() throws IOException {
        final ZipArchiveEntry entry = getNextZipEntry();
        return entry == null ? null : new JarArchiveEntry(entry);
    }

    @Override
    public ArchiveEntry getNextEntry() throws IOException {
        return getNextJarEntry();
    }

    /**
     * Checks if the signature matches what is expected for a jar file
     * (in this case it is the same as for a zip file).
     *
     * @param signature
     *            the bytes to check
     * @param length
     *            the number of bytes to check
     * @return true, if this stream is a jar archive stream, false otherwise
     */
    public static boolean matches(final byte[] signature, final int length ) {
        return ZipArchiveInputStream.matches(signature, length);
    }
}

public class Job20LineHistoryEventEmitter extends HistoryEventEmitter {

  static List<SingleEventEmitter> nonFinals =
      new LinkedList<SingleEventEmitter>();
  static List<SingleEventEmitter> finals = new LinkedList<SingleEventEmitter>();

  Long originalSubmitTime = null;

  static {
    nonFinals.add(new JobSubmittedEventEmitter());
    nonFinals.add(new JobPriorityChangeEventEmitter());
    nonFinals.add(new JobStatusChangedEventEmitter());
    nonFinals.add(new JobInitedEventEmitter());
    nonFinals.add(new JobInfoChangeEventEmitter());

    finals.add(new JobUnsuccessfulCompletionEventEmitter());
    finals.add(new JobFinishedEventEmitter());
  }

  Job20LineHistoryEventEmitter() {
    super();
  }

  static private class JobSubmittedEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      JobID jobID = JobID.forName(jobIDName);

      if (jobIDName == null) {
        return null;
      }

      String submitTime = line.get("SUBMIT_TIME");
      String jobConf = line.get("JOBCONF");
      String user = line.get("USER");
      if (user == null) {
        user = "nulluser";
      }
      String jobName = line.get("JOBNAME");
      String jobQueueName = line.get("JOB_QUEUE");// could be null
      String workflowId = line.get("WORKFLOW_ID");
      if (workflowId == null) {
        workflowId = "";
      }
      String workflowName = line.get("WORKFLOW_NAME");
      if (workflowName == null) {
        workflowName = "";
      }
      String workflowNodeName = line.get("WORKFLOW_NODE_NAME");
      if (workflowNodeName == null) {
        workflowNodeName = "";
      }
      String workflowAdjacencies = line.get("WORKFLOW_ADJACENCIES");
      if (workflowAdjacencies == null) {
        workflowAdjacencies = "";
      }
      String workflowTags = line.get("WORKFLOW_TAGS");
      if (workflowTags == null) {
        workflowTags = "";
      }


      if (submitTime != null) {
        Job20LineHistoryEventEmitter that =
            (Job20LineHistoryEventEmitter) thatg;

        that.originalSubmitTime = Long.parseLong(submitTime);

        Map<JobACL, AccessControlList> jobACLs =
          new HashMap<JobACL, AccessControlList>();
        return new JobSubmittedEvent(jobID, jobName, user,
            that.originalSubmitTime, jobConf, jobACLs, jobQueueName,
            workflowId, workflowName, workflowNodeName, workflowAdjacencies,
            workflowTags);
      }

      return null;
    }
  }

  static private class JobPriorityChangeEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      JobID jobID = JobID.forName(jobIDName);

      if (jobIDName == null) {
        return null;
      }

      String priority = line.get("JOB_PRIORITY");

      if (priority != null) {
        return new JobPriorityChangeEvent(jobID, JobPriority.valueOf(priority));
      }

      return null;
    }
  }

  static private class JobInitedEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      if (jobIDName == null) {
        return null;
      }

      JobID jobID = JobID.forName(jobIDName);

      String launchTime = line.get("LAUNCH_TIME");
      String status = line.get("JOB_STATUS");
      String totalMaps = line.get("TOTAL_MAPS");
      String totalReduces = line.get("TOTAL_REDUCES");
      String uberized = line.get("UBERIZED");

      if (launchTime != null && totalMaps != null && totalReduces != null) {
        return new JobInitedEvent(jobID, Long.parseLong(launchTime), Integer
            .parseInt(totalMaps), Integer.parseInt(totalReduces), status,
            Boolean.parseBoolean(uberized));
      }

      return null;
    }
  }

  static private class JobStatusChangedEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      if (jobIDName == null) {
        return null;
      }

      JobID jobID = JobID.forName(jobIDName);

      String status = line.get("JOB_STATUS");

      if (status != null) {
        return new JobStatusChangedEvent(jobID, status);
      }

      return null;
    }
  }

  static private class JobInfoChangeEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      if (jobIDName == null) {
        return null;
      }

      JobID jobID = JobID.forName(jobIDName);

      String launchTime = line.get("LAUNCH_TIME");

      if (launchTime != null) {
        Job20LineHistoryEventEmitter that =
            (Job20LineHistoryEventEmitter) thatg;
        return new JobInfoChangeEvent(jobID, that.originalSubmitTime, Long
            .parseLong(launchTime));
      }

      return null;
    }
  }

  static private class JobUnsuccessfulCompletionEventEmitter extends
      SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      if (jobIDName == null) {
        return null;
      }

      JobID jobID = JobID.forName(jobIDName);

      String finishTime = line.get("FINISH_TIME");

      String status = line.get("JOB_STATUS");

      String finishedMaps = line.get("FINISHED_MAPS");
      String finishedReduces = line.get("FINISHED_REDUCES");

      if (status != null && !status.equalsIgnoreCase("success")
          && finishTime != null && finishedMaps != null
          && finishedReduces != null) {
        return new JobUnsuccessfulCompletionEvent(jobID, Long
            .parseLong(finishTime), Integer.parseInt(finishedMaps), Integer
            .parseInt(finishedReduces), -1, -1, -1, -1, status);
      }

      return null;
    }
  }

  static private class JobFinishedEventEmitter extends SingleEventEmitter {
    HistoryEvent maybeEmitEvent(ParsedLine line, String jobIDName,
        HistoryEventEmitter thatg) {
      if (jobIDName == null) {
        return null;
      }

      JobID jobID = JobID.forName(jobIDName);

      String finishTime = line.get("FINISH_TIME");

      String status = line.get("JOB_STATUS");

      String finishedMaps = line.get("FINISHED_MAPS");
      String finishedReduces = line.get("FINISHED_REDUCES");

      String failedMaps = line.get("FAILED_MAPS");
      String failedReduces = line.get("FAILED_REDUCES");

      String counters = line.get("COUNTERS");

      if (status != null && status.equalsIgnoreCase("success")
          && finishTime != null && finishedMaps != null
          && finishedReduces != null) {
        return new JobFinishedEvent(jobID, Long.parseLong(finishTime), Integer
            .parseInt(finishedMaps), Integer.parseInt(finishedReduces), Integer
            .parseInt(failedMaps), Integer.parseInt(failedReduces), -1, -1,
            null, null, maybeParseCounters(counters));
      }

      return null;
    }
  }

  @Override
  List<SingleEventEmitter> finalSEEs() {
    return finals;
  }

  @Override
  List<SingleEventEmitter> nonFinalSEEs() {
    return nonFinals;
  }

}

private void writeRawBytes(Writable writable) throws IOException {
  if (writable instanceof BytesWritable) {
    BytesWritable bw = (BytesWritable) writable;
    byte[] bytes = bw.getBytes();
    int length = bw.getLength();
    clientOut.writeInt(length);
    clientOut.write(bytes, 0, length);
  } else {
    bufferOut.reset();
    writable.write(bufferDataOut);
    byte[] bytes = bufferOut.toByteArray();
    clientOut.writeInt(bytes.length);
    clientOut.write(bytes);
  }
}

private static class BucketList<V> implements Iterable<Bucket<V>> {
    private final ArrayList<Bucket<V>> bucketList;
    private final List<Bucket<V>> immutableVisibleList;

    private BucketList(ArrayList<Bucket<V>> bucketList, ArrayList<Bucket<V>> publicBucketList) {
        this.bucketList = bucketList;

        int displayIndex = 0;
        for (Bucket<V> bucket : publicBucketList) {
            bucket.displayIndex = displayIndex++;
        }
        immutableVisibleList = Collections.unmodifiableList(publicBucketList);
    }

    private int getBucketCount() {
        return immutableVisibleList.size();
    }

    private int getBucketIndex(CharSequence name, Collator collatorPrimaryOnly) {
        // binary search
        int start = 0;
        int limit = bucketList.size();
        while ((start + 1) < limit) {
            int i = (start + limit) / 2;
            Bucket<V> bucket = bucketList.get(i);
            int nameVsBucket = collatorPrimaryOnly.compare(name, bucket.lowerBoundary);
            if (nameVsBucket < 0) {
                limit = i;
            } else {
                start = i;
            }
        }
        Bucket<V> bucket = bucketList.get(start);
        if (bucket.displayBucket != null) {
            bucket = bucket.displayBucket;
        }
        return bucket.displayIndex;
    }

    /**
     * Private iterator over all the buckets, visible and invisible
     */
    private Iterator<Bucket<V>> fullIterator() {
        return bucketList.iterator();
    }

    /**
     * Iterator over just the visible buckets.
     */
    @Override
    public Iterator<Bucket<V>> iterator() {
        return immutableVisibleList.iterator(); // use immutable list to prevent remove().
    }
}

InitializeParams get(String id) throws LanguageServerException {
  InitializeParams initializeParams = new InitializeParams();
  LOG.debug("Initialize params constructing: started");

  Boolean locality = localityRegistry.get(id);
  LOG.debug("Locality: {}", locality);

  Integer processId = locality ? ProcessIdProvider.get() : null;
  initializeParams.setProcessId(processId);
  LOG.debug("Process id: {}", processId);

  String projectsRoot = projectsRootRegistry.getOrNull(id);

  String rootPath;
  if (projectsRoot != null) {
    rootPath = projectsRoot;
  } else {
    rootPath = Paths.get(rootUri).toAbsolutePath().toString();
  }
  initializeParams.setRootPath(rootPath);
  LOG.debug("Root path: {}", rootPath);

  String rootUri;
  if (projectsRoot != null) {
    rootUri = Paths.get(projectsRoot).toUri().toString();
  } else {
    rootUri = this.rootUri.toString();
  }
  initializeParams.setRootUri(rootUri);
  LOG.debug("Root URI: {}", rootUri);

  ClientCapabilities capabilities = ClientCapabilitiesProvider.get();
  initializeParams.setCapabilities(capabilities);
  LOG.debug("Client capabilities: {}", capabilities);

  String clientName = ClientCapabilitiesProvider.CLIENT_NAME;
  initializeParams.setClientName(clientName);
  LOG.debug("Client name: {}", clientName);

  LOG.debug("Initialize params constructing: finished");
  return initializeParams;
}

