@Override
public int run(String[] args) throws IOException {
  if (args.length == 0) {
    printUsage(false);
    return 1;
  }
  final Command command = determineCommand(args[0]);
  if (command == null) {
    System.err.println("Can't understand command '" + args[0] + "'");
    if (!args[0].startsWith("-")) {
      System.err.println("Command names must start with dashes.");
    }
    printUsage(false);
    return 1;
  }
  final List<String> argsList = new LinkedList<String>();
  for (int j = 1; j < args.length; j++) {
    argsList.add(args[j]);
  }
  try {
    return command.run(getConf(), argsList);
  } catch (IllegalArgumentException e) {
    System.err.println(prettifyException(e));
    return -1;
  }
}

public class CloudCliServiceLaunchConfigurationDelegate extends BootCliLaunchConfigurationDelegate {

	private static final VersionRange SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE = new VersionRange("1.3.0");

	public final static String TYPE_ID = "org.springframework.ide.eclipse.boot.launch.cloud.cli.service";

	public final static String ATTR_CLOUD_SERVICE_ID = "local-cloud-service-id";

	private final static String PREF_DONT_SHOW_PLATFORM_WARNING = "org.springframework.ide.eclipse.boot.launch.cloud.cli.NotSupportedPlatform";
	private final static String PREF_DONT_SHOW_JRE_WARNING = "org.springframework.ide.eclipse.boot.launch.cloud.cli.JRE";
	private final static String PREF_DONT_SHOW_JDK_WARNING = "org.springframework.ide.eclipse.boot.launch.cloud.cli.JDK";

	private List<String> getCloudCliServiceLifeCycleVmArguments(ILaunchConfiguration configuration, int jmxPort) {
		List<String> vmArgs = new ArrayList<>();
			EnumSet<JmxBeanSupport.Feature> enabled = BootLaunchConfigurationDelegate
					.getEnabledJmxFeatures(configuration);
			if (!enabled.isEmpty()) {
				String enableLiveBeanArgs = JmxBeanSupport.jmxBeanVmArgs(jmxPort, enabled);
				vmArgs.addAll(Arrays.asList(enableLiveBeanArgs.split("\n")));
			}
		return vmArgs;
	}

	protected String[] getProgramArgs(IBootInstall bootInstall, ILaunch launch, ILaunchConfiguration configuration) {
		try {
			CloudCliInstall cloudCliInstall = bootInstall.getExtension(CloudCliInstall.class);
			if (cloudCliInstall == null) {
				Log.error("No Spring Cloud CLI installation found");
			} else {
				String serviceId = configuration.getAttribute(ATTR_CLOUD_SERVICE_ID, (String) null);
				Version cloudCliVersion = cloudCliInstall.getVersion();
				List<String> vmArgs = new ArrayList<>();
				List<String> args = new ArrayList<>();

				args.add(CloudCliInstall.COMMAND_PREFIX);
				args.add(serviceId);

				if (cloudCliVersion != null && SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE.includes(cloudCliVersion)) {
					args.add("--deployer=thin");
				}

				args.add("--");
				args.add("--logging.level.org.springframework.cloud.launcher.deployer=DEBUG");

				// VM argument for the service log output
				if (BootLaunchConfigurationDelegate.supportsAnsiConsoleOutput()) {
					vmArgs.add("-Dspring.output.ansi.enabled=always");
				}

				if (CloudCliServiceLaunchConfigurationDelegate.SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE.includes(cloudCliVersion)) {
					if (!vmArgs.isEmpty()) {
						args.add("--spring.cloud.launcher.deployables." + serviceId + ".properties.spring.cloud.deployer.local.javaOpts=" + String.join(",", vmArgs));
					}
				} else if (CloudCliInstall.CLOUD_CLI_JAVA_OPTS_SUPPORTING_VERSIONS.includes(cloudCliVersion)) {
					int jmxPort = getJmxPort(configuration);
					// Set the JMX port for launch
					launch.setAttribute(BootLaunchConfigurationDelegate.JMX_PORT, String.valueOf(jmxPort));
					vmArgs.addAll(getCloudCliServiceLifeCycleVmArguments(configuration, jmxPort));
					// Set the JMX port connection jvm args for the service
					if (!vmArgs.isEmpty()) {
						args.add("--spring.cloud.launcher.deployables." + serviceId + ".properties.JAVA_OPTS=" + String.join(",", vmArgs));
					}
				}
				return args.toArray(new String[args.size()]);
			}
		} catch (Exception e) {
			Log.log(e);
		}
		return new String[0];
	}

	private int getJmxPort(ILaunchConfiguration configuration) {
		int port = 0;
		try {
			port = Integer.parseInt(BootLaunchConfigurationDelegate.getJMXPort(configuration));
		} catch (Exception e) {
			// ignore: bad data in launch config.
		}
		if (port == 0) {
			try {
				// slightly better than calling JmxBeanSupport.randomPort()
				port = PortFinder.findFreePort();
			} catch (IOException e) {
				Log.log(e);
			}
		}
		return port;
	}

	public static boolean isLocalCloudServiceLaunch(ILaunchConfiguration conf) {
		try {
			if (conf!=null) {
					String type = conf.getType().getIdentifier();
				return TYPE_ID.equals(type);
			}
		} catch (Exception e) {
			Log.log(e);
		}
		return false;
	}

	public static ILaunchConfigurationWorkingCopy createLaunchConfig(String serviceId) throws CoreException {
		ILaunchManager launchManager = DebugPlugin.getDefault().getLaunchManager();
		ILaunchConfigurationType type = launchManager.getLaunchConfigurationType(TYPE_ID);
		ILaunchConfigurationWorkingCopy config = type.newInstance(null, serviceId);

		// Set default config with life cycle tracking support because it should cover with life cycle tracking and without
		BootLaunchConfigurationDelegate.setDefaults(config, null, null);

		config.setAttribute(ATTR_CLOUD_SERVICE_ID, serviceId);

		// Overwrite process factory class because for latest version of Cloud CLI life cycle tracking through JMX port is not available for services
		BootLaunchConfigurationDelegate.setProcessFactory(config, CloudCliProcessFactory.class);
		return config;
	}

	public static boolean canUseLifeCycle(ILaunch launch) {
		ILaunchConfiguration conf = launch.getLaunchConfiguration();
		return conf!=null && canUseLifeCycle(conf);
	}

	public static boolean isSingleProcessServiceConfig(ILaunchConfiguration conf) {
		try {
			if (isCloudCliService(conf)) {
				IBootInstall bootInstall = BootInstallManager.getInstance().getDefaultInstall();
				if (bootInstall != null) {
					Version cloudCliVersion = bootInstall.getExtension(CloudCliInstall.class) == null ? null : bootInstall.getExtension(CloudCliInstall.class).getVersion();
					return SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE.includes(cloudCliVersion);
				}
			}
		} catch (Exception e) {
			// ignore
		}
		return false;
	}

	public static boolean isCloudCliService(ILaunchConfiguration conf) {
		try {
			return TYPE_ID.equals(conf.getType().getIdentifier());
		} catch (CoreException e) {
			// Ignore
		}
		return false;
	}

	public static boolean canUseLifeCycle(ILaunchConfiguration conf) {
		try {
			if (!isCloudCliService(conf)) {
				return false;
			}
			IBootInstall bootInstall = BootInstallManager.getInstance().getDefaultInstall();
			if (bootInstall == null) {
				return false;
			}
			Version cloudCliVersion = bootInstall.getExtension(CloudCliInstall.class) == null ? null : bootInstall.getExtension(CloudCliInstall.class).getVersion();
			// Cloud CLI version below 1.2.0 and over 1.3.0 can't have JMX connection to cloud service hence life cycle should be disabled.
			if (!canUseLifeCycle(cloudCliVersion)) {
				return false;
			}
			return SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE.includes(cloudCliVersion) || BootLaunchConfigurationDelegate.getEnableLifeCycle(conf);
		} catch (Exception e) {
			// Ignore
		}
		return false;
	}

	private static boolean canUseLifeCycle(Version cloudCliVersion) {
		// Cloud CLI version below 1.2.0 and over 1.3.0 can't have JMX connection to cloud service hence life cycle should be disabled.
		if (cloudCliVersion == null
				|| !CloudCliInstall.CLOUD_CLI_JAVA_OPTS_SUPPORTING_VERSIONS.includes(cloudCliVersion)
				|| SPRING_CLOUD_CLI_SINGLE_PROCESS_VERSION_RANGE.includes(cloudCliVersion)) {
			return false;
		}
		return true;
	}

	public static class CloudCliProcessFactory extends BootProcessFactory {

		@Override
		public IProcess newProcess(ILaunch launch, Process process, String label, Map<String, String> attributes) {
			try {
				IBootInstall bootInstall = BootInstallManager.getInstance().getDefaultInstall();
				if (bootInstall != null) {
					Version cloudCliVersion = bootInstall.getExtension(CloudCliInstall.class) == null ? null : bootInstall.getExtension(CloudCliInstall.class).getVersion();
					if (CloudCliServiceLaunchConfigurationDelegate.isSingleProcessServiceConfig(launch.getLaunchConfiguration())) {
						final IPreferenceStore store = BootActivator.getDefault().getPreferenceStore();
						// Set invalid PID initially thus if PID is failed to be calculated then set PID launch attribute to invalid PID to fallback to default non-JMX process tracking
						long pid = -1;
						try {
							if (ProcessUtils.isLatestJdkForTools()) {
								pid = ProcessUtils.getProcessID(process);
							} else {
								Log.warn("Old JDK version. Need latest JDK to make JMX connection to process using its PID");
								if (!store.getBoolean(PREF_DONT_SHOW_JDK_WARNING)) {
									PlatformUI.getWorkbench().getDisplay().asyncExec(() -> {
										MessageDialogWithToggle dialog = MessageDialogWithToggle.openWarning(
											Display.getCurrent().getActiveShell(), "Cloud CLI Service Info Limitation",
											"Cloud service process life-cycle data is limited and port data is unavailable because STS runnning on an old JDK version. Point STS to the latest JDK and restart it to have complete service process life-cycle and port data",
											"Don't show this message again",
											false, null, null);
										store.setValue(PREF_DONT_SHOW_JDK_WARNING, dialog.getToggleState());
									});
								}
							}
						} catch (NoClassDefFoundError e) {
							Log.warn(e);
							if (!store.getBoolean(PREF_DONT_SHOW_JRE_WARNING)) {
								PlatformUI.getWorkbench().getDisplay().asyncExec(() -> {
									MessageDialogWithToggle dialog = MessageDialogWithToggle.openWarning(
										Display.getCurrent().getActiveShell(), "Cloud CLI Service Info Limitation",
										"Cloud service process life-cycle data is limited and port data is unavailable because STS is running on a JRE. Point it to a JDK and restart STS for complete service process life-cycle and port data",
										"Don't show this message again",
										false, null, null);
									store.setValue(PREF_DONT_SHOW_JRE_WARNING, dialog.getToggleState());
								});
							}
						} catch (UnsupportedOperationException e) {
							Log.warn(e);
							if (!store.getBoolean(PREF_DONT_SHOW_PLATFORM_WARNING)) {
								PlatformUI.getWorkbench().getDisplay().asyncExec(() -> {
									MessageDialogWithToggle dialog = MessageDialogWithToggle.openWarning(
										Display.getCurrent().getActiveShell(), "Cloud CLI Service Info Limitation",
										"Cloud service process life-cycle data is limited and port data is unavailable on the current platform.",
										"Don't show this message again",
										false, null, null);
									store.setValue(PREF_DONT_SHOW_PLATFORM_WARNING, dialog.getToggleState());
								});
							}
						}
						launch.setAttribute(BootLaunchConfigurationDelegate.PROCESS_ID, String.valueOf(pid));
						return new RuntimeProcess(launch, process, label, attributes);
					} else if (canUseLifeCycle(cloudCliVersion)) {
						return super.newProcess(launch, process, label, attributes);
					}
				}
			} catch (Exception e) {
				Log.log(e);
			}
			return new RuntimeProcess(launch, process, label, attributes);
		}

	}

}

    public static RuleSet parse(final Reader configReader, EventLoggerProvider eventLogger)
    {
        RuleSetCreator ruleSetCreator = new RuleSetCreator();

        int line = 0;
        try(Reader fileReader = configReader)
        {
            LOGGER.debug("About to load ACL file");
            StreamTokenizer tokenizer = new StreamTokenizer(new BufferedReader(fileReader));
            tokenizer.resetSyntax(); // setup the tokenizer

            tokenizer.commentChar(COMMENT); // single line comments
            tokenizer.eolIsSignificant(true); // return EOL as a token
            tokenizer.ordinaryChar('='); // equals is a token
            tokenizer.ordinaryChar(CONTINUATION); // continuation character (when followed by EOL)
            tokenizer.quoteChar('"'); // double quote
            tokenizer.quoteChar('\''); // single quote
            tokenizer.whitespaceChars('\u0000', '\u0020'); // whitespace (to be ignored) TODO properly
            tokenizer.wordChars('a', 'z'); // unquoted token characters [a-z]
            tokenizer.wordChars('A', 'Z'); // [A-Z]
            tokenizer.wordChars('0', '9'); // [0-9]
            tokenizer.wordChars('_', '_'); // underscore
            tokenizer.wordChars('-', '-'); // dash
            tokenizer.wordChars('.', '.'); // dot
            tokenizer.wordChars('*', '*'); // star
            tokenizer.wordChars('@', '@'); // at
            tokenizer.wordChars(':', ':'); // colon

            // parse the acl file lines
            Stack<String> stack = new Stack<>();
            int current;
            do {
                current = tokenizer.nextToken();
                line = tokenizer.lineno()-1;
                switch (current)
                {
                    case StreamTokenizer.TT_EOF:
                    case StreamTokenizer.TT_EOL:
                        if (stack.isEmpty())
                        {
                            break; // blank line
                        }

                        // pull out the first token from the bottom of the stack and check arguments exist
                        String first = stack.firstElement();
                        stack.removeElementAt(0);
                        if (stack.isEmpty())
                        {
                            throw new IllegalConfigurationException(String.format(NOT_ENOUGH_TOKENS_MSG, line));
                        }

                        // check for and parse optional initial number for ACL lines
                        Integer number = null;
                        if (first != null && first.matches("\\d+"))
                        {
                            // set the acl number and get the next element
                            number = Integer.valueOf(first);
                            first = stack.firstElement();
                            stack.removeElementAt(0);
                        }

                        if (ACL.equalsIgnoreCase(first))
                        {
                            parseAcl(number, stack, ruleSetCreator, line);
                        }
                        else if (number == null)
                        {
                            if("GROUP".equalsIgnoreCase(first))
                            {
                                throw new IllegalConfigurationException(String.format("GROUP keyword not supported at "
                                                                                      + "line %d. Groups should defined "
                                                                                      + "via a Group Provider, not in "
                                                                                      + "the ACL file.",
                                                                                      line));
                            }
                            else if (CONFIG.equalsIgnoreCase(first))
                            {
                                parseConfig(stack, ruleSetCreator, line);
                            }
                            else
                            {
                                throw new IllegalConfigurationException(String.format(UNRECOGNISED_INITIAL_MSG, first, line));
                            }
                        }
                        else
                        {
                            throw new IllegalConfigurationException(String.format(NUMBER_NOT_ALLOWED_MSG, first, line));
                        }

                        // reset stack, start next line
                        stack.clear();
                        break;
                    case StreamTokenizer.TT_NUMBER:
                        stack.push(Integer.toString(Double.valueOf(tokenizer.nval).intValue()));
                        break;
                    case StreamTokenizer.TT_WORD:
                        stack.push(tokenizer.sval); // token
                        break;
                    default:
                        if (tokenizer.ttype == CONTINUATION)
                        {
                            int next = tokenizer.nextToken();
                            line = tokenizer.lineno()-1;
                            if (next == StreamTokenizer.TT_EOL)
                            {
	                            break; // continue reading next line
                            }

                            // invalid location for continuation character (add one to line because we ate the EOL)
                            throw new IllegalConfigurationException(String.format(PREMATURE_CONTINUATION_MSG, line + 1));
                        }
                        else if (tokenizer.ttype == '\'' || tokenizer.ttype == '"')
                        {
                            stack.push(tokenizer.sval); // quoted token
                        }
                        else
                        {
                            stack.push(Character.toString((char) tokenizer.ttype)); // single character
                        }
                }
            } while (current != StreamTokenizer.TT_EOF);

            if (!stack.isEmpty())
            {
                throw new IllegalConfigurationException(String.format(PREMATURE_EOF_MSG, line));
            }
        }
        catch (IllegalArgumentException iae)
        {
            throw new IllegalConfigurationException(String.format(PARSE_TOKEN_FAILED_MSG, line), iae);
        }
        catch (IOException ioe)
        {
            throw new IllegalConfigurationException(CANNOT_LOAD_MSG, ioe);
        }
        return ruleSetCreator.createRuleSet(eventLogger);
    }

public int rewindUpTo(VirtualFrame frame, int length) {
    if (props.isForward()) {
        final int offset = Math.min(getIndex(frame), length);
        setIndex(frame, getIndex(frame) - offset);
        return offset;
    } else {
        assert length == 0;
        return 0;
    }
}

@SuppressWarnings("unchecked")
public <T extends Enum<T>> T get(final String property, final T defaultValue) {
    final String value = properties.getProperty(property);

    if (value == null || value.equals(""))
        return parent.get(property, defaultValue);

    if (defaultValue == null)
        throw new IllegalArgumentException("Must supply a default for property " + property);

    final Class<T> enumType = (Class<T>) defaultValue.getClass();

    try {
        return log(property, valueOf(enumType, value.toUpperCase()));
    } catch (IllegalArgumentException e) {
        warn(property, value);
        return parent.get(property, defaultValue);
    }
}

class XPathFactoryFinder  {
    private static final String DEFAULT_PACKAGE = "com.sun.org.apache.xpath.internal";

    /** debug support code. */
    private static boolean debug = false;
    static {
        // Use try/catch block to support applets
        try {
            debug = SecuritySupport.getSystemProperty("jaxp.debug") != null;
        } catch (Exception unused) {
            debug = false;
        }
    }

    /**
     * <p>Cache properties for performance.</p>
     */
    private static final Properties cacheProps = new Properties();

    /**
     * <p>First time requires initialization overhead.</p>
     */
    private volatile static boolean firstTime = true;

    /**
     * <p>Conditional debug printing.</p>
     *
     * @param msgGen Supplier function that returns debug message
     */
    private static void debugPrintln(Supplier<String> msgGen) {
        if (debug) {
            System.err.println("JAXP: " + msgGen.get());
        }
    }

    /**
     * <p><code>ClassLoader</code> to use to find <code>XPathFactory</code>.</p>
     */
    private final ClassLoader classLoader;

    /**
     * <p>Constructor that specifies <code>ClassLoader</code> to use
     * to find <code>XPathFactory</code>.</p>
     *
     * @param loader
     *      to be used to load resource and {@link XPathFactory}
     *      implementations during the resolution process.
     *      If this parameter is null, the default system class loader
     *      will be used.
     */
    public XPathFactoryFinder(ClassLoader loader) {
        this.classLoader = loader;
        if( debug ) {
            debugDisplayClassLoader();
        }
    }

    private void debugDisplayClassLoader() {
        try {
            if( classLoader == SecuritySupport.getContextClassLoader() ) {
                debugPrintln(() -> "using thread context class loader ("+classLoader+") for search");
                return;
            }
        } catch( Throwable unused ) {
             // getContextClassLoader() undefined in JDK1.1
        }

        if( classLoader==ClassLoader.getSystemClassLoader() ) {
            debugPrintln(() -> "using system class loader ("+classLoader+") for search");
            return;
        }

        debugPrintln(() -> "using class loader ("+classLoader+") for search");
    }

    /**
     * <p>Creates a new {@link XPathFactory} object for the specified
     * object model.</p>
     *
     * @param uri
     *       Identifies the underlying object model.
     *
     * @return <code>null</code> if the callee fails to create one.
     *
     * @throws NullPointerException
     *      If the parameter is null.
     */
    public XPathFactory newFactory(String uri) throws XPathFactoryConfigurationException {
        if (uri == null) {
            throw new NullPointerException();
        }
        XPathFactory f = _newFactory(uri);
        if (f != null) {
            debugPrintln(()->"factory '" + f.getClass().getName() + "' was found for " + uri);
        } else {
            debugPrintln(()->"unable to find a factory for " + uri);
        }
        return f;
    }

    /**
     * <p>Lookup a {@link XPathFactory} for the given object model.</p>
     *
     * @param uri identifies the object model.
     *
     * @return {@link XPathFactory} for the given object model.
     */
    private XPathFactory _newFactory(String uri) throws XPathFactoryConfigurationException {
        XPathFactory xpathFactory = null;

        String propertyName = SERVICE_CLASS.getName() + ":" + uri;

        // system property look up
        try {
            debugPrintln(()->"Looking up system property '"+propertyName+"'" );
            String r = SecuritySupport.getSystemProperty(propertyName);
            if(r!=null) {
                debugPrintln(()->"The value is '"+r+"'");
                xpathFactory = createInstance(r);
                if (xpathFactory != null) {
                    return xpathFactory;
                }
            } else
                debugPrintln(()->"The property is undefined.");
        } catch( Throwable t ) {
            if( debug ) {
                debugPrintln(()->"failed to look up system property '"+propertyName+"'" );
                t.printStackTrace();
            }
        }

        String javah = SecuritySupport.getSystemProperty( "java.home" );
        String configFile = javah + File.separator +
        "conf" + File.separator + "jaxp.properties";

        // try to read from $java.home/conf/jaxp.properties
        try {
            if(firstTime){
                synchronized(cacheProps){
                    if(firstTime){
                        File f=new File( configFile );
                        firstTime = false;
                        if(SecuritySupport.doesFileExist(f)){
                            debugPrintln(()->"Read properties file " + f);
                            cacheProps.load(SecuritySupport.getFileInputStream(f));
                        }
                    }
                }
            }
            final String factoryClassName = cacheProps.getProperty(propertyName);
            debugPrintln(()->"found " + factoryClassName + " in $java.home/conf/jaxp.properties");

            if (factoryClassName != null) {
                xpathFactory = createInstance(factoryClassName);
                if(xpathFactory != null){
                    return xpathFactory;
                }
            }
        } catch (Exception ex) {
            if (debug) {
                ex.printStackTrace();
            }
        }

        // Try with ServiceLoader
        assert xpathFactory == null;
        xpathFactory = findServiceProvider(uri);

        // The following assertion should always be true.
        // Uncomment it, recompile, and run with -ea in case of doubts:
        // assert xpathFactory == null || xpathFactory.isObjectModelSupported(uri);

        if (xpathFactory != null) {
            return xpathFactory;
        }

        // platform default
        if(uri.equals(XPathFactory.DEFAULT_OBJECT_MODEL_URI)) {
            debugPrintln(()->"attempting to use the platform default W3C DOM XPath lib");
            return new XPathFactoryImpl();
        }

        debugPrintln(()->"all things were tried, but none was found. bailing out.");
        return null;
    }

    /** <p>Create class using appropriate ClassLoader.</p>
     *
     * @param className Name of class to create.
     * @return Created class or <code>null</code>.
     */
    private Class<?> createClass(String className) {
        Class<?> clazz;
        // make sure we have access to restricted packages
        boolean internal = false;
        if (System.getSecurityManager() != null) {
            if (className != null && className.startsWith(DEFAULT_PACKAGE)) {
                internal = true;
            }
        }

        // use approprite ClassLoader
        try {
            if (classLoader != null && !internal) {
                    clazz = Class.forName(className, false, classLoader);
            } else {
                    clazz = Class.forName(className);
            }
        } catch (Throwable t) {
            if(debug) {
                t.printStackTrace();
            }
            return null;
        }

        return clazz;
    }

    /**
     * <p>Creates an instance of the specified and returns it.</p>
     *
     * @param className
     *      fully qualified class name to be instantiated.
     *
     * @return null
     *      if it fails. Error messages will be printed by this method.
     */
    XPathFactory createInstance(String className)
            throws XPathFactoryConfigurationException
    {
        XPathFactory xPathFactory = null;

        debugPrintln(()->"createInstance(" + className + ")");

        // get Class from className
        Class<?> clazz = createClass(className);
        if (clazz == null) {
            debugPrintln(()->"failed to getClass(" + className + ")");
            return null;
        }
        debugPrintln(()->"loaded " + className + " from " + which(clazz));

        // instantiate Class as a XPathFactory
        try {
            xPathFactory = (XPathFactory) clazz.getConstructor().newInstance();
        } catch (ClassCastException | IllegalAccessException | IllegalArgumentException |
            InstantiationException | InvocationTargetException | NoSuchMethodException |
            SecurityException ex) {
            debugPrintln(()->"could not instantiate " + clazz.getName());
            if (debug) {
                    ex.printStackTrace();
            }
            return null;
        }

        return xPathFactory;
    }

    // Call isObjectModelSupportedBy with initial context.
    private boolean isObjectModelSupportedBy(final XPathFactory factory,
            final String objectModel,
            AccessControlContext acc) {
        return AccessController.doPrivileged(new PrivilegedAction<Boolean>() {
                    public Boolean run() {
                        return factory.isObjectModelSupported(objectModel);
                    }
                }, acc);
    }

    /**
     * Finds a service provider subclass of XPathFactory that supports the
     * given object model using the ServiceLoader.
     *
     * @param objectModel URI of object model to support.
     * @return An XPathFactory supporting the specified object model, or null
     *         if none is found.
     * @throws XPathFactoryConfigurationException if a configuration error is found.
     */
    private XPathFactory findServiceProvider(final String objectModel)
            throws XPathFactoryConfigurationException {

        assert objectModel != null;
        // store current context.
        final AccessControlContext acc = AccessController.getContext();
        try {
            return AccessController.doPrivileged(new PrivilegedAction<XPathFactory>() {
                public XPathFactory run() {
                    final ServiceLoader<XPathFactory> loader =
                            ServiceLoader.load(SERVICE_CLASS);
                    for (XPathFactory factory : loader) {
                        // restore initial context to call
                        // factory.isObjectModelSupportedBy
                        if (isObjectModelSupportedBy(factory, objectModel, acc)) {
                            return factory;
                        }
                    }
                    return null; // no factory found.
                }
            });
        } catch (ServiceConfigurationError error) {
            throw new XPathFactoryConfigurationException(error);
        }
    }

    private static final Class<XPathFactory> SERVICE_CLASS = XPathFactory.class;

    // Used for debugging purposes
    private static String which( Class<?> clazz ) {
        return SecuritySupport.getClassSource(clazz);
    }

}

private void addUTF8Region(StructurePointer clazz, String slotName,
		String additionalInfo, AbstractPointer utf8String)
		throws CorruptDataException {
	long offset = utf8String.getAddress() - clazz.getAddress();
	/* We do not want to print UTF8 outside of the ROM class. */
	long clazzSize = ((J9ROMClassPointer) clazz).romSize().longValue();
	if ((offset > 0) && (offset < clazzSize)) {
		if (utf8String.notNull()) {
			long UTF8Length = getUTF8Length(J9UTF8Pointer.cast(utf8String));
			if (utf8String.getAddress() < firstJ9_ROM_UTF8) {
				firstJ9_ROM_UTF8 = utf8String.getAddress();
			}
			if ((utf8String.getAddress() + UTF8Length) > lastJ9_ROM_UTF8) {
				lastJ9_ROM_UTF8 = utf8String.getAddress() + UTF8Length;
			}
			classRegions.add(new J9ClassRegion(utf8String,
					SlotType.J9_ROM_UTF8, slotName, additionalInfo,
					UTF8Length, offset, true));
		}
	}
}

