public class RandomForestClassifierTrainer
    extends RandomForestTrainer<ObjectHistogram<BootstrappedVector>, GiniHistogram, RandomForestClassifierTrainer> {
    /** Label mapping. */
    private Map<Double, Integer> lblMapping = new HashMap<>();

    /**
     * Constructs an instance of RandomForestClassifierTrainer.
     *
     * @param meta Features meta.
     */
    public RandomForestClassifierTrainer(List<FeatureMeta> meta) {
        super(meta);
    }

    /** {@inheritDoc} */
    @Override protected RandomForestClassifierTrainer instance() {
        return this;
    }

    /**
     * Aggregates all unique labels from dataset and assigns integer id value for each label.
     * This id can be used as index in arrays or lists.
     *
     * @param dataset Dataset.
     * @return true if initialization was done.
     */
    @Override protected boolean init(Dataset<EmptyContext, BootstrappedDatasetPartition> dataset) {
        Set<Double> uniqLabels = dataset.compute(
            x -> {
                Set<Double> labels = new HashSet<>();
                for (int i = 0; i < x.getRowsCount(); i++)
                    labels.add(x.getRow(i).label());
                return labels;
            },
            (l, r) -> {
                if (l == null)
                    return r;
                if (r == null)
                    return l;
                Set<Double> lbls = new HashSet<>();
                lbls.addAll(l);
                lbls.addAll(r);
                return lbls;
            }
        );

        if(uniqLabels == null)
            return false;

        int i = 0;
        for (Double label : uniqLabels)
            lblMapping.put(label, i++);

        return super.init(dataset);
    }

    /** {@inheritDoc} */
    @Override protected ModelsComposition buildComposition(List<TreeRoot> models) {
        return new ModelsComposition(models, new OnMajorityPredictionsAggregator());
    }

    /** {@inheritDoc} */
    @Override protected ImpurityHistogramsComputer<GiniHistogram> createImpurityHistogramsComputer() {
        return new GiniHistogramsComputer(lblMapping);
    }

    /** {@inheritDoc} */
    @Override protected LeafValuesComputer<ObjectHistogram<BootstrappedVector>> createLeafStatisticsAggregator() {
        return new ClassifierLeafValuesComputer(lblMapping);
    }

    /** {@inheritDoc} */
    @Override public RandomForestClassifierTrainer withEnvironmentBuilder(LearningEnvironmentBuilder envBuilder) {
        return (RandomForestClassifierTrainer)super.withEnvironmentBuilder(envBuilder);
    }
}

public class CustomDataImpl implements CustomData {

  public static final CustomData NONE = new CustomDataImpl(new LinkedHashMap<Object, Object>());

  private final Map<Object, Object> customData;

  public CustomDataImpl(final Map<Object, Object> customData) {
    Validate.notNull(customData, "Custom data required");
    this.customData = Collections.unmodifiableMap(customData);
  }

  @Override
  public boolean equals(final Object obj) {
    if (this == obj) {
      return true;
    }
    if (obj == null) {
      return false;
    }
    if (getClass() != obj.getClass()) {
      return false;
    }
    final CustomDataImpl other = (CustomDataImpl) obj;
    if (customData == null) {
      if (other.customData != null) {
        return false;
      }
    } else if (!customData.equals(other.customData)) {
      return false;
    }
    return true;
  }

  public Object get(final Object key) {
    return customData.get(key);
  }

  @Override
  public int hashCode() {
    final int prime = 31;
    final int result = 1;
    return prime * result + (customData == null ? 0 : customData.hashCode());
  }

  public Iterator<Object> iterator() {
    return customData.keySet().iterator();
  }

  public Set<Object> keySet() {
    return customData.keySet();
  }

  @Override
  public String toString() {
    return customData.toString();
  }
}

public abstract class AbstractClientProvider {

  public AbstractClientProvider() {
  }

  /**
   * Generates a fixed format of application tags given one or more of
   * application name, version and description. This allows subsequent query for
   * an application with a name only, version only or description only or any
   * combination of those as filters.
   *
   * @param appName name of the application
   * @param appVersion version of the application
   * @param appDescription brief description of the application
   * @return
   */
  public static final Set<String> createApplicationTags(String appName,
      String appVersion, String appDescription) {
    Set<String> tags = new HashSet<>();
    tags.add(ServiceUtils.createNameTag(appName));
    if (appVersion != null) {
      tags.add(ServiceUtils.createVersionTag(appVersion));
    }
    if (appDescription != null) {
      tags.add(ServiceUtils.createDescriptionTag(appDescription));
    }
    return tags;
  }

  /**
   * Validate the artifact.
   * @param artifact
   */
  public abstract void validateArtifact(Artifact artifact, String compName,
      FileSystem fileSystem) throws IOException;

  protected abstract void validateConfigFile(ConfigFile configFile,
      String compName, FileSystem fileSystem) throws IOException;

  /**
   * Validate the config files.
   * @param configFiles config file list
   * @param fs file system
   */
  public void validateConfigFiles(List<ConfigFile> configFiles, String compName,
      FileSystem fs) throws IOException {
    Set<String> destFileSet = new HashSet<>();

    for (ConfigFile file : configFiles) {
      if (file.getType() == null) {
        throw new IllegalArgumentException("File type is empty");
      }
      ConfigFile.TypeEnum fileType = file.getType();

      if (fileType.equals(ConfigFile.TypeEnum.TEMPLATE)) {
        if (StringUtils.isEmpty(file.getSrcFile()) &&
            !file.getProperties().containsKey(CONTENT)) {
          throw new IllegalArgumentException(MessageFormat.format("For {0} " +
                  "format, either src_file must be specified in ConfigFile," +
                  " or the \"{1}\" key must be specified in " +
                  "the 'properties' field of ConfigFile. ",
              ConfigFile.TypeEnum.TEMPLATE, CONTENT));
        }
      } else if (fileType.equals(ConfigFile.TypeEnum.STATIC) || fileType.equals(
          ConfigFile.TypeEnum.ARCHIVE)) {
        if (!file.getProperties().isEmpty()) {
          throw new IllegalArgumentException(String
              .format("For %s format, should not specify any 'properties.'",
                  fileType));
        }

        String srcFile = file.getSrcFile();
        if (srcFile == null || srcFile.isEmpty()) {
          throw new IllegalArgumentException(String.format(
              "For %s format, should make sure that srcFile is specified",
              fileType));
        }
        FileStatus fileStatus = fs.getFileStatus(new Path(srcFile));
        if (fileStatus != null && fileStatus.isDirectory()) {
          throw new IllegalArgumentException("srcFile=" + srcFile +
              " is a directory, which is not supported.");
        }
      }
      if (!StringUtils.isEmpty(file.getSrcFile())) {
        Path p = new Path(file.getSrcFile());
        if (!fs.exists(p)) {
          throw new IllegalArgumentException(
              "Specified src_file does not exist on " + fs.getScheme() + ": "
                  + file.getSrcFile());
        }
      }

      if (StringUtils.isEmpty(file.getDestFile())) {
        throw new IllegalArgumentException("dest_file is empty.");
      }

      if (destFileSet.contains(file.getDestFile())) {
        throw new IllegalArgumentException(
            "Duplicated ConfigFile exists: " + file.getDestFile());
      }
      destFileSet.add(file.getDestFile());

      java.nio.file.Path destPath = Paths.get(file.getDestFile());
      if (!destPath.isAbsolute() && destPath.getNameCount() > 1) {
        throw new IllegalArgumentException("Non-absolute dest_file has more " +
            "than one path element");
      }

      // provider-specific validation
      validateConfigFile(file, compName, fs);
    }
  }
}

