@Override
public void setIntValues(final Item orgUnitItem, final Attribute attr, final RealmTO realmTO) {
    List<Object> values = null;
    if (attr != null) {
        values = attr.getValue();
        for (ItemTransformer transformer : MappingUtils.getItemTransformers(orgUnitItem)) {
            values = transformer.beforePull(orgUnitItem, realmTO, values);
        }
    }

    if (values != null && !values.isEmpty() && values.get(0) != null) {
        switch (orgUnitItem.getIntAttrName()) {
            case "name":
                realmTO.setName(values.get(0).toString());
                break;

            case "fullpath":
                String parentFullPath = StringUtils.substringBeforeLast(values.get(0).toString(), "/");
                Realm parent = realmDAO.findByFullPath(parentFullPath);
                if (parent == null) {
                    LOG.warn("Could not find Realm with path {}, ignoring", parentFullPath);
                } else {
                    realmTO.setParent(parent.getFullPath());
                }
                break;

            default:
        }
    }
}

private void rehash(Entry[] oldMap, int newCount, int newCapacity) {
  int oldCapacity = oldMap.length;

  Entry newMap[] = new Entry[newCapacity];

  synchronized (rehashLock) {
    for (int i = oldCapacity; i-- > 0;) {
      for (Entry old = oldMap[i]; old != null;) {
        Entry e = old;
        old = old.next;

        if (e.value != null && e.value instanceof WeakReference) {
          WeakReference r = (WeakReference) e.value;
          if (r.get() == null) {
            // don't copy this one into the new table since its value was gc'd
            newCount--;
            continue;
          }
        }
        int index = Math.abs(e.key) % newCapacity;
        e.next = newMap[index];
        newMap[index] = e;
      }
    }

    threshold = (int) (newCapacity * loadFactor);
    count = newCount;
    table = newMap;
  }
}

public class StagingItemReader<T> implements ItemReader<ProcessIndicatorItemWrapper<T>>, StepExecutionListener,
InitializingBean, DisposableBean {

	private static Log logger = LogFactory.getLog(StagingItemReader.class);

	private StepExecution stepExecution;

	private final Object lock = new Object();

	private volatile boolean initialized = false;

	private volatile Iterator<Long> keys;

	private JdbcOperations jdbcTemplate;

	public void setDataSource(DataSource dataSource) {
		jdbcTemplate = new JdbcTemplate(dataSource);
	}

	@Override
	public void destroy() throws Exception {
		initialized = false;
		keys = null;
	}

	@Override
	public final void afterPropertiesSet() throws Exception {
		Assert.notNull(jdbcTemplate, "You must provide a DataSource.");
	}

	private List<Long> retrieveKeys() {

		synchronized (lock) {

			return jdbcTemplate.query(

					"SELECT ID FROM BATCH_STAGING WHERE JOB_ID=? AND PROCESSED=? ORDER BY ID",

					new RowMapper<Long>() {
						@Override
						public Long mapRow(ResultSet rs, int rowNum) throws SQLException {
							return rs.getLong(1);
						}
					},

					stepExecution.getJobExecution().getJobId(), StagingItemWriter.NEW);

		}

	}

	@Override
	public ProcessIndicatorItemWrapper<T> read() {
		if (!initialized) {
			throw new ReaderNotOpenException("Reader must be open before it can be used.");
		}

		Long id = null;
		synchronized (lock) {
			if (keys.hasNext()) {
				id = keys.next();
			}
		}
		logger.debug("Retrieved key from list: " + id);

		if (id == null) {
			return null;
		}
		@SuppressWarnings("unchecked")
		T result = (T) jdbcTemplate.queryForObject("SELECT VALUE FROM BATCH_STAGING WHERE ID=?",
				new RowMapper<Object>() {
			@Override
			public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
				byte[] blob = rs.getBytes(1);
				return SerializationUtils.deserialize(blob);
			}
		}, id);

		return new ProcessIndicatorItemWrapper<>(id, result);
	}

	@Override
	public ExitStatus afterStep(StepExecution stepExecution) {
		return null;
	}

	@Override
	public void beforeStep(StepExecution stepExecution) {
		this.stepExecution = stepExecution;
		synchronized (lock) {
			if (keys == null) {
				keys = retrieveKeys().iterator();
				logger.info("Keys obtained for staging.");
				initialized = true;
			}
		}
	}

}

static class ExponentialRandomBackOffContext
		extends ExponentialBackOffPolicy.ExponentialBackOffContext {

	private final Random r = new Random();

	public ExponentialRandomBackOffContext(long expSeed, double multiplier,
			long maxInterval) {
		super(expSeed, multiplier, maxInterval);
	}

	@Override
	public synchronized long getSleepAndIncrement() {
		long next = super.getSleepAndIncrement();
		next = (long) (next * (1 + r.nextFloat() * (getMultiplier() - 1)));
		return next;
	}

}

