@SuppressWarnings("deprecation")
private static Maybe<Calendar> parseCalendarDefaultParse(String input) {
    try {
        long ms = Date.parse(input);
        if (ms>=new Date(1999, 12, 25).getTime() && ms <= new Date(2200, 1, 2).getTime()) {
            // accept default date parse for this century and next
            GregorianCalendar c = new GregorianCalendar();
            c.setTimeInMillis(ms);
            return Maybe.of((Calendar)c);
        }
    } catch (Exception e) {
        Exceptions.propagateIfFatal(e);
    }
    return Maybe.absent();
}

@Repository
public class UserDao {

    private static final String DEFAULT_USER_CREDENTIALS_PROPERTIES = "users-credentials.properties";

    private static final Logger LOG = LoggerFactory.getLogger(UserDao.class);

    private Properties userLogins;

    @PostConstruct
    public void init() {
        loadFileLoginsDetails();
    }

    void loadFileLoginsDetails() {
        InputStream inStr = null;
        try {
            Configuration configuration = ApplicationProperties.get();
            inStr = ApplicationProperties.getFileAsInputStream(configuration, "atlas.authentication.method.file.filename", DEFAULT_USER_CREDENTIALS_PROPERTIES);
            userLogins = new Properties();
            userLogins.load(inStr);
        } catch (IOException | AtlasException e) {
            LOG.error("Error while reading user.properties file", e);
            throw new RuntimeException(e);
        } finally {
            if(inStr != null) {
                try {
                    inStr.close();
                } catch(Exception excp) {
                    // ignore
                }
            }
        }
    }

    public User loadUserByUsername(final String username)
            throws AuthenticationException {
        String userdetailsStr = userLogins.getProperty(username);
        if (userdetailsStr == null || userdetailsStr.isEmpty()) {
            throw new UsernameNotFoundException("Username not found."
                    + username);
        }
        String password = "";
        String role = "";
        String dataArr[] = userdetailsStr.split("::");
        if (dataArr != null && dataArr.length == 2) {
            role = dataArr[0];
            password = dataArr[1];
        } else {
            LOG.error("User role credentials is not set properly for {}", username);
            throw new AtlasAuthenticationException("User role credentials is not set properly for " + username );
        }

        List<GrantedAuthority> grantedAuths = new ArrayList<>();
        if (StringUtils.hasText(role)) {
            grantedAuths.add(new SimpleGrantedAuthority(role));
        } else {
            LOG.error("User role credentials is not set properly for {}", username);
            throw new AtlasAuthenticationException("User role credentials is not set properly for " + username );
        }

        User userDetails = new User(username, password, grantedAuths);

        return userDetails;
    }


    @VisibleForTesting
    public void setUserLogins(Properties userLogins) {
        this.userLogins = userLogins;
    }


    public static String getSha256Hash(String base) throws AtlasAuthenticationException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(base.getBytes("UTF-8"));
            StringBuffer hexString = new StringBuffer();

            for (byte aHash : hash) {
                String hex = Integer.toHexString(0xff & aHash);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();

        } catch (Exception ex) {
            throw new AtlasAuthenticationException("Exception while encoding password.", ex);
        }
    }

}

public ClientListenerResponse doHandle(OdbcRequest req) {
    if (!busyLock.enterBusy())
        return new OdbcResponse(IgniteQueryErrorCode.UNKNOWN,
            "Failed to handle ODBC request because node is stopping: " + req);

    if (actx != null)
        AuthorizationContext.context(actx);

    try {
        switch (req.command()) {
            case QRY_EXEC:
                return executeQuery((OdbcQueryExecuteRequest)req);

            case QRY_EXEC_BATCH:
                return executeBatchQuery((OdbcQueryExecuteBatchRequest)req);

            case STREAMING_BATCH:
                return dispatchBatchOrdered((OdbcStreamingBatchRequest)req);

            case QRY_FETCH:
                return fetchQuery((OdbcQueryFetchRequest)req);

            case QRY_CLOSE:
                return closeQuery((OdbcQueryCloseRequest)req);

            case META_COLS:
                return getColumnsMeta((OdbcQueryGetColumnsMetaRequest)req);

            case META_TBLS:
                return getTablesMeta((OdbcQueryGetTablesMetaRequest)req);

            case META_PARAMS:
                return getParamsMeta((OdbcQueryGetParamsMetaRequest)req);

            case MORE_RESULTS:
                return moreResults((OdbcQueryMoreResultsRequest)req);
        }

        return new OdbcResponse(IgniteQueryErrorCode.UNKNOWN, "Unsupported ODBC request: " + req);
    }
    finally {
        AuthorizationContext.clear();

        busyLock.leaveBusy();
    }
}

@Override
public boolean isExists(Object identifier) throws AppCatalogException {
    HashMap<String, String> ids;
    if (identifier instanceof Map) {
        ids = (HashMap) identifier;
    } else {
        logger.error("Identifier should be a map with the field name and it's value");
        throw new AppCatalogException("Identifier should be a map with the field name and it's value");
    }

    EntityManager em = null;
    try {
        em = AppCatalogJPAUtils.getEntityManager();
        ComputeResourcePreference existingPreference = em.find(ComputeResourcePreference.class,
                new ComputeResourcePreferencePK(ids.get(ComputeResourcePreferenceConstants.GATEWAY_ID),
                        ids.get(ComputeResourcePreferenceConstants.RESOURCE_ID)));
        if (em.isOpen()) {
            if (em.getTransaction().isActive()){
                em.getTransaction().rollback();
            }
            em.close();
        }
        return existingPreference != null;
    }catch (Exception e) {
        logger.error(e.getMessage(), e);
        throw new AppCatalogException(e);
    } finally {
        if (em != null && em.isOpen()) {
            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }
            em.close();
        }
    }
}

private boolean sampleLoadingFinished(Map<TopicPartition, Long> endOffsets) {
  for (Map.Entry<TopicPartition, Long> entry : endOffsets.entrySet()) {
    long position = _consumer.position(entry.getKey());
    if (position < entry.getValue()) {
      LOG.debug("Partition {} is still lagging. Current position: {}, LEO: {}", entry.getKey(),
