public class CoapEncoder implements StatelessProtocolEncoder<CoapMessage, ByteBuffer> {

    private static final Logger LOG = LoggerFactory.getLogger(CoapEncoder.class);

    private static final int HEADER_SIZE = 4;

    /**
     * {@inheritDoc}
     */
    @Override
    public Void createEncoderState() {
        return null;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public ByteBuffer encode(CoapMessage message, Void context) {

        LOG.debug("encoding {}", message);

        // compute size of the needed buffer
        int size = HEADER_SIZE + message.getToken().length;

        int delta = 0;
        for (CoapOption opt : message.getOptions()) {
            // compute delta encoding size
            int code = opt.getType().getCode();
            delta = code - delta;
            if (delta < 13) {
                size += 1;
            } else if (delta < 256 + 13) {
                size += 2;
            } else if (delta < 65536 + 269) {
                size += 3;
            }

            // compute option length encoding size
            int optLength = opt.getData().length;
            if (optLength < 13) {
                size += 0;
            } else if (optLength < 256 + 13) {
                size += 1;
            } else if (optLength < 65536 + 269) {
                size += 2;
            }

            // compute option data encoding size
            size += optLength;
        }

        // if we have a payload, we place the marker and the payload
        if (message.getPayload() != null && message.getPayload().length > 0) {
            // payload marker
            size += 1;
            size += message.getPayload().length;
        }

        ByteBuffer buffer = ByteBuffer.allocate(size);

        buffer.order(ByteOrder.BIG_ENDIAN);

        // encode header
        buffer.put((byte) (((message.getVersion() & 0x03) << 6) | (message.getType().getCode() & 0x03) << 4 | (message
                .getToken().length & 0x0F)));
        buffer.put((byte) message.getCode());
        buffer.putShort((short) message.getId());
        buffer.put(message.getToken());

        // encode options
        int lastOptCode = 0;

        for (CoapOption opt : message.getOptions()) {
            int optionDelta = opt.getType().getCode() - lastOptCode;
            int deltaQuartet = getQuartet(optionDelta);
            int optionLength = opt.getData().length;

            int optionQuartet = getQuartet(optionLength);

            buffer.put((byte) ((deltaQuartet << 4) | optionQuartet));

            // write extended option delta field (0 - 2 bytes)
            if (deltaQuartet == 13) {
                buffer.put((byte) (optionDelta - 13));
            } else if (deltaQuartet == 14) {
                buffer.putShort((short) (optionDelta - 269));
            }

            if (optionQuartet == 13) {
                buffer.put((byte) (optionLength - 13));
            } else if (optionQuartet == 14) {
                buffer.putShort((short) (optionLength - 269));
            }
            buffer.put(opt.getData());

            lastOptCode = opt.getType().getCode();
        }

        if (message.getPayload() != null && message.getPayload().length > 0) {
            buffer.put((byte) 0xFF);
            buffer.put(message.getPayload());
        }

        buffer.flip();
        return buffer;
    }

    private int getQuartet(int value) {
        if (value <= 12) {
            return value;
        } else if (value <= 255 + 13) {
            return 13;
        } else {
            return 14;
        }
    }
}

class OffsetStream {

    private static final Logger logger = LoggerFactory.getLogger(OffsetStream.class);

    private final File directory;
    private final int offsetFileMaxSize;

    @Getter private final Offset offset;
    private File offsetFile;
    private boolean initialized = false;
    private String lastOffsetRecord = "";

    OffsetStream(File directory, int offsetFileMaxSize) {
        this.directory = directory;
        this.offsetFileMaxSize = offsetFileMaxSize;
        this.offset = new Offset();
    }

    void clean() throws IOException {
        String[] fileNames = directory.list(new PrefixFileFilter(BufferFileUtils.OFFSET_FILE_PREFIX));
        if (fileNames != null) {
            for (String fileName : fileNames) {
                File file = new File(directory, fileName);
                if (logger.isDebugEnabled()) {
                    logger.debug("Delete buffer offset file: {}", file.getAbsolutePath());
                }
                FileUtils.forceDelete(new File(directory, fileName));
            }
        }
    }

    synchronized void initialize() throws IOException {
        if (!initialized) {
            String[] fileNames = directory.list(new PrefixFileFilter(BufferFileUtils.OFFSET_FILE_PREFIX));
            if (fileNames != null && fileNames.length > 0) {
                BufferFileUtils.sort(fileNames);
                offsetFile = new File(directory, fileNames[0]);
            } else {
                offsetFile = newFile();
            }
            offset.deserialize(readLastLine());
            initialized = true;

            Executors.newSingleThreadScheduledExecutor().scheduleAtFixedRate(
                new RunnableWithExceptionProtection(this::flush,
                    t -> logger.error("Flush offset file in background failure.", t)
                ), 2, 1, TimeUnit.SECONDS);
        }
    }

    void flush() {
        try {
            String offsetRecord = offset.serialize();
            if (!lastOffsetRecord.equals(offsetRecord)) {
                logger.debug("flush offset, record: {}", offsetRecord);
                if (offsetFile.length() >= FileUtils.ONE_MB * offsetFileMaxSize) {
                    nextFile();
                }

                try (OutputStream out = new BufferedOutputStream(FileUtils.openOutputStream(offsetFile, true))) {
                    IOUtils.write(offsetRecord, out, Charset.forName(BufferFileUtils.CHARSET));
                    IOUtils.write(System.lineSeparator(), out, Charset.forName(BufferFileUtils.CHARSET));
                }
                lastOffsetRecord = offsetRecord;
            }
        } catch (IOException e) {
            throw new RuntimeException(e.getMessage(), e);
        }
    }

    private void nextFile() throws IOException {
        File newOffsetFile = newFile();
        if (!offsetFile.delete()) {
            logger.warn("Offset file {} delete failure.", newOffsetFile.getAbsolutePath());
        }
        offsetFile = newOffsetFile;
        this.flush();
    }

    private File newFile() throws IOException {
        String fileName = BufferFileUtils.buildFileName(BufferFileUtils.OFFSET_FILE_PREFIX);
        File file = new File(directory, fileName);
        if (file.createNewFile()) {
            logger.info("Create a new offset file {}", fileName);
        }
        return file;
    }

    private String readLastLine() throws IOException {
        ReversedLinesFileReader reader = new ReversedLinesFileReader(offsetFile, Charset.forName(BufferFileUtils.CHARSET));
        return reader.readLine();
    }
}

