public class WeightedRunningAverage implements RunningAverage, Serializable {

  private double totalWeight;
  private double average;

  public WeightedRunningAverage() {
    totalWeight = 0.0;
    average = Double.NaN;
  }

  @Override
  public synchronized void addDatum(double datum) {
    addDatum(datum, 1.0);
  }

  public synchronized void addDatum(double datum, double weight) {
    double oldTotalWeight = totalWeight;
    totalWeight += weight;
    if (oldTotalWeight <= 0.0) {
      average = datum;
    } else {
      average = average * oldTotalWeight / totalWeight + datum * weight / totalWeight;
    }
  }

  @Override
  public synchronized void removeDatum(double datum) {
    removeDatum(datum, 1.0);
  }

  public synchronized void removeDatum(double datum, double weight) {
    double oldTotalWeight = totalWeight;
    totalWeight -= weight;
    if (totalWeight <= 0.0) {
      average = Double.NaN;
      totalWeight = 0.0;
    } else {
      average = average * oldTotalWeight / totalWeight - datum * weight / totalWeight;
    }
  }

  @Override
  public synchronized void changeDatum(double delta) {
    changeDatum(delta, 1.0);
  }

  public synchronized void changeDatum(double delta, double weight) {
    Preconditions.checkArgument(weight <= totalWeight, "weight must be <= totalWeight");
    average += delta * weight / totalWeight;
  }

  public synchronized double getTotalWeight() {
    return totalWeight;
  }

  /** @return {@link #getTotalWeight()} */
  @Override
  public synchronized int getCount() {
    return (int) totalWeight;
  }

  @Override
  public synchronized double getAverage() {
    return average;
  }

  @Override
  public RunningAverage inverse() {
    return new InvertedRunningAverage(this);
  }

  @Override
  public synchronized String toString() {
    return String.valueOf(average);
  }

}

private static class WeightedMultiWorkUnit extends MultiWorkUnit implements Comparable<WeightedMultiWorkUnit> {

  private long weight = 0l;

  /**
   * Add a new single workUnit to the current workUnits list. Update the weight by adding the weight of the new workUnit.
   *
   * @param weight the weight of the newWorkUnit.
   * @param newWorkUnit the new work unit.
   */
  private void addWorkUnit(long weight, WorkUnit newWorkUnit) {
    this.addWorkUnit(newWorkUnit);
    this.weight += weight;
  }

  /**
   * Compare with the other weightedMultiWorkUnit based on weight.
   */
  @Override
  public int compareTo(WeightedMultiWorkUnit weightedMultiWorkUnit) {
    return Longs.compare(this.weight, weightedMultiWorkUnit.getWeight());
  }

  @Override
  public int hashCode() {
    final int prime = 31;
    int result = 1;
    result = prime * result + (int) (this.weight ^ (this.weight >>> 32));
    return result;
  }

  @Override
  public boolean equals(Object obj) {
    if (!(obj instanceof WeightedMultiWorkUnit)) {
      return false;
    }
    WeightedMultiWorkUnit weightedMultiWorkUnit = (WeightedMultiWorkUnit) obj;
    return this.weight == weightedMultiWorkUnit.getWeight();
  }

  public long getWeight() {
    return this.weight;
  }
}

