@Component
@Reference(name = "shell", strategy = ReferenceStrategy.EVENT, policy = ReferencePolicy.DYNAMIC,
    referenceInterface = Shell.class, cardinality = ReferenceCardinality.OPTIONAL_UNARY)
public class JdkDelegatingLogListener extends AbstractFlashingObject implements LogListener {

  public static final String DO_NOT_LOG = "#DO_NOT_LOG";
  private final static Logger LOGGER = HandlerUtils.getLogger(JdkDelegatingLogListener.class);

  @Reference(policy = ReferencePolicy.DYNAMIC)
  private volatile LogReaderService logReaderService;

  public static String cleanThrowable(final Throwable throwable) {
    final StringBuilder result = new StringBuilder();
    result.append(LINE_SEPARATOR);
    result.append(throwable.toString().replace(DO_NOT_LOG, ""));
    result.append(LINE_SEPARATOR);
    for (final StackTraceElement ste : throwable.getStackTrace()) {
      result.append(ste);
      result.append(LINE_SEPARATOR);
    }
    return result.toString();
  }

  @SuppressWarnings("unchecked")
  protected void activate(final ComponentContext context) {
    logReaderService.addLogListener(this);
    final Enumeration<LogEntry> latestLogs = logReaderService.getLog();
    if (latestLogs.hasMoreElements()) {
      logNow(latestLogs.nextElement(), false);
    }
  }

  private String buildMessage(final LogEntry entry) {
    final StringBuilder sb = new StringBuilder();
    sb.append("[").append(entry.getBundle()).append("] ").append(entry.getMessage());
    return sb.toString();
  }

  private boolean containsDoNotLogTag(final Throwable throwable) {
    if (throwable == null) {
      return false;
    }
    if (throwable.getMessage().contains(DO_NOT_LOG)) {
      return true;
    }
    final StringWriter sw = new StringWriter();
    throwable.printStackTrace(new PrintWriter(sw));
    return sw.toString().contains(DO_NOT_LOG);
  }

  protected void deactivate(final ComponentContext context) {
    logReaderService.removeLogListener(this);
  }

  public void logged(final LogEntry entry) {
    if (containsDoNotLogTag(entry.getException())) {
      // Only log Felix stack trace in development mode, discard log
      // otherwise
      if (isDevelopmentMode()) {
        logNow(entry, true);
      }
    } else {
      logNow(entry, false);
    }
  }

  private void logNow(final LogEntry entry, final boolean removeDoNotLogTag) {
    final int osgiLevel = entry.getLevel();
    Level jdkLevel = Level.FINEST;

    // Convert the OSGi level into a JDK logger level
    if (osgiLevel == LogService.LOG_DEBUG) {
      jdkLevel = Level.FINE;
    } else if (osgiLevel == LogService.LOG_INFO) {
      jdkLevel = Level.INFO;
    } else if (osgiLevel == LogService.LOG_WARNING) {
      jdkLevel = Level.WARNING;
    } else if (osgiLevel == LogService.LOG_ERROR) {
      jdkLevel = Level.SEVERE;
    }

    if (jdkLevel.intValue() <= Level.INFO.intValue()) {
      // Not very important message, so just flash it if possible and
      // we're in development mode
      if (isDevelopmentMode()) {
        flash(jdkLevel, buildMessage(entry), MY_SLOT);
        // Immediately clear it once the timeout has been reached
        flash(jdkLevel, "", MY_SLOT);
      }
    } else {
      // Important log message, so log it via JDK
      if (removeDoNotLogTag) {
        LOGGER.log(jdkLevel, buildMessage(entry) + cleanThrowable(entry.getException()));
      } else {
        LOGGER.log(jdkLevel, buildMessage(entry), entry.getException());
      }
    }
  }
}

private class IncrementalIndexCursor implements Cursor
{
  private IncrementalIndexRowHolder currEntry;
  private final ColumnSelectorFactory columnSelectorFactory;
  private final ValueMatcher filterMatcher;
  private final int maxRowIndex;
  private Iterator<IncrementalIndexRow> baseIter;
  private Iterable<IncrementalIndexRow> cursorIterable;
  private boolean emptyRange;
  private final DateTime time;
  private int numAdvanced;
  private boolean done;

  IncrementalIndexCursor(
      VirtualColumns virtualColumns,
      boolean descending,
      Filter filter,
      Interval interval,
      Interval actualInterval,
      Granularity gran
  )
  {
    currEntry = new IncrementalIndexRowHolder();
    columnSelectorFactory = new IncrementalIndexColumnSelectorFactory(index, virtualColumns, descending, currEntry);
    // Set maxRowIndex before creating the filterMatcher. See https://github.com/apache/incubator-druid/pull/6340
    maxRowIndex = index.getLastRowIndex();
    filterMatcher = filter == null ? BooleanValueMatcher.of(true) : filter.makeMatcher(columnSelectorFactory);
    numAdvanced = -1;
    final long timeStart = Math.max(interval.getStartMillis(), actualInterval.getStartMillis());
    cursorIterable = index.getFacts().timeRangeIterable(
        descending,
        timeStart,
        Math.min(actualInterval.getEndMillis(), gran.increment(interval.getStart()).getMillis())
    );
    emptyRange = !cursorIterable.iterator().hasNext();
    time = gran.toDateTime(interval.getStartMillis());

    reset();
  }

  @Override
  public ColumnSelectorFactory getColumnSelectorFactory()
  {
    return columnSelectorFactory;
  }

  @Override
  public DateTime getTime()
  {
    return time;
  }

  @Override
  public void advance()
  {
    if (!baseIter.hasNext()) {
      done = true;
      return;
    }

    while (baseIter.hasNext()) {
      BaseQuery.checkInterrupted();

      IncrementalIndexRow entry = baseIter.next();
      if (beyondMaxRowIndex(entry.getRowIndex())) {
        continue;
      }

      currEntry.set(entry);

      if (filterMatcher.matches()) {
        return;
      }
    }

    done = true;
  }

  @Override
  public void advanceUninterruptibly()
  {
    if (!baseIter.hasNext()) {
      done = true;
      return;
    }

    while (baseIter.hasNext()) {
      if (Thread.currentThread().isInterrupted()) {
        return;
      }

      IncrementalIndexRow entry = baseIter.next();
      if (beyondMaxRowIndex(entry.getRowIndex())) {
        continue;
      }

      currEntry.set(entry);

      if (filterMatcher.matches()) {
        return;
      }
    }

    done = true;
  }

  @Override
  public void advanceTo(int offset)
  {
    int count = 0;
    while (count < offset && !isDone()) {
      advance();
      count++;
    }
  }

  @Override
  public boolean isDone()
  {
    return done;
  }

  @Override
  public boolean isDoneOrInterrupted()
  {
    return isDone() || Thread.currentThread().isInterrupted();
  }

  @Override
  public void reset()
  {
    baseIter = cursorIterable.iterator();

    if (numAdvanced == -1) {
      numAdvanced = 0;
    } else {
      Iterators.advance(baseIter, numAdvanced);
    }

    BaseQuery.checkInterrupted();

    boolean foundMatched = false;
    while (baseIter.hasNext()) {
      IncrementalIndexRow entry = baseIter.next();
      if (beyondMaxRowIndex(entry.getRowIndex())) {
        numAdvanced++;
        continue;
      }
      currEntry.set(entry);
      if (filterMatcher.matches()) {
        foundMatched = true;
        break;
      }

      numAdvanced++;
    }

    done = !foundMatched && (emptyRange || !baseIter.hasNext());
  }

  private boolean beyondMaxRowIndex(int rowIndex)
  {
    // ignore rows whose rowIndex is beyond the maxRowIndex
    // rows are order by timestamp, not rowIndex,
    // so we still need to go through all rows to skip rows added after cursor created
    return rowIndex > maxRowIndex;
  }
}

@GroovyASTTransformation(phase = CompilePhase.CANONICALIZATION)

public class SortableASTTransformation extends AbstractASTTransformation {
    private static final ClassNode MY_TYPE = make(Sortable.class);
    private static final String MY_TYPE_NAME = "@" + MY_TYPE.getNameWithoutPackage();
    private static final ClassNode COMPARABLE_TYPE = makeClassSafe(Comparable.class);
    private static final ClassNode COMPARATOR_TYPE = makeClassSafe(Comparator.class);

    private static final String VALUE = "value";
    private static final String OTHER = "other";
    private static final String THIS_HASH = "thisHash";
    private static final String OTHER_HASH = "otherHash";
    private static final String ARG0 = "arg0";
    private static final String ARG1 = "arg1";

    public void visit(ASTNode[] nodes, SourceUnit source) {
        init(nodes, source);
        AnnotationNode annotation = (AnnotationNode) nodes[0];
        AnnotatedNode parent = (AnnotatedNode) nodes[1];
        if (parent instanceof ClassNode) {
            createSortable(annotation, (ClassNode) parent);
        }
    }

    private void createSortable(AnnotationNode anno, ClassNode classNode) {
        List<String> includes = getMemberStringList(anno, "includes");
        List<String> excludes = getMemberStringList(anno, "excludes");
        boolean reversed = memberHasValue(anno, "reversed", true);
        boolean includeSuperProperties = memberHasValue(anno, "includeSuperProperties", true);
        boolean allNames = memberHasValue(anno, "allNames", true);
        boolean allProperties = !memberHasValue(anno, "allProperties", false);
        if (!checkIncludeExcludeUndefinedAware(anno, excludes, includes, MY_TYPE_NAME)) return;
        if (!checkPropertyList(classNode, includes, "includes", anno, MY_TYPE_NAME, false, includeSuperProperties, allProperties)) return;
        if (!checkPropertyList(classNode, excludes, "excludes", anno, MY_TYPE_NAME, false, includeSuperProperties, allProperties)) return;
        if (classNode.isInterface()) {
            addError(MY_TYPE_NAME + " cannot be applied to interface " + classNode.getName(), anno);
        }
        List<PropertyNode> properties = findProperties(anno, classNode, includes, excludes, allProperties, includeSuperProperties, allNames);
        implementComparable(classNode);

        addGeneratedMethod(classNode,
                "compareTo",
                ACC_PUBLIC,
                ClassHelper.int_TYPE,
                params(param(newClass(classNode), OTHER)),
                ClassNode.EMPTY_ARRAY,
                createCompareToMethodBody(properties, reversed)
        );

        for (PropertyNode property : properties) {
            createComparatorFor(classNode, property, reversed);
        }
        new VariableScopeVisitor(sourceUnit, true).visitClass(classNode);
    }

    private static void implementComparable(ClassNode classNode) {
        if (!classNode.implementsInterface(COMPARABLE_TYPE)) {
            classNode.addInterface(makeClassSafeWithGenerics(Comparable.class, classNode));
        }
    }

    private static Statement createCompareToMethodBody(List<PropertyNode> properties, boolean reversed) {
        List<Statement> statements = new ArrayList<Statement>();

        // if (this.is(other)) return 0;
        statements.add(ifS(callThisX("is", args(OTHER)), returnS(constX(0))));

        if (properties.isEmpty()) {
            // perhaps overkill but let compareTo be based on hashes for commutativity
            // return this.hashCode() <=> other.hashCode()
            statements.add(declS(localVarX(THIS_HASH, ClassHelper.Integer_TYPE), callX(varX("this"), "hashCode")));
            statements.add(declS(localVarX(OTHER_HASH, ClassHelper.Integer_TYPE), callX(varX(OTHER), "hashCode")));
            statements.add(returnS(compareExpr(varX(THIS_HASH), varX(OTHER_HASH), reversed)));
        } else {
            // int value = 0;
            statements.add(declS(localVarX(VALUE, ClassHelper.int_TYPE), constX(0)));
            for (PropertyNode property : properties) {
                String propName = property.getName();
                // value = this.prop <=> other.prop;
                statements.add(assignS(varX(VALUE), compareExpr(propX(varX("this"), propName), propX(varX(OTHER), propName), reversed)));
                // if (value != 0) return value;
                statements.add(ifS(neX(varX(VALUE), constX(0)), returnS(varX(VALUE))));
            }
            // objects are equal
            statements.add(returnS(constX(0)));
        }

        final BlockStatement body = new BlockStatement();
        body.addStatements(statements);
        return body;
    }

    private static Statement createCompareMethodBody(PropertyNode property, boolean reversed) {
        String propName = property.getName();
        return block(
                // if (arg0 == arg1) return 0;
                ifS(eqX(varX(ARG0), varX(ARG1)), returnS(constX(0))),
                // if (arg0 != null && arg1 == null) return -1;
                ifS(andX(notNullX(varX(ARG0)), equalsNullX(varX(ARG1))), returnS(constX(-1))),
                // if (arg0 == null && arg1 != null) return 1;
                ifS(andX(equalsNullX(varX(ARG0)), notNullX(varX(ARG1))), returnS(constX(1))),
                // return arg0.prop <=> arg1.prop;
                returnS(compareExpr(propX(varX(ARG0), propName), propX(varX(ARG1), propName), reversed))
        );
    }

    private static void createComparatorFor(ClassNode classNode, PropertyNode property, boolean reversed) {
        String propName = StringGroovyMethods.capitalize((CharSequence) property.getName());
        String className = classNode.getName() + "$" + propName + "Comparator";
        ClassNode superClass = makeClassSafeWithGenerics(AbstractComparator.class, classNode);
        InnerClassNode cmpClass = new InnerClassNode(classNode, className, ACC_PRIVATE | ACC_STATIC, superClass);
        addGeneratedInnerClass(classNode, cmpClass);

        addGeneratedMethod(cmpClass,
                "compare",
                ACC_PUBLIC,
                ClassHelper.int_TYPE,
                params(param(newClass(classNode), ARG0), param(newClass(classNode), ARG1)),
                ClassNode.EMPTY_ARRAY,
                createCompareMethodBody(property, reversed)
        );

        String fieldName = "this$" + propName + "Comparator";
        // private final Comparator this$<property>Comparator = new <type>$<property>Comparator();
        FieldNode cmpField = classNode.addField(
                fieldName,
                ACC_STATIC | ACC_FINAL | ACC_PRIVATE | ACC_SYNTHETIC,
                COMPARATOR_TYPE,
                ctorX(cmpClass));

        addGeneratedMethod(classNode,
                "comparatorBy" + propName,
                ACC_PUBLIC | ACC_STATIC,
                COMPARATOR_TYPE,
                Parameter.EMPTY_ARRAY,
                ClassNode.EMPTY_ARRAY,
                returnS(fieldX(cmpField))
        );
    }

    private List<PropertyNode> findProperties(AnnotationNode annotation, final ClassNode classNode, final List<String> includes,
                                              final List<String> excludes, final boolean allProperties,
                                              final boolean includeSuperProperties, final boolean allNames) {
        Set<String> names = new HashSet<String>();
        List<PropertyNode> props = getAllProperties(names, classNode, classNode, true, false, allProperties,
                false, includeSuperProperties, false, false, allNames, false);
        List<PropertyNode> properties = new ArrayList<PropertyNode>();
        for (PropertyNode property : props) {
            String propertyName = property.getName();
            if ((excludes != null && excludes.contains(propertyName)) ||
                    includes != null && !includes.contains(propertyName)) continue;
            properties.add(property);
        }
        for (PropertyNode pNode : properties) {
            checkComparable(pNode);
        }
        if (includes != null) {
            Comparator<PropertyNode> includeComparator = new Comparator<PropertyNode>() {
                public int compare(PropertyNode o1, PropertyNode o2) {
                    return Integer.compare(includes.indexOf(o1.getName()), includes.indexOf(o2.getName()));
                }
            };
            Collections.sort(properties, includeComparator);
        }
        return properties;
    }

    private void checkComparable(PropertyNode pNode) {
        if (pNode.getType().implementsInterface(COMPARABLE_TYPE) || isPrimitiveType(pNode.getType()) || hasAnnotation(pNode.getType(), MY_TYPE)) {
            return;
        }
        addError("Error during " + MY_TYPE_NAME + " processing: property '" +
                pNode.getName() + "' must be Comparable", pNode);
    }

    /**
     * Helper method used to build a binary expression that compares two values
     * with the option to handle reverse order.
     */
    private static BinaryExpression compareExpr(Expression lhv, Expression rhv, boolean reversed) {
        return (reversed) ? cmpX(rhv, lhv) : cmpX(lhv, rhv);
    }

}

@Override public boolean readFrom(ByteBuffer buf, MessageReader reader) {
    reader.setBuffer(buf);

    if (!reader.beforeMessageRead())
        return false;

    if (!super.readFrom(buf, reader))
        return false;

    switch (reader.state()) {
        case 3:
            futId = reader.readLong("futId");

            if (!reader.isLastRead())
                return false;

            reader.incrementState();

        case 4:
            locksArr = reader.readObjectArray("locksArr", MessageCollectionItemType.MSG, TxLockList.class);

            if (!reader.isLastRead())
                return false;

            reader.incrementState();

        case 5:
            nearTxKeysArr = reader.readObjectArray("nearTxKeysArr", MessageCollectionItemType.MSG, IgniteTxKey.class);

            if (!reader.isLastRead())
                return false;

            reader.incrementState();

        case 6:
            txKeysArr = reader.readObjectArray("txKeysArr", MessageCollectionItemType.MSG, IgniteTxKey.class);

            if (!reader.isLastRead())
                return false;

            reader.incrementState();

    }

    return reader.afterMessageRead(TxLocksResponse.class);
}

public void read(org.apache.thrift.protocol.TProtocol iprot, add_check_constraint_result struct) throws org.apache.thrift.TException {
  org.apache.thrift.protocol.TField schemeField;
  iprot.readStructBegin();
  while (true)
  {
    schemeField = iprot.readFieldBegin();
    if (schemeField.type == org.apache.thrift.protocol.TType.STOP) { 
      break;
    }
    switch (schemeField.id) {
      case 1: // O1
        if (schemeField.type == org.apache.thrift.protocol.TType.STRUCT) {
          struct.o1 = new NoSuchObjectException();
          struct.o1.read(iprot);
          struct.setO1IsSet(true);
        } else { 
          org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
        }
        break;
      case 2: // O2
        if (schemeField.type == org.apache.thrift.protocol.TType.STRUCT) {
          struct.o2 = new MetaException();
          struct.o2.read(iprot);
          struct.setO2IsSet(true);
        } else { 
          org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
        }
        break;
      default:
        org.apache.thrift.protocol.TProtocolUtil.skip(iprot, schemeField.type);
    }
    iprot.readFieldEnd();
  }
  iprot.readStructEnd();
  struct.validate();
}

public class Butcher {

	@Transformer
	public Meat sell(Ingredient ingredient) {
		return new Meat(ingredient.getName(), ingredient.getAmount());
	}

    @Transformer
    public GroceryBag<Meat> sell(ShoppingList shoppingList) {
        GroceryBag<Meat> groceryBag = new GroceryBag<Meat>();
        for (Ingredient ingredient : shoppingList.getItems()) {
            groceryBag.put(sell(ingredient));
        }
        return groceryBag;
    }
}

public class SerializableGlobalSumAggregateFunction extends AbstractSerializableSumAggregateFunction {

    public SerializableGlobalSumAggregateFunction(IScalarEvaluatorFactory[] args, IHyracksTaskContext context,
            SourceLocation sourceLoc) throws HyracksDataException {
        super(args, context, sourceLoc);
    }

    // Called for each incoming tuple
    @Override
    public void step(IFrameTupleReference tuple, byte[] state, int start, int len) throws HyracksDataException {
        super.step(tuple, state, start, len);
    }

    // Finish calculation
    @Override
    public void finish(byte[] state, int start, int len, DataOutput out) throws HyracksDataException {
        super.finish(state, start, len, out);
    }

    // Is skip
    @Override
    protected boolean skipStep(byte[] state, int start) {
        ATypeTag aggType = EnumDeserializer.ATYPETAGDESERIALIZER.deserialize(state[start + AGG_TYPE_OFFSET]);
        return aggType == ATypeTag.NULL;
    }

    // Handle NULL step
    @Override
    protected void processNull(byte[] state, int start) {
        state[start + AGG_TYPE_OFFSET] = ATypeTag.SERIALIZED_NULL_TYPE_TAG;
    }

    // Handle SYSTEM_NULL step
    @Override
    protected void processSystemNull() {
        // Do nothing
    }

    // Handle NULL finish
    @Override
    protected void finishNull(DataOutput out) throws IOException {
        out.writeByte(ATypeTag.SERIALIZED_NULL_TYPE_TAG);
    }

    // Handle SYSTEM_NULL finish
    @Override
    protected void finishSystemNull(DataOutput out) throws IOException {
        out.writeByte(ATypeTag.SERIALIZED_NULL_TYPE_TAG);
    }
}

private static class GridMBeanServerData {
    /** Set of grid names for selected MBeanServer. */
    private Collection<String> igniteInstanceNames = new HashSet<>();

    /** */
    private ObjectName mbean;

    /** Count of grid instances. */
    private int cnt;

    /**
     * Create data container.
     *
     * @param mbean Object name of MBean.
     */
    GridMBeanServerData(ObjectName mbean) {
        assert mbean != null;

        this.mbean = mbean;
    }

    /**
     * Add Ignite instance name.
     *
     * @param igniteInstanceName Ignite instance name.
     */
    public void addIgniteInstance(String igniteInstanceName) {
        igniteInstanceNames.add(igniteInstanceName);
    }

    /**
     * Remove Ignite instance name.
     *
     * @param igniteInstanceName Ignite instance name.
     */
    public void removeIgniteInstance(String igniteInstanceName) {
        igniteInstanceNames.remove(igniteInstanceName);
    }

    /**
     * Returns {@code true} if data contains the specified
     * Ignite instance name.
     *
     * @param igniteInstanceName Ignite instance name.
     * @return {@code true} if data contains the specified Ignite instance name.
