public class MainActivity extends FragmentActivity {
    private static final String TAG = "MainActivity";
    private static final String INAPP_PURCHASE_DATA = "INAPP_PURCHASE_DATA";

    static final int RPS = 0;
    static final int SETTINGS = 1;
    static final int CONTENT = 2;
    static final int FRAGMENT_COUNT = CONTENT +1;

    private Fragment[] fragments = new Fragment[FRAGMENT_COUNT];
    private MenuItem settings;
    private MenuItem challenge;
    private MenuItem share;
    private MenuItem message;
    private boolean isResumed = false;
    private boolean hasNativeLink = false;
    private CallbackManager callbackManager;
    private GameRequestDialog gameRequestDialog;

    private AccessTokenTracker accessTokenTracker;

    @Override
    public void onCreate(Bundle savedInstanceState) {

        FacebookSdk.addLoggingBehavior(LoggingBehavior.APP_EVENTS);
        FacebookSdk.setIsDebugEnabled(true);

        super.onCreate(savedInstanceState);
        accessTokenTracker = new AccessTokenTracker() {
            @Override
            protected void onCurrentAccessTokenChanged(AccessToken oldAccessToken,
                                                       AccessToken currentAccessToken) {
                if (isResumed) {
                    if (currentAccessToken == null) {
                        showFragment(RPS, false);
                    }
                }
            }
        };

        setContentView(R.layout.main);

        FragmentManager fm = getSupportFragmentManager();
        fragments[RPS] = fm.findFragmentById(R.id.rps_fragment);
        fragments[SETTINGS] = fm.findFragmentById(R.id.settings_fragment);
        fragments[CONTENT] = fm.findFragmentById(R.id.content_fragment);

        FragmentTransaction transaction = fm.beginTransaction();
        for(int i = 0; i < fragments.length; i++) {
            transaction.hide(fragments[i]);
        }
        transaction.commit();

        hasNativeLink = handleNativeLink();

        gameRequestDialog = new GameRequestDialog(this);
        callbackManager = CallbackManager.Factory.create();
        gameRequestDialog.registerCallback(
                callbackManager,
                new FacebookCallback<GameRequestDialog.Result>() {
                    @Override
                    public void onCancel() {
                        Log.d(TAG, "Canceled");
                    }

                    @Override
                    public void onError(FacebookException error) {
                        Log.d(TAG, String.format("Error: %s", error.toString()));
                    }

                    @Override
                    public void onSuccess(GameRequestDialog.Result result) {
                        Log.d(TAG, "Success!");
                        Log.d(TAG, "Request id: " + result.getRequestId());
                        Log.d(TAG, "Recipients:");
                        for (String recipient : result.getRequestRecipients()) {
                            Log.d(TAG, recipient);
                        }
                    }
                });
    }

    @Override
    public void onResume() {
        super.onResume();
        isResumed = true;
    }

    @Override
    public void onPause() {
        super.onPause();
        isResumed = false;
    }

    @Override
    public void onActivityResult(int requestCode, int resultCode, Intent data) {
        callbackManager.onActivityResult(requestCode, resultCode, data);
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == RpsFragment.IN_APP_PURCHASE_RESULT) {
            String purchaseData = data.getStringExtra(INAPP_PURCHASE_DATA);

            if (resultCode == RESULT_OK) {
                RpsFragment fragment = (RpsFragment) fragments[RPS];
                try {
                    JSONObject jo = new JSONObject(purchaseData);
                    fragment.onInAppPurchaseSuccess(jo);
                }
                catch (JSONException e) {
                    Log.e(TAG, "In app purchase invalid json.", e);
                }
            }
        }
    }

    @Override
    public void onDestroy() {
        super.onDestroy();
        accessTokenTracker.stopTracking();
    }

    @Override
    protected void onResumeFragments() {
        super.onResumeFragments();

        if (hasNativeLink) {
            showFragment(CONTENT, false);
            hasNativeLink = false;
        } else {
            showFragment(RPS, false);
        }
    }

    @Override
    public boolean onPrepareOptionsMenu(Menu menu) {
        // only add the menu when the selection fragment is showing
        if (fragments[RPS].isVisible()) {
            if (menu.size() == 0) {
                share = menu.add(R.string.share_on_facebook);
                message = menu.add(R.string.send_with_messenger);
                challenge = menu.add(R.string.challenge_friends);
                settings = menu.add(R.string.check_settings);
            }
            return true;
        } else {
            menu.clear();
            settings = null;
        }
        return false;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.equals(settings)) {
            showFragment(SETTINGS, true);
            return true;
        } else if (item.equals(challenge)) {
            GameRequestContent newGameRequestContent = new GameRequestContent.Builder()
                    .setTitle(getString(R.string.challenge_dialog_title))
                    .setMessage(getString(R.string.challenge_dialog_message))
                    .build();

            gameRequestDialog.show(this, newGameRequestContent);

            return true;
        } else if (item.equals(share)) {
            RpsFragment fragment = (RpsFragment) fragments[RPS];
            fragment.shareUsingAutomaticDialog();
            return true;
        } else if (item.equals(message)) {
            RpsFragment fragment = (RpsFragment) fragments[RPS];
            fragment.shareUsingMessengerDialog();
            return true;
        }
        return false;
    }

    private boolean handleNativeLink() {
        if (!AccessToken.isCurrentAccessTokenActive()) {
            AccessToken.createFromNativeLinkingIntent(getIntent(),
                    FacebookSdk.getApplicationId(), new AccessToken.AccessTokenCreationCallback(){

                        @Override
                        public void onSuccess(AccessToken token) {
                            AccessToken.setCurrentAccessToken(token);
                        }

                        @Override
                        public void onError(FacebookException error) {

                        }
                    });
        }
        // See if we have a deep link in addition.
        int appLinkGesture = getAppLinkGesture(getIntent());
        if (appLinkGesture != INVALID_CHOICE) {
            ContentFragment fragment = (ContentFragment) fragments[CONTENT];
            fragment.setContentIndex(appLinkGesture);
            return true;
        }
        return false;
    }

    private int getAppLinkGesture(Intent intent) {
      Uri targetURI = AppLinks.getTargetUrlFromInboundIntent(this, intent);
      if (targetURI == null) {
        return INVALID_CHOICE;
      }
      String gesture = targetURI.getQueryParameter("gesture");
      if (gesture != null) {
          if (gesture.equalsIgnoreCase(getString(R.string.rock))) {
              return RpsGameUtils.ROCK;
          } else if (gesture.equalsIgnoreCase(getString(R.string.paper))) {
              return RpsGameUtils.PAPER;
          } else if (gesture.equalsIgnoreCase(getString(R.string.scissors))) {
              return RpsGameUtils.SCISSORS;
          }
      }
      return INVALID_CHOICE;
    }

    void showFragment(int fragmentIndex, boolean addToBackStack) {
        FragmentManager fm = getSupportFragmentManager();
        FragmentTransaction transaction = fm.beginTransaction();
        if (addToBackStack) {
            transaction.addToBackStack(null);
        } else {
            int backStackSize = fm.getBackStackEntryCount();
            for (int i = 0; i < backStackSize; i++) {
                fm.popBackStack();
            }
        }
        for (int i = 0; i < fragments.length; i++) {
            if (i == fragmentIndex) {
                transaction.show(fragments[i]);
            } else {
                transaction.hide(fragments[i]);
            }
        }
        transaction.commit();
    }
}

public java.lang.String getLanguage() {
  java.lang.Object ref = language_;
  if (ref instanceof java.lang.String) {
    return (java.lang.String) ref;
  } else {
    com.google.protobuf.ByteString bs = 
        (com.google.protobuf.ByteString) ref;
    java.lang.String s = bs.toStringUtf8();
    if (bs.isValidUtf8()) {
      language_ = s;
    }
    return s;
  }
}

static final class Key {

    final Object content;
    final URI uri;
    final URL url;
    final String name;
    final String mimeType;
    final String language;
    final String path;
    final boolean internal;
    final boolean interactive;
    final boolean cached;
    // TODO remove legacy field with deprecated Source builders.
    final boolean legacy;

    Key(Object content, String mimeType, String languageId, URL url, URI uri, String name, String path, boolean internal, boolean interactive, boolean cached, boolean legacy) {
        this.content = content;
        this.mimeType = mimeType;
        this.language = languageId;
        this.name = name;
        this.path = path;
        this.internal = internal;
        this.interactive = interactive;
        this.cached = cached;
        this.url = url;
        this.uri = uri;
        this.legacy = legacy;
    }

    @Override
    public int hashCode() {
        int result = 31 * 1 + ((content == null) ? 0 : content.hashCode());
        result = 31 * result + (interactive ? 1231 : 1237);
        result = 31 * result + (internal ? 1231 : 1237);
        result = 31 * result + (cached ? 1231 : 1237);
        result = 31 * result + ((language == null) ? 0 : language.hashCode());
        result = 31 * result + ((mimeType == null) ? 0 : mimeType.hashCode());
        result = 31 * result + ((name == null) ? 0 : name.hashCode());
        result = 31 * result + ((path == null) ? 0 : path.hashCode());
        result = 31 * result + ((uri == null) ? 0 : uri.hashCode());
        result = 31 * result + ((url == null) ? 0 : url.hashCode());
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        } else if (!(obj instanceof Key)) {
            return false;
        }
        Key other = (Key) obj;
        /*
         * Compare characters last as it is likely the most expensive comparison in the worst
         * case.
         */
        return Objects.equals(language, other.language) && //
                        Objects.equals(mimeType, other.mimeType) && //
                        Objects.equals(name, other.name) && //
                        Objects.equals(path, other.path) && //
                        Objects.equals(uri, other.uri) && //
                        Objects.equals(url, other.url) && //
                        interactive == other.interactive && //
                        internal == other.internal &&
                        cached == other.cached &&
                        compareContent(other);
    }

    private boolean compareContent(Key other) {
        Object otherContent = other.content;
        if (content == other.content) {
            return true;
        } else if (content instanceof CharSequence && otherContent instanceof CharSequence) {
            return compareCharacters((CharSequence) content, (CharSequence) otherContent);
        } else if (content instanceof ByteSequence && otherContent instanceof ByteSequence) {
            return compareBytes((ByteSequence) content, (ByteSequence) otherContent);
        } else {
            return false;
        }
    }

    private static boolean compareBytes(ByteSequence bytes, ByteSequence other) {
        if (bytes == null || bytes.length() != other.length()) {
            return false;
        } else {
            // trusted class
            return bytes.equals(other);
        }
    }

    private static boolean compareCharacters(CharSequence characters, CharSequence other) {
        if (characters == null || characters.length() != other.length()) {
            return false;
        } else {
            return Objects.equals(characters.toString(), other.toString());
        }
    }

    SourceImpl toSourceInterned() {
        assert cached;
        return new SourceImpl(this);
    }

    SourceImpl toSourceNotInterned() {
        assert !cached;
        return new SourceImpl(this, this);
    }

}

