public static class OutgoingMessage implements Serializable {
  /** Underlying (encoded) element. */
  public final byte[] elementBytes;

  public final Map<String, String> attributes;

  /** Timestamp for element (ms since epoch). */
  public final long timestampMsSinceEpoch;

  /**
   * If using an id attribute, the record id to associate with this record's metadata so the
   * receiver can reject duplicates. Otherwise {@literal null}.
   */
  @Nullable public final String recordId;

  public OutgoingMessage(
      byte[] elementBytes,
      Map<String, String> attributes,
      long timestampMsSinceEpoch,
      @Nullable String recordId) {
    this.elementBytes = elementBytes;
    this.attributes = attributes;
    this.timestampMsSinceEpoch = timestampMsSinceEpoch;
    this.recordId = recordId;
  }

  @Override
  public String toString() {
    return String.format(
        "OutgoingMessage(%db, %dms)", elementBytes.length, timestampMsSinceEpoch);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    OutgoingMessage that = (OutgoingMessage) o;

    return timestampMsSinceEpoch == that.timestampMsSinceEpoch
        && Arrays.equals(elementBytes, that.elementBytes)
        && Objects.equal(attributes, that.attributes)
        && Objects.equal(recordId, that.recordId);
  }

  @Override
  public int hashCode() {
    return Objects.hashCode(
        Arrays.hashCode(elementBytes), attributes, timestampMsSinceEpoch, recordId);
  }
}

public class ActionNamesAction extends ActionSupport {

    private static final long serialVersionUID = -5389385242431387840L;

    private Set<String> actionNames;
    private String namespace = "";
    private Set<String> namespaces;
    private String extension;

    protected ConfigurationHelper configHelper;

    @Inject
    public void setConfigurationHelper(ConfigurationHelper cfg) {
        this.configHelper = cfg;
    }

    public Set<String> getActionNames() {
        return actionNames;
    }

    public String getNamespace() {
        return StringEscapeUtils.escapeHtml4(namespace);
    }

    public void setNamespace(String namespace) {
        this.namespace = namespace;
    }

    @Inject(StrutsConstants.STRUTS_ACTION_EXTENSION)
    public void setExtension(String ext) {
        this.extension = ext;
    }

    public ActionConfig getConfig(String actionName) {
        return configHelper.getActionConfig(namespace, actionName);
    }

    public Set<String> getNamespaces() {
        return namespaces;
    }

    public String getExtension() {
        if (extension == null) {
            return "action";
        }
        if (extension.contains(",")) {
            return extension.substring(0, extension.indexOf(","));
        }
        return extension;
    }

    public String execute() throws Exception {
        namespaces = configHelper.getNamespaces();
        if (namespaces.size() == 0) {
            addActionError("There are no namespaces in this configuration");
            return ERROR;
        }
        if (namespace == null) {
            namespace = "";
        }
        actionNames = new TreeSet<String>(configHelper.getActionNames(namespace));
        return SUCCESS;
    }

    /**
     * Index action to support cooperation with REST plugin
     *
     * @return action result
     * @throws Exception
     */
    public String index() throws Exception {
        return execute();
    }

    public String redirect() {
        return SUCCESS;
    }

}

