public abstract class AbstractPreferencePropertyMonitor implements IPropertyChangeListener {

    private List<PreferencePropertyChangeListener> listeners = new CopyOnWriteArrayList<>();

    private final long notificationDelay;
    private NotifyListenersJob job = null;

    /**
     * Create a preference monitor with the given notification delay
     * 
     * @param notificationDelay
     *            If it's a positive value, then all notifications on the
     *            registered listeners will be executed asynchronously after the
     *            specified delay. Otherwise, the notification happens
     *            synchronously right after change events
     */
    public AbstractPreferencePropertyMonitor(long notificationDelay) {
        this.notificationDelay = notificationDelay;
        if (notificationDelay > 0) {
            job = new NotifyListenersJob();
        }
    }

    /**
     * Override this method to determine whether changes to the given preference
     * key should be watched by this monitor.
     */
    protected abstract boolean watchPreferenceProperty(String preferenceKey);

    public void addChangeListener(PreferencePropertyChangeListener listener) {
        listeners.add(listener);
    }

    public void removeChangeListener(PreferencePropertyChangeListener listener) {
        listeners.remove(listener);
    }

    @Override
    public void propertyChange(PropertyChangeEvent event) {
        String property = event.getProperty();

        if (watchPreferenceProperty(property)) {
            if (job == null) {
                notifyListeners();
            } else {
                job.schedule(notificationDelay);
            }
        }
    }

    private void notifyListeners() {
        for ( PreferencePropertyChangeListener listener : listeners ) {
            try {
                listener.watchedPropertyChanged();
            } catch ( Exception e ) {
                AwsToolkitCore.getDefault().logError(
                        "Couldn't notify listener of preferece property change: " + listener.getClass(), e);
            }
        }
    }

    private final class NotifyListenersJob extends Job {
        private NotifyListenersJob() {
            super("AWS preference property update");
            this.setSystem(true);
        }

        @Override
        protected IStatus run(IProgressMonitor monitor) {
            AbstractPreferencePropertyMonitor.this.notifyListeners();
            return Status.OK_STATUS;
        }
    }
}

public class PolylineConnection extends Polyline implements Connection,
		AnchorListener {

	private ConnectionAnchor startAnchor, endAnchor;
	private ConnectionRouter connectionRouter = ConnectionRouter.NULL;
	private RotatableDecoration startArrow, endArrow;

	{
		setLayoutManager(new DelegatingLayout());
		addPoint(new Point(0, 0));
		addPoint(new Point(100, 100));
	}

	/**
	 * Hooks the source and target anchors.
	 * 
	 * @see Figure#addNotify()
	 */
	public void addNotify() {
		super.addNotify();
		hookSourceAnchor();
		hookTargetAnchor();
	}

	/**
	 * Appends the given routing listener to the list of listeners.
	 * 
	 * @param listener
	 *            the routing listener
	 * @since 3.2
	 */
	public void addRoutingListener(RoutingListener listener) {
		if (connectionRouter instanceof RoutingNotifier) {
			RoutingNotifier notifier = (RoutingNotifier) connectionRouter;
			notifier.listeners.add(listener);
		} else
			connectionRouter = new RoutingNotifier(connectionRouter, listener);
	}

	/**
	 * Called by the anchors of this connection when they have moved,
	 * revalidating this polyline connection.
	 * 
	 * @param anchor
	 *            the anchor that moved
	 */
	public void anchorMoved(ConnectionAnchor anchor) {
		revalidate();
	}

	/**
	 * Returns the bounds which holds all the points in this polyline
	 * connection. Returns any previously existing bounds, else calculates by
	 * unioning all the children's dimensions.
	 * 
	 * @return the bounds
	 */
	public Rectangle getBounds() {
		if (bounds == null) {
			super.getBounds();
			for (int i = 0; i < getChildren().size(); i++) {
				IFigure child = (IFigure) getChildren().get(i);
				bounds.union(child.getBounds());
			}
		}
		return bounds;
	}

	/**
	 * Returns the <code>ConnectionRouter</code> used to layout this connection.
	 * Will not return <code>null</code>.
	 * 
	 * @return this connection's router
	 */
	public ConnectionRouter getConnectionRouter() {
		if (connectionRouter instanceof RoutingNotifier)
			return ((RoutingNotifier) connectionRouter).realRouter;
		return connectionRouter;
	}

	/**
	 * Returns this connection's routing constraint from its connection router.
	 * May return <code>null</code>.
	 * 
	 * @return the connection's routing constraint
	 */
	public Object getRoutingConstraint() {
		if (getConnectionRouter() != null)
			return getConnectionRouter().getConstraint(this);
		else
			return null;
	}

	/**
	 * @return the anchor at the start of this polyline connection (may be null)
	 */
	public ConnectionAnchor getSourceAnchor() {
		return startAnchor;
	}

	/**
	 * @return the source decoration (may be null)
	 */
	protected RotatableDecoration getSourceDecoration() {
		return startArrow;
	}

	/**
	 * @return the anchor at the end of this polyline connection (may be null)
	 */
	public ConnectionAnchor getTargetAnchor() {
		return endAnchor;
	}

	/**
	 * @return the target decoration (may be null)
	 * 
	 * @since 2.0
	 */
	protected RotatableDecoration getTargetDecoration() {
		return endArrow;
	}

	private void hookSourceAnchor() {
		if (getSourceAnchor() != null)
			getSourceAnchor().addAnchorListener(this);
	}

	private void hookTargetAnchor() {
		if (getTargetAnchor() != null)
			getTargetAnchor().addAnchorListener(this);
	}

	/**
	 * Layouts this polyline. If the start and end anchors are present, the
	 * connection router is used to route this, after which it is laid out. It
	 * also fires a moved method.
	 */
	public void layout() {
		if (getSourceAnchor() != null && getTargetAnchor() != null)
			connectionRouter.route(this);

		Rectangle oldBounds = bounds;
		super.layout();
		bounds = null;

		if (!getBounds().contains(oldBounds)) {
			getParent().translateToParent(oldBounds);
			getUpdateManager().addDirtyRegion(getParent(), oldBounds);
		}

		repaint();
		fireFigureMoved();
	}

	/**
	 * Called just before the receiver is being removed from its parent. Results
	 * in removing itself from the connection router.
	 * 
	 * @since 2.0
	 */
	public void removeNotify() {
		unhookSourceAnchor();
		unhookTargetAnchor();
		connectionRouter.remove(this);
		super.removeNotify();
	}

	/**
	 * Removes the first occurence of the given listener.
	 * 
	 * @param listener
	 *            the listener being removed
	 * @since 3.2
	 */
	public void removeRoutingListener(RoutingListener listener) {
		if (connectionRouter instanceof RoutingNotifier) {
			RoutingNotifier notifier = (RoutingNotifier) connectionRouter;
			notifier.listeners.remove(listener);
			if (notifier.listeners.isEmpty())
				connectionRouter = notifier.realRouter;
		}
	}

	/**
	 * @see IFigure#revalidate()
	 */
	public void revalidate() {
		super.revalidate();
		connectionRouter.invalidate(this);
	}

	/**
	 * Sets the connection router which handles the layout of this polyline.
	 * Generally set by the parent handling the polyline connection.
	 * 
	 * @param cr
	 *            the connection router
	 */
	public void setConnectionRouter(ConnectionRouter cr) {
		if (cr == null)
			cr = ConnectionRouter.NULL;
		ConnectionRouter oldRouter = getConnectionRouter();
		if (oldRouter != cr) {
			connectionRouter.remove(this);
			if (connectionRouter instanceof RoutingNotifier)
				((RoutingNotifier) connectionRouter).realRouter = cr;
			else
				connectionRouter = cr;
			firePropertyChange(Connection.PROPERTY_CONNECTION_ROUTER,
					oldRouter, cr);
			revalidate();
		}
	}

	/**
	 * Sets the routing constraint for this connection.
	 * 
	 * @param cons
	 *            the constraint
	 */
	public void setRoutingConstraint(Object cons) {
		if (connectionRouter != null)
			connectionRouter.setConstraint(this, cons);
		revalidate();
	}

	/**
	 * Sets the anchor to be used at the start of this polyline connection.
	 * 
	 * @param anchor
	 *            the new source anchor
	 */
	public void setSourceAnchor(ConnectionAnchor anchor) {
		if (anchor == startAnchor)
			return;
		unhookSourceAnchor();
		// No longer needed, revalidate does this.
		// getConnectionRouter().invalidate(this);
		startAnchor = anchor;
		if (getParent() != null)
			hookSourceAnchor();
		revalidate();
	}

	/**
	 * Sets the decoration to be used at the start of the {@link Connection}.
	 * 
	 * @param dec
	 *            the new source decoration
	 * @since 2.0
	 */
	public void setSourceDecoration(RotatableDecoration dec) {
		if (startArrow == dec)
			return;
		if (startArrow != null)
			remove(startArrow);
		startArrow = dec;
		if (startArrow != null)
			add(startArrow, new ArrowLocator(this, ConnectionLocator.SOURCE));
	}

	/**
	 * Sets the anchor to be used at the end of the polyline connection. Removes
	 * this listener from the old anchor and adds it to the new anchor.
	 * 
	 * @param anchor
	 *            the new target anchor
	 */
	public void setTargetAnchor(ConnectionAnchor anchor) {
		if (anchor == endAnchor)
			return;
		unhookTargetAnchor();
		// No longer needed, revalidate does this.
		// getConnectionRouter().invalidate(this);
		endAnchor = anchor;
		if (getParent() != null)
			hookTargetAnchor();
		revalidate();
	}

	/**
	 * Sets the decoration to be used at the end of the {@link Connection}.
	 * 
	 * @param dec
	 *            the new target decoration
	 */
	public void setTargetDecoration(RotatableDecoration dec) {
		if (endArrow == dec)
			return;
		if (endArrow != null)
			remove(endArrow);
		endArrow = dec;
		if (endArrow != null)
			add(endArrow, new ArrowLocator(this, ConnectionLocator.TARGET));
	}

	private void unhookSourceAnchor() {
		if (getSourceAnchor() != null)
			getSourceAnchor().removeAnchorListener(this);
	}

	private void unhookTargetAnchor() {
		if (getTargetAnchor() != null)
			getTargetAnchor().removeAnchorListener(this);
	}

	final class RoutingNotifier implements ConnectionRouter {

		ConnectionRouter realRouter;
		List listeners = new ArrayList(1);

		RoutingNotifier(ConnectionRouter router, RoutingListener listener) {
			realRouter = router;
			listeners.add(listener);
		}

		public Object getConstraint(Connection connection) {
			return realRouter.getConstraint(connection);
		}

		public void invalidate(Connection connection) {
			for (int i = 0; i < listeners.size(); i++)
				((RoutingListener) listeners.get(i)).invalidate(connection);

			realRouter.invalidate(connection);
		}

		public void route(Connection connection) {
			boolean consumed = false;
			for (int i = 0; i < listeners.size(); i++)
				consumed |= ((RoutingListener) listeners.get(i))
						.route(connection);

			if (!consumed)
				realRouter.route(connection);

			for (int i = 0; i < listeners.size(); i++)
				((RoutingListener) listeners.get(i)).postRoute(connection);
		}

		public void remove(Connection connection) {
			for (int i = 0; i < listeners.size(); i++)
				((RoutingListener) listeners.get(i)).remove(connection);
			realRouter.remove(connection);
		}

		public void setConstraint(Connection connection, Object constraint) {
			for (int i = 0; i < listeners.size(); i++)
				((RoutingListener) listeners.get(i)).setConstraint(connection,
						constraint);
			realRouter.setConstraint(connection, constraint);
		}

	}

}

final class SearchFirstStringNode extends Node {

    private static final int[] UNINTIALIZED_CACHED_INDICES = new int[0];

    private final VectorLengthProfile targetLengthProfile = VectorLengthProfile.create();
    private final VectorLengthProfile elementsLengthProfile = VectorLengthProfile.create();
    private final ValueProfile targetClassProfile = ValueProfile.createClassProfile();
    private final ValueProfile elementsClassProfile = ValueProfile.createClassProfile();

    @Child private StringEqualsNode stringEquals = CompareStringNode.createEquals();
    @Child private CompareStringNode stringStartsWith;
    @Child private StringEqualsNode equalsDuplicate;

    private final NACheck elementsNACheck = NACheck.create();
    private final NACheck targetNACheck = NACheck.create();
    private final BranchProfile everFoundDuplicate = BranchProfile.create();
    private final BranchProfile seenInvalid = BranchProfile.create();

    /** Instead of using the notFoundStartIndex we use NA. */
    private final boolean useNAForNotFound;
    private final boolean exactMatch;

    @CompilationFinal(dimensions = 1) private int[] cachedIndices;

    private SearchFirstStringNode(boolean exactMatch, boolean useNAForNotFound) {
        this.exactMatch = exactMatch;
        this.useNAForNotFound = useNAForNotFound;
        if (!exactMatch) {
            stringStartsWith = CompareStringNode.createStartsWith();
        }
    }

    public RAbstractIntVector apply(RAbstractStringVector target, RAbstractStringVector elements, int notFoundStartIndex, RStringVector names) {
        RAbstractStringVector targetProfiled = targetClassProfile.profile(target);
        RAbstractStringVector elementsProfiled = elementsClassProfile.profile(elements);

        int targetLength = targetLengthProfile.profile(targetProfiled.getLength());
        int elementsLength = elementsLengthProfile.profile(elementsProfiled.getLength());

        targetNACheck.enable(target);
        elementsNACheck.enable(elements);

        if (cachedIndices == UNINTIALIZED_CACHED_INDICES) {
            CompilerDirectives.transferToInterpreterAndInvalidate();
            cachedIndices = searchCached(targetProfiled, targetLength, elementsProfiled, elementsLength, names);
        }
        if (cachedIndices != null) {
            if (!isCacheValid(targetProfiled, targetLength, elementsProfiled, elementsLength, cachedIndices)) {
                CompilerDirectives.transferToInterpreterAndInvalidate();
                cachedIndices = null; // set to generic
                // fallthrough to generic
            } else {
                assert sameVector(searchCached(target, targetLength, elements, elementsLength, names), cachedIndices);
                return RDataFactory.createIntVector(cachedIndices, true, names);
            }
        }

        return searchGeneric(targetProfiled, targetLength, elementsProfiled, elementsLength, notFoundStartIndex, false, names);
    }

    public static SearchFirstStringNode createNode(boolean exactMatch, boolean useNAForNotFound) {
        return new SearchFirstStringNode(exactMatch, useNAForNotFound);
    }

    private int[] searchCached(RAbstractStringVector target, int targetLength, RAbstractStringVector elements, int elementsLength, RStringVector names) {
        if (exactMatch) {
            RAbstractIntVector genericResult = searchGeneric(target, targetLength, elements, elementsLength, -1, true, names);
            if (genericResult != null) {
                return genericResult.materialize().getReadonlyData();
            }
        }
        return null;
    }

    private boolean isCacheValid(RAbstractStringVector target, int targetLength,
                    RAbstractStringVector elements, int elementsLength, int[] cached) {
        int cachedLength = cached.length;
        if (elementsLength != cachedLength) {
            seenInvalid.enter();
            return false;
        }

        for (int i = 0; i < cachedLength; i++) {
            int cachedIndex = cached[i];
            String cachedElement = elements.getDataAt(i);
            int cachedElementHash = cachedElement.hashCode();

            assert !elementsNACheck.check(cachedElement) && cachedElement.length() > 0;

            int cachedTranslatedIndex = cachedIndex - 1;
            for (int j = 0; j < cachedTranslatedIndex; j++) {
                String targetString = target.getDataAt(j);
                if (!targetNACheck.check(targetString) && stringEquals.executeCompare(cachedElement, cachedElementHash, targetString)) {
                    seenInvalid.enter();
                    return false;
                }
            }
            if (cachedTranslatedIndex < targetLength) {
                String targetString = target.getDataAt(cachedTranslatedIndex);
                if (!targetNACheck.check(targetString) && !stringEquals.executeCompare(cachedElement, cachedElementHash, targetString)) {
                    seenInvalid.enter();
                    return false;
                }
            } else {
                seenInvalid.enter();
                return false;
            }
        }
        return true;

    }

    private static boolean sameVector(int[] a, int[] b) {
        if (a == null) {
            return false;
        }
        if (a.length != b.length) {
            return false;
        }

        for (int i = 0; i < a.length; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    }

    private final BranchProfile notFoundProfile = BranchProfile.create();
    private final ConditionProfile hashingProfile = ConditionProfile.createBinaryProfile();

    private RAbstractIntVector searchGeneric(RAbstractStringVector target, int targetLength, RAbstractStringVector elements, int elementsLength, int notFoundStartIndex, boolean nullOnNotFound,
                    RStringVector names) {
        int[] indices = new int[elementsLength];
        boolean resultComplete = true;

        long hashingCost = targetLength * 10L + 10 /* constant overhead */;
        long lookupCost = elementsLength * 2L;
        long nestedLoopCost = targetLength * (long) elementsLength;
        NonRecursiveHashMapCharacter map;
        if (hashingProfile.profile(nestedLoopCost > hashingCost + lookupCost)) {
            map = new NonRecursiveHashMapCharacter(targetLength);
            for (int i = 0; i < targetLength; i++) {
                String name = target.getDataAt(i);
                if (!targetNACheck.check(name)) {
                    map.put(name, i);
                }
            }
        } else {
            map = null;
        }
        int notFoundIndex = notFoundStartIndex;
        for (int i = 0; i < elementsLength; i++) {
            String element = elements.getDataAt(i);
            boolean isElementNA = elementsNACheck.check(element) || element.length() == 0;
            if (!isElementNA) {
                int index;
                if (map != null) {
                    index = map.get(element);
                    if (!exactMatch && index < 0) {
                        // the map is only good for exact matches
                        index = findNonExactIndex(target, targetLength, element);
                    }
                } else {
                    index = findIndex(target, targetLength, element);
                }
                if (index >= 0) {
                    indices[i] = index + 1;
                    continue;
                }
            }
            notFoundProfile.enter();
            if (nullOnNotFound) {
                return null;
            } else {
                int prevDuplicateIndex = -1;
                if (!isElementNA) {
                    prevDuplicateIndex = findFirstDuplicate(elements, element, i);
                }
                int nextIndex;
                if (prevDuplicateIndex == -1) {
                    if (useNAForNotFound) {
                        resultComplete = false;
                        nextIndex = RRuntime.INT_NA;
                    } else {
                        nextIndex = ++notFoundIndex;
                    }
                } else {
                    nextIndex = indices[prevDuplicateIndex];
                }
                indices[i] = nextIndex;
            }
        }
        return RDataFactory.createIntVector(indices, resultComplete && elements.isComplete(), names);
    }

    private int findNonExactIndex(RAbstractStringVector target, int targetLength, String element) {
        assert !exactMatch;
        int nonExactIndex = -1;
        for (int j = 0; j < targetLength; j++) {
            String targetValue = target.getDataAt(j);
            if (!targetNACheck.check(targetValue)) {
                if (stringStartsWith.executeCompare(targetValue, element)) {
                    if (nonExactIndex == -1) {
                        nonExactIndex = j;
                    } else {
                        return -1;
                    }
                }
            }
        }
        return nonExactIndex;
    }

    private int findIndex(RAbstractStringVector target, int targetLength, String element) {
        int nonExactIndex = -1;
        int elementHash = element.hashCode();
        for (int j = 0; j < targetLength; j++) {
            String targetValue = target.getDataAt(j);
            if (!targetNACheck.check(targetValue)) {
                if (stringEquals.executeCompare(element, elementHash, targetValue)) {
                    return j;
                }
                if (!exactMatch) {
                    if (stringStartsWith.executeCompare(targetValue, element)) {
                        if (nonExactIndex == -1) {
                            nonExactIndex = j;
                        } else {
                            nonExactIndex = -2;
                        }
                    }
                }
            }
        }
        return nonExactIndex;
    }

    private int findFirstDuplicate(RAbstractStringVector elements, String element, int currentIndex) {
        if (equalsDuplicate == null) {
            CompilerDirectives.transferToInterpreterAndInvalidate();
            equalsDuplicate = insert(CompareStringNode.createEquals());
        }

        int elementHash = element.hashCode();
        for (int j = 0; j < currentIndex; j++) {
            String otherElement = elements.getDataAt(j);
            if (!targetNACheck.check(otherElement) && equalsDuplicate.executeCompare(element, elementHash, otherElement)) {
                everFoundDuplicate.enter();
                return j;
            }
        }
        return -1;
    }

    abstract static class CompareStringNode extends Node {

        public abstract boolean executeCompare(String a, String b);

        public static StringEqualsNode createEquals() {
            return new StringEqualsNode();
        }

        public static StringStartsWithNode createStartsWith() {
            return new StringStartsWithNode();
        }

        public static class StringEqualsNode extends CompareStringNode {

            private final ConditionProfile identityEquals = ConditionProfile.createBinaryProfile();
            private final ConditionProfile hashEquals = ConditionProfile.createBinaryProfile();

            @Override
            public final boolean executeCompare(String a, String b) {
                assert !RRuntime.isNA(a);
                assert !RRuntime.isNA(b);
                if (identityEquals.profile(Utils.fastPathIdentityEquals(a, b))) {
                    return true;
                } else {
                    if (hashEquals.profile(a.hashCode() != b.hashCode())) {
                        return false;
                    }
                    return a.equals(b);
                }
            }

            public final boolean executeCompare(String a, int aHash, String b) {
                assert !RRuntime.isNA(a);
                assert !RRuntime.isNA(b);
                if (identityEquals.profile(Utils.fastPathIdentityEquals(a, b))) {
                    return true;
                } else {
                    if (hashEquals.profile(aHash != b.hashCode())) {
                        return false;
                    }
                    return a.equals(b);
                }
            }
        }

        private static class StringStartsWithNode extends CompareStringNode {

            private final ConditionProfile identityEquals = ConditionProfile.createBinaryProfile();

            @Override
            public final boolean executeCompare(String a, String b) {
                assert !RRuntime.isNA(a);
                assert !RRuntime.isNA(b);
                if (identityEquals.profile(Utils.fastPathIdentityEquals(a, b))) {
                    return true;
                } else {
                    return a.startsWith(b);
                }
            }
        }
    }
}

public abstract class Event<L> {

    private List<L> listener;
    private boolean fireEvents;
    private boolean eventWasFired;

    public Event() {
        listener = new ArrayList<>();
        fireEvents = true;
    }

    public void addListener(L l) {
        listener.add(l);
    }

    /**
     * Remove listener
     * @param l
     */
    public void removeListener(final L l) {
        listener.remove(l);
    }

    public void fire() {
        if(fireEvents) {
            List<L> tmpList = new ArrayList<>(listener);
            for (L l : tmpList) {
                fire(l);
            }
        } else {
            eventWasFired = true;
        }
    }

    public void beginAtomic() {
        assert fireEvents : "endAtomic has to be called before another beginAtomic may be called";
        this.fireEvents = false;
        this.eventWasFired = false;
    }

    public void endAtomic() {
        assert !fireEvents : "beginAtomic has to be called first";
        this.fireEvents = true;
        if(eventWasFired) {
            fire();
        }
    }

    protected abstract void fire(L l);
}

