public class JobExecutionInfoResource extends ComplexKeyResourceTemplate<JobExecutionQuery, EmptyRecord, JobExecutionQueryResult> {

  private static final Logger LOGGER = LoggerFactory.getLogger(JobExecutionInfoResource.class);

  @Inject
  @Named("jobHistoryStore")
  private JobHistoryStore jobHistoryStore;

  @Override
  public JobExecutionQueryResult get(ComplexResourceKey<JobExecutionQuery, EmptyRecord> key) {
    JobExecutionQuery query = key.getKey();

    JobExecutionInfoArray jobExecutionInfos = new JobExecutionInfoArray();
    try {
      for (JobExecutionInfo jobExecutionInfo : this.jobHistoryStore.get(query)) {
        jobExecutionInfos.add(jobExecutionInfo);
      }
    } catch (Throwable t) {
      LOGGER
          .error(String.format("Failed to execute query [id = %s, type = %s]", query.getId(), query.getIdType().name()),
              t);
      return null;
    }

    JobExecutionQueryResult result = new JobExecutionQueryResult();
    result.setJobExecutions(jobExecutionInfos);
    ResourceContext rc = this.getContext();
    rc.setResponseHeader("Access-Control-Allow-Origin", "*");
    this.setContext(rc);

    return result;
  }

  @Override
  public Map<ComplexResourceKey<JobExecutionQuery, EmptyRecord>, JobExecutionQueryResult> batchGet(
      Set<ComplexResourceKey<JobExecutionQuery, EmptyRecord>> keys) {

    Map<ComplexResourceKey<JobExecutionQuery, EmptyRecord>, JobExecutionQueryResult> results = Maps.newHashMap();
    for (ComplexResourceKey<JobExecutionQuery, EmptyRecord> key : keys) {
      JobExecutionQueryResult result = get(key);
      if (result != null) {
        results.put(key, get(key));
      }
    }
    ResourceContext rc = this.getContext();
    rc.setResponseHeader("Access-Control-Allow-Origin", "*");
    this.setContext(rc);

    return results;
  }
}

private static DimFilter negate(final DimFilter filter)
{
  if (Filtration.matchEverything().equals(filter)) {
    return Filtration.matchNothing();
  } else if (Filtration.matchNothing().equals(filter)) {
    return Filtration.matchEverything();
  } else if (filter instanceof NotDimFilter) {
    return ((NotDimFilter) filter).getField();
  } else if (filter instanceof BoundDimFilter) {
    final BoundDimFilter negated = Bounds.not((BoundDimFilter) filter);
    return negated != null ? negated : new NotDimFilter(filter);
  } else {
    return new NotDimFilter(filter);
  }
}

public class ContentProviderController<T extends ContentProvider>  {
  private T contentProvider;

  private ContentProviderController(T contentProvider) {
    this.contentProvider = contentProvider;
  }

  public static <T extends ContentProvider> ContentProviderController<T> of(T contentProvider) {
    return new ContentProviderController<>(contentProvider);
  }

  /**
   * Create and register {@link ContentProvider} using {@link ProviderInfo} found from manifest.
   */
  public ContentProviderController<T> create() {
    Context baseContext = RuntimeEnvironment.application.getBaseContext();

    ComponentName componentName = createRelative(baseContext.getPackageName(), contentProvider.getClass().getName());

    ProviderInfo providerInfo = null;
    try {
      providerInfo =
          baseContext
              .getPackageManager()
              .getProviderInfo(componentName, PackageManager.MATCH_DISABLED_COMPONENTS);
    } catch (PackageManager.NameNotFoundException e) {
      Logger.strict("Unable to find provider info for " + componentName, e);
    }

    return create(providerInfo);
  }

  /**
   * Create and register {@link ContentProvider} using {@link ProviderInfo} found from manifest.
   *
   * @param authority the authority to use
   * @return this {@link ContentProviderController}
   */
  public ContentProviderController<T> create(String authority) {
    ProviderInfo providerInfo = new ProviderInfo();
    providerInfo.authority = authority;
    return create(providerInfo);
  }

  /**
   * Create and register {@link ContentProvider} using the given {@link ProviderInfo}.
   *
   * @param providerInfo the {@link ProviderInfo} to use
   * @return this {@link ContentProviderController}
   */
  public ContentProviderController<T> create(ProviderInfo providerInfo) {
    Context baseContext = RuntimeEnvironment.application.getBaseContext();
    // make sure the component is enabled
    ComponentName componentName =
        createRelative(baseContext.getPackageName(), contentProvider.getClass().getName());
    baseContext
        .getPackageManager()
        .setComponentEnabledSetting(
            componentName, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, 0);
    contentProvider.attachInfo(baseContext, providerInfo);

    if (providerInfo != null) {
      ShadowContentResolver.registerProviderInternal(providerInfo.authority, contentProvider);
    }

    return this;
  }

  public T get() {
    return contentProvider;
  }

  public ContentProviderController<T> shutdown() {
    contentProvider.shutdown();
    return this;
  }

  private static ComponentName createRelative(String pkg, String cls) {
    final String fullName;
    if (cls.charAt(0) == '.') {
      // Relative to the package. Prepend the package name.
      fullName = pkg + cls;
    } else {
      // Fully qualified package name.
      fullName = cls;
    }
    return new ComponentName(pkg, fullName);
  }
}

