@Configuration
@Conditional(JwtKeyStoreCondition.class)
protected class JwtKeyStoreConfiguration implements ApplicationContextAware {

	private final AuthorizationServerProperties authorization;

	private ApplicationContext context;

	@Autowired
	public JwtKeyStoreConfiguration(AuthorizationServerProperties authorization) {
		this.authorization = authorization;
	}

	@Override
	public void setApplicationContext(ApplicationContext context)
			throws BeansException {
		this.context = context;
	}

	@Bean
	@ConditionalOnMissingBean(AuthorizationServerTokenServices.class)
	public DefaultTokenServices jwtTokenServices(TokenStore jwtTokenStore) {
		DefaultTokenServices services = new DefaultTokenServices();
		services.setTokenStore(jwtTokenStore);
		return services;
	}

	@Bean
	@ConditionalOnMissingBean(TokenStore.class)
	public TokenStore tokenStore() {
		return new JwtTokenStore(accessTokenConverter());
	}

	@Bean
	public JwtAccessTokenConverter accessTokenConverter() {
		Assert.notNull(this.authorization.getJwt().getKeyStore(),
				"keyStore cannot be null");
		Assert.notNull(this.authorization.getJwt().getKeyStorePassword(),
				"keyStorePassword cannot be null");
		Assert.notNull(this.authorization.getJwt().getKeyAlias(),
				"keyAlias cannot be null");

		JwtAccessTokenConverter converter = new JwtAccessTokenConverter();

		Resource keyStore = this.context
				.getResource(this.authorization.getJwt().getKeyStore());
		char[] keyStorePassword = this.authorization.getJwt().getKeyStorePassword()
				.toCharArray();
		KeyStoreKeyFactory keyStoreKeyFactory = new KeyStoreKeyFactory(keyStore,
				keyStorePassword);

		String keyAlias = this.authorization.getJwt().getKeyAlias();
		char[] keyPassword = Optional
				.ofNullable(this.authorization.getJwt().getKeyPassword())
				.map(String::toCharArray).orElse(keyStorePassword);
		converter.setKeyPair(keyStoreKeyFactory.getKeyPair(keyAlias, keyPassword));

		return converter;
	}

}

protected void sendMessage(Connection cnx) throws Exception {
  if (cnx.getServer().getRequiresCredentials()) {
    // Security is enabled on client as well as on server
    getMessage().setMessageHasSecurePartFlag();
    long userId = -1;

    if (UserAttributes.userAttributes.get() == null) { // single user mode
      userId = cnx.getServer().getUserId();
    } else { // multi user mode
      Object id = UserAttributes.userAttributes.get().getServerToId().get(cnx.getServer());
      if (id == null) {
        // This will ensure that this op is retried on another server, unless
        // the retryCount is exhausted. Fix for Bug 41501
        throw new ServerConnectivityException("Connection error while authenticating user");
      }
      userId = (Long) id;
    }
    HeapDataOutputStream hdos = new HeapDataOutputStream(Version.CURRENT);
    try {
      hdos.writeLong(cnx.getConnectionID());
      hdos.writeLong(userId);
      getMessage().setSecurePart(((ConnectionImpl) cnx).encryptBytes(hdos.toByteArray()));
    } finally {
      hdos.close();
    }
  }
  getMessage().send(false);
}

public class TestRun extends AbstractDotnetTest {

	@Override
	public void setup() throws CoreException {
		super.buildEmptyProject();
		csprojFile = this.project.getFile("Project2.Tests.csproj");
		csprojFile.create(getClass().getResourceAsStream(csprojFile.getName()), true, new NullProgressMonitor());
	}

	@Test
	public void testDotnetRunSuccessful() throws CoreException {
		int exitCode = runTest("ProjectTestsPass.cs");
		assertTrue("Test's exit code was incorrect; expected: 0, actual: " + exitCode, exitCode == 0);
	}

	@Test
	public void testDotnetRunFailure() throws CoreException {
		int exitCode = runTest("ProjectTestsFail.cs");
		assertTrue("Test's exit code was incorrect; expected: 1, actual: " + exitCode, exitCode == 1);
	}

	private int runTest(String csharpSourceFileName) throws CoreException {
		csharpSourceFile = this.project.getFile(csharpSourceFileName);
		csharpSourceFile.create(getClass().getResourceAsStream(csharpSourceFile.getName()), true,
				new NullProgressMonitor());

		SWTBotView view = bot.viewByTitle("Project Explorer");
		List<Tree> explorerControls = new ChildrenControlFinder(view.getWidget())
				.findControls(WidgetOfType.widgetOfType(Tree.class));
		SWTBotTree explorerTree = new SWTBotTree(explorerControls.get(0));
		SWTBotTreeItem projectItem = explorerTree.getTreeItem(project.getName());
		SWTBotTreeItem fileItem = projectItem.expand().getNode(csharpSourceFile.getName());
		fileItem.select().contextMenu("Open").click();
		SWTBotEditor editor = bot.editorByTitle(csharpSourceFile.getName());
		editor.setFocus();
		editor.toTextEditor().contextMenu("Run As").menu("2 .NET Core Test").click();
		SWTBotView debugView = bot.viewByTitle("Debug");
		List<Tree> debugControls = new ChildrenControlFinder(debugView.getWidget())
				.findControls(WidgetOfType.widgetOfType(Tree.class));
		SWTBotTree debugTree = new SWTBotTree(debugControls.get(0));

		bot.waitUntil(new ICondition() {
			@Override
			public boolean test() throws Exception {
				for (SWTBotTreeItem item : debugTree.getAllItems()) {
					for (String node : item.expand().getNodes()) {
						if (node.matches("<terminated, exit value: \\d>dotnet test")) {
							return true;
						}
					}
				}
				return false;
			}

			@Override
			public void init(SWTBot bot) {
				debugView.setFocus();
			}

			@Override
			public String getFailureMessage() {
				SWTBotView consoleView = bot.viewByPartName("Console");
				return "Test program failed: " + consoleView.bot().styledText().getText();
			}
		}, 30000);

		for (SWTBotTreeItem item : debugTree.getAllItems()) {
			for (String node : item.expand().getNodes()) {
				if (node.matches("<terminated, exit value: \\d>dotnet test")) {
					return Integer.parseInt(node.replace("<terminated, exit value: ", "").replace(">dotnet test", ""));
				}
			}
		}
		return -1;
	}
}

