public class GetObject {

    public static void main(String[] args) throws IOException {
        String clientRegion = "*** Client region ***";
        String bucketName = "*** Bucket name ***";
        String key = "*** Object key ***";

        S3Object fullObject = null, objectPortion = null, headerOverrideObject = null;
        try {
            AmazonS3 s3Client = AmazonS3ClientBuilder.standard()
                    .withRegion(clientRegion)
                    .withCredentials(new ProfileCredentialsProvider())
                    .build();

            // Get an object and print its contents.
            System.out.println("Downloading an object");
            fullObject = s3Client.getObject(new GetObjectRequest(bucketName, key));
            System.out.println("Content-Type: " + fullObject.getObjectMetadata().getContentType());
            System.out.println("Content: ");
            displayTextInputStream(fullObject.getObjectContent());

            // Get a range of bytes from an object and print the bytes.
            GetObjectRequest rangeObjectRequest = new GetObjectRequest(bucketName, key)
                                                        .withRange(0,9);
            objectPortion = s3Client.getObject(rangeObjectRequest);
            System.out.println("Printing bytes retrieved.");
            displayTextInputStream(objectPortion.getObjectContent());

            // Get an entire object, overriding the specified response headers, and print the object's content.
            ResponseHeaderOverrides headerOverrides = new ResponseHeaderOverrides()
                                                            .withCacheControl("No-cache")
                                                            .withContentDisposition("attachment; filename=example.txt");
            GetObjectRequest getObjectRequestHeaderOverride = new GetObjectRequest(bucketName, key)
                                                            .withResponseHeaders(headerOverrides);
            headerOverrideObject = s3Client.getObject(getObjectRequestHeaderOverride);
            displayTextInputStream(headerOverrideObject.getObjectContent());
        }
        catch(AmazonServiceException e) {
            // The call was transmitted successfully, but Amazon S3 couldn't process 
            // it, so it returned an error response.
            e.printStackTrace();
        }
        catch(SdkClientException e) {
            // Amazon S3 couldn't be contacted for a response, or the client
            // couldn't parse the response from Amazon S3.
            e.printStackTrace();
        }
        finally {
            // To ensure that the network connection doesn't remain open, close any open input streams.
            if(fullObject != null) {
                fullObject.close();
            }
            if(objectPortion != null) {
                objectPortion.close();
            }
            if(headerOverrideObject != null) {
                headerOverrideObject.close();
            }
        }
    }

    private static void displayTextInputStream(InputStream input) throws IOException {
        // Read the text input stream one line at a time and display each line.
        BufferedReader reader = new BufferedReader(new InputStreamReader(input));
        String line = null;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        System.out.println();
    }
}

private void removeAndReconnect(MapReduceOper mr, MapReduceOper newMR) throws VisitorException {
    List<MapReduceOper> mapperSuccs = getPlan().getSuccessors(mr);
    List<MapReduceOper> mapperPreds = getPlan().getPredecessors(mr);

    // make a copy before removing operator
    ArrayList<MapReduceOper> succsCopy = null;
    ArrayList<MapReduceOper> predsCopy = null;
    if (mapperSuccs != null) {
        succsCopy = new ArrayList<MapReduceOper>(mapperSuccs);
    }
    if (mapperPreds != null) {
        predsCopy = new ArrayList<MapReduceOper>(mapperPreds);
    }
    getPlan().remove(mr);

    // reconnect the mapper's successors
    if (succsCopy != null) {
        for (MapReduceOper succ : succsCopy) {
            try {
                getPlan().connect(newMR, succ);
            } catch (PlanException e) {
                int errCode = 2133;
                String msg = "Internal Error. Unable to connect map plan with successors for optimization.";
                throw new OptimizerException(msg, errCode, PigException.BUG, e);
            }
        }
    }

    // reconnect the mapper's predecessors
    if (predsCopy != null) {
        for (MapReduceOper pred : predsCopy) {
            if (newMR.getOperatorKey().equals(pred.getOperatorKey())) {
                continue;
            }
            try {
                getPlan().connect(pred, newMR);
            } catch (PlanException e) {
                int errCode = 2134;
                String msg = "Internal Error. Unable to connect map plan with predecessors for optimization.";
                throw new OptimizerException(msg, errCode, PigException.BUG, e);
            }
        }
    }

    mergeMROperProperties(mr, newMR);
}

public class AtmosFileDownloadResult extends AtmosResult {

    /**
     * Object payload contained in Exchange
     * In case of a single file Exchange Header is populated with the name of the remote path downloaded
     * In case of a multiple files Exchange Header is populated with the name of the remote paths downloaded
     * In case of a single file Exchange Body is populated with the ByteArrayOutputStream downloaded from atmos.
     * In case of multiple files Exchange Body is populated with a map containing as key the remote path
     * and as value the linked ByteArrayOutputStream
     * @param exchange
     */
    @Override
    public void populateExchange(Exchange exchange) {
        //in case we have only one baos put it directly in body
        Map<String, ByteArrayOutputStream> map = (Map<String, ByteArrayOutputStream>)resultEntries;
        if (map.size() == 1) {
            //set info in exchange
            String pathExtracted = null;
            ByteArrayOutputStream baosExtracted = null;
            for (Map.Entry<String, ByteArrayOutputStream> entry : map.entrySet()) {
                pathExtracted = entry.getKey();
                baosExtracted = entry.getValue();
            }
            exchange.getIn().setHeader(AtmosResultHeader.DOWNLOADED_FILE.name(), pathExtracted);
            exchange.getIn().setBody(baosExtracted);
        } else {
            StringBuffer pathsExtracted = new StringBuffer();
            for (Map.Entry<String, ByteArrayOutputStream> entry : map.entrySet()) {
                pathsExtracted.append(entry.getKey() + "\n");
            }
            exchange.getIn().setHeader(AtmosResultHeader.DOWNLOADED_FILES.name(), pathsExtracted.toString());
            exchange.getIn().setBody(map);
        }
    }
}

private final void writePreInvoke() {
  //The place to go if the listener is null
  Label nullListener = newLabel();
  beginListenerInvocation(nullListener);

  // The listener is on the stack, we need (target, method, args)

  loadLocal(dispatchTarget);
  getStatic(typeBeingWoven, methodStaticFieldName, METHOD_TYPE);
  loadArgArray();

  //invoke it and store the token returned
  invokeInterface(LISTENER_TYPE, PRE_INVOKE_METHOD);
  storeLocal(preInvokeReturnedToken);

  mark(nullListener);
}

void set(final String name, final String desc, final Handle bsm,
        final Object[] bsmArgs) {
    this.type = 'y';
    this.strVal1 = name;
    this.strVal2 = desc;
    this.objVal3 = bsm;
    this.objVals = bsmArgs;

    int hashCode = 'y' + name.hashCode() * desc.hashCode() * bsm.hashCode();
    for (Object bsmArg : bsmArgs) {
        hashCode *= bsmArg.hashCode();
    }
    this.hashCode = 0x7FFFFFFF & hashCode;
}

protected String getHash(T data, String salt) {
  String json = null;
  try {
    json = MAPPER.writeValueAsString(data);
  } catch (JsonProcessingException e) {
    throw new RuntimeException("Error during mapping message to calculate hash", e);
  }
  String generatedPassword = null;
  try {
    MessageDigest md = MessageDigest.getInstance("SHA-512");
    md.update(salt.getBytes("UTF-8"));
    byte[] bytes = md.digest(json.getBytes("UTF-8"));
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
      sb.append(Integer.toString((b & 0xff) + 0x100, 16).substring(1));
    }
    generatedPassword = sb.toString();
  } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
    e.printStackTrace();
  }
  return generatedPassword;
}

