public class PortletModeDropDownTag extends BodyTagSupport {

	private static final long serialVersionUID = 1L;


	/** Logger. */
    private static final Logger LOG = LoggerFactory.getLogger(PortletModeDropDownTag.class);


    // Private Member Variables ------------------------------------------------
    private String portletMode = null;

    /** The portlet ID attribute obtained from parent tag. */
    private String portletId = null;

    /** The evaluated value of the portlet ID attribute. */
    private String evaluatedPortletId = null;       

    // BodyTagSupport Impl -----------------------------------------------------

    /**
     * Method invoked when the start tag is encountered.
     * @throws JspException  if an error occurs.
     */
    @SuppressWarnings("deprecation")
   public int doStartTag() throws JspException {

        // Ensure that the modeAnchor tag resides within a portlet tag.
        PortletTag parentTag = (PortletTag) TagSupport.findAncestorWithClass(
                this, PortletTag.class);
        if (parentTag == null) {
            throw new JspException("Portlet window controls may only reside "
                    + "within a pluto:portlet tag.");
        }

        portletId = parentTag.getPortletId();        
        // Evaluate portlet ID attribute.
        evaluatePortletId();

        // Retrieve the portlet window config for the evaluated portlet ID.
        ServletContext servletContext = pageContext.getServletContext();
        DriverConfiguration driverConfig = (DriverConfiguration)
                servletContext.getAttribute(AttributeKeys.DRIVER_CONFIG);

        // Retrieve the portal environment.
        PortalRequestContext portalEnv = PortalRequestContext.getContext(
                (HttpServletRequest) pageContext.getRequest());        

        //find the current mode for use in 'selected' attrib of select option
		PortalURL requestedPortalUrl = portalEnv.getRequestedPortalURL();
        PortletWindowConfig windowConfig =
            PortletWindowConfig.fromId(evaluatedPortletId);
        // Retrieve the portlet container from servlet context.
        PortletContainer container = (PortletContainer)
                servletContext.getAttribute(AttributeKeys.PORTLET_CONTAINER);

        // Create the portlet window to render.
        PortletWindow window = null;


        try
        {
        	// If this fails it means that the portlet will be not available.
        	// Render Tag will take care of it.
        	window = new PortletWindowImpl(container, windowConfig, requestedPortalUrl);
        }
        catch(RuntimeException ex) 
        {
        	  if (LOG.isDebugEnabled()) {
                  LOG.debug("The portlet " + windowConfig.getPortletName() + " is not available. Is already deployed?");
              }
        }

        //start the markup
        StringBuffer tag = new StringBuffer();

        // Do not render if we don't have a window.
        if(window!=null)
        {
        	PortletMode currentMode = requestedPortalUrl.getPortletMode(window.getId().getStringId());


        	//        String strCurrentMode = currentMode.toString();        
        	//        tag.append("Current mode: " + currentMode.toString());
        	tag.append("<form action=\"\" name=\"modeSelectionForm\" style=\"display:inline\"><select onchange=\"self.location=this.options[this.selectedIndex].value\">");
        	Set<PortletMode> modeSet = null;
        	try {
        		modeSet = driverConfig.getSupportedPortletModes(evaluatedPortletId);
        	} catch (PortletContainerException e) {
        		throw new JspException(e);
        	}

        	if (modeSet != null) {
        		Iterator<PortletMode> i = modeSet.iterator();
        		while (i.hasNext()) {
        			PortletMode mode = i.next();

        			PortalURL portalUrl =  requestedPortalUrl.clone();
        			portalUrl.setPortletMode(evaluatedPortletId, mode);

        			// Build a string buffer containing the anchor tag
        			tag.append("<option value=\"" + portalUrl.toString() + "\"");
        			//Add 'selected' attribute for current mode.
        			if (mode.equals(currentMode)) {
        				tag.append(" selected=\"true\"");
        			}
        			tag.append(">");
        			if (driverConfig.isPortletManagedMode(evaluatedPortletId, mode.toString())) {
        				tag.append(getCustomModeDecorationName(driverConfig, mode));	            	
        			} else {
        				tag.append(mode.toString().toUpperCase());
        			}
        			//	            tag.append(mode.toString().toUpperCase());
        			tag.append("</option>");
        		}
        	}
        	tag.append("</select></form>");

        }

        // Print the mode anchor tag.
        try {
            JspWriter out = pageContext.getOut();
            out.print(tag.toString());
        } catch (IOException ex) {
            throw new JspException(ex);
        }

        // Continue to evaluate the tag body.
        return EVAL_BODY_INCLUDE;
    }

    // Package Methods ---------------------------------------------------------

    /**
     * Returns the evaluated portlet ID.
     * @return the evaluated portlet ID.
     */
    String getEvaluatedPortletId() {
        return evaluatedPortletId;
    }



    // Private Methods ---------------------------------------------------------

    /**
     * Evaluates the portlet ID attribute passed into this tag. This method
     * evaluates the member variable <code>portletId</code> and saves the
     * evaluated result to <code>evaluatedPortletId</code>
     * @throws JspException  if an error occurs.
     */
    private void evaluatePortletId() throws JspException {
        Object obj = ExpressionEvaluatorManager.evaluate(
                "portletId", portletId, String.class, this, pageContext);
        if (LOG.isDebugEnabled()) {
            LOG.debug("Evaluated portletId to: " + obj);
        }
        evaluatedPortletId = (String) obj;
    }

    /**
     * @return the portletMode
     */
    public String getPortletMode() {
        return portletMode;
    }

    /**
     * @param portletMode the portletMode to set
     */
    public void setPortletMode(String portletMode) {
        this.portletMode = portletMode;
    }

    /**
     * Obtains decoration name for a portlet managed mode from the portlet's resource bundle
     * as defined in PLT.8.4 of the JSR-286 spec using the key 
     * javax.portlet.app.custom-portlet-mode.<custom mode>.decoration-name where
     * custom mode is the name of the custom mode as defined in portlet.xml
     * (//portlet-app/custom-portlet-mode/portlet-mode element). If the decoration
     * name is not found in the resource bundle, this method returns the uppercased
     * mode name.
     * 
     * @param driverConfig the driver config object found in the session.
     * @param mode the portlet managed custom mode that will be searched for decoration name
     * in the resource bundle.
     * @return the decoration name for a portlet managed mode in the resource bundle
     * using the key javax.portlet.app.custom-portlet-mode.<custom mode>.decoration-name 
     * where custom mode is the name of the custom mode as defined in portlet.xml
     * (//portlet-app/custom-portlet-mode/portlet-mode element). If the decoration
     * name is not found in the resource bundle, the uppercased
     * mode name is returned.
     */
    private String getCustomModeDecorationName(DriverConfiguration driverConfig, 
    		PortletMode mode) {
    	//decoration name is mode name by default
		String decorationName = mode.toString().toUpperCase();
		ResourceBundle bundle;
		StringBuffer res;
		try {
			PortletConfig config = driverConfig.getPortletConfig(evaluatedPortletId);
			ServletRequest request = pageContext.getRequest();
			Locale defaultLocale = request.getLocale();
			bundle = config.getResourceBundle(defaultLocale);
			res = new StringBuffer();
			res.append("javax.portlet.app.custom-portlet-mode.");
			res.append(mode.toString());
			res.append(".decoration-name");
			decorationName = bundle.getString(res.toString());
		} catch (Exception e) {
			LOG.debug("Problem finding decoration-name for custom mode: " + mode.toString());
		}
		return decorationName;
    }

}

public final class InnerClasses {
  private final TypeInfo outer;
  private final Map<TypeInfo, ClassData> innerClasses = new LinkedHashMap<>();
  private final Map<TypeInfo, Integer> innerClassesAccessModifiers = new LinkedHashMap<>();
  private final UniqueNameGenerator classNames = JbcSrcNameGenerators.forClassNames();

  public InnerClasses(TypeInfo outer) {
    this.outer = outer;
  }

  /** Returns all the {@link ClassData} for every InnerClass registered. */
  public ImmutableList<ClassData> getInnerClassData() {
    return ImmutableList.copyOf(innerClasses.values());
  }

  /**
   * Register the given name as an inner class with the given access modifiers.
   *
   * @return A {@link TypeInfo} with the full class name
   */
  public TypeInfo registerInnerClass(String simpleName, int accessModifiers) {
    classNames.claimName(simpleName);
    TypeInfo innerClass = outer.innerClass(simpleName);
    innerClassesAccessModifiers.put(innerClass, accessModifiers);
    return innerClass;
  }

  /**
   * Register the name (or a simpl mangling of it) as an inner class with the given access
   * modifiers.
   *
   * @return A {@link TypeInfo} with the full (possibly mangled) class name
   */
  public TypeInfo registerInnerClassWithGeneratedName(String simpleName, int accessModifiers) {
    simpleName = classNames.generateName(simpleName);
    TypeInfo innerClass = outer.innerClass(simpleName);
    innerClassesAccessModifiers.put(innerClass, accessModifiers);
    return innerClass;
  }

  /**
   * Adds the data for an inner class.
   *
   * @throws java.lang.IllegalArgumentException if the class wasn't previous registered via {@link
   *     #registerInnerClass(String, int)} or {@link #registerInnerClassWithGeneratedName(String,
   *     int)}.
   */
  public void add(ClassData classData) {
    checkRegistered(classData.type());
    innerClasses.put(classData.type(), classData);
  }

  private void checkRegistered(TypeInfo type) {
    if (!classNames.hasName(type.simpleName())) {
      throw new IllegalArgumentException(type + " wasn't registered");
    }
  }

  /**
   * Registers this factory as an inner class on the given class writer.
   *
   * <p>Registering an inner class is confusing. The inner class needs to call this and so does the
   * outer class. Confirmed by running ASMIfier. Also, failure to call visitInnerClass on both
   * classes either breaks reflective apis (like class.getSimpleName()/getEnclosingClass), or causes
   * verifier errors (like IncompatibleClassChangeError).
   */
  public void registerAsInnerClass(ClassVisitor visitor, TypeInfo innerClass) {
    checkRegistered(innerClass);
    doRegister(visitor, innerClass);
  }

  /** Registers all inner classes to the given outer class. */
  public void registerAllInnerClasses(ClassVisitor visitor) {
    for (Map.Entry<TypeInfo, Integer> entry : innerClassesAccessModifiers.entrySet()) {
      TypeInfo innerClass = entry.getKey();
      doRegister(visitor, innerClass);
    }
  }

  private void doRegister(ClassVisitor visitor, TypeInfo innerClass) {
    visitor.visitInnerClass(
        innerClass.internalName(), 
        outer.internalName(), 
        innerClass.simpleName(),
        innerClassesAccessModifiers.get(innerClass));
  }
}

public class MIMEBindingValidator
    extends AbstractDefinitionValidator {

    public MIMEBindingValidator(Definition def) {
        super(def);
    }

    public boolean isValid() {
        Collection<Binding> bindings = CastUtils.cast(def.getBindings().values());
        for (Binding binding : bindings) {
            Collection<BindingOperation> bindingOps = CastUtils.cast(binding.getBindingOperations());
            for (BindingOperation bindingOperation : bindingOps) {
                if (bindingOperation.getBindingInput() == null) {
                    continue;
                }
                Collection<ExtensibilityElement> exts = CastUtils.cast(bindingOperation
                                                                           .getBindingInput()
                                                                           .getExtensibilityElements());
                for (ExtensibilityElement extElement : exts) {
                    if (extElement instanceof MIMEMultipartRelated
                        && !doValidate((MIMEMultipartRelated)extElement,
                                       bindingOperation.getName())) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean doValidate(MIMEMultipartRelated mimeExt, String operationName) {
        boolean gotRootPart = false;
        List<MIMEPart> parts = CastUtils.cast(mimeExt.getMIMEParts());
        for (MIMEPart mPart : parts) {
            List<MIMEContent> mimeContents = new ArrayList<>();
            List<ExtensibilityElement> extns = CastUtils.cast(mPart.getExtensibilityElements());
            for (ExtensibilityElement extElement : extns) {
                if (SOAPBindingUtil.isSOAPBody(extElement)) {
                    if (gotRootPart) {
                        addErrorMessage("Operation("
                                        + operationName
                                        + "): There's more than one soap body mime part"
                                        + " in its binding input");
                        return false;
                    }
                    gotRootPart = true;
                } else if (extElement instanceof MIMEContent) {
                    mimeContents.add((MIMEContent)extElement);
                }
            }
            if (!doValidateMimeContentPartNames(mimeContents, operationName)) {
                return false;
            }
        }
        if (!gotRootPart) {
            addErrorMessage("Operation("
                            + operationName
                            + "): There's no soap body in mime part"
                            + " in its binding input");
            return false;
        }
        return true;
    }

    private boolean doValidateMimeContentPartNames(List<MIMEContent> mimeContents,
                                                   String operationName) {
        // validate mime:content(s) in the mime:part as per R2909
        String partName = null;
        for (MIMEContent mimeContent : mimeContents) {
            String mimeContnetPart = mimeContent.getPart();
            if (mimeContnetPart == null) {
                addErrorMessage("Operation("
                                + operationName
                                + "): Must provide part attribute value for meme:content elements");
                return false;
            }
            if (partName == null) {
                partName = mimeContnetPart;
            } else {
                if (!partName.equals(mimeContnetPart)) {
                    addErrorMessage("Operation("
                                    + operationName
                                    + "): Part attribute value for meme:content "
                                    + "elements are different");
                    return false;
                }
            }
        }
        return true;
    }
}

