            { service } : allServices;

            final JSONWriter jw = new JSONWriter( pw );

            jw.object();

            jw.key( "status" );
            jw.value( statusLine );

            jw.key( "serviceCount" );
            jw.value( allServices.length );

            jw.key( "data" );

            jw.array();

