@Override
public int compare(PropertyDescriptor d1, PropertyDescriptor d2) {
    String g1 = group(d1);
    String g2 = group(d2);
    Integer go1 = groupOrder(g1);
    Integer go2 = groupOrder(g2);

    int result = go1.compareTo(go2);
    if (result != 0) {
        return result;
    }

    result = g1.compareTo(g2);
    if (result != 0) {
        return result;
    }

    Integer po1 = propertyOrder(d1);
    Integer po2 = propertyOrder(d2);
    result = po1.compareTo(po2);
    if (result != 0) {
        return result;
    }

    return d1.getName().compareTo(d2.getName());
}

public class ViewerErrorScanner implements Runnable {

    // the process to monitor
    private Process process;

    public ViewerErrorScanner(Process process) {
        this.process = process;
    }

    /**
     * Wait for the program to exit and read the status.
     */
    public void run() {

        BufferedReader in = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        ArrayList buffer = new ArrayList();
        String tmp = null;
        try {

            // read the error output stream lines before the program exits
            // the stream is not available anymore after the program has exit
            while ((tmp = in.readLine()) != null) {
                buffer.add(tmp);
            }
            in.close();

        } catch (IOException e) {
        }

        int exitCode = 0;
        try {
            exitCode = process.waitFor();
        } catch (InterruptedException e) {
        }

        // if there was an error, the viewer exited with non-zero status
        if (exitCode != 0) {
            // print the error messages
            for (int i = 0; i < buffer.size(); i++) {
                tmp = (String) buffer.get(i);
                BuilderRegistry.printToConsole("viewer> " + tmp);
            }
        }
    }
}

