static final class SymbolComparator implements Comparator {

	/* (non-Javadoc)
	 * @see java.util.Comparator#compare(java.lang.Object, java.lang.Object)
	 */
	public int compare(Object arg0, Object arg1) {

		long addr0=0;
		long addr1=0;
		// arg0 and arg1 will be Symbol objects 
		if (arg0 instanceof Symbol) {
			Symbol S0 = (Symbol) arg0;
			Symbol S1 = (Symbol) arg1;
			addr0 = S0.symbolStart;
			addr1 = S1.symbolStart;
		} else {
			addr0 = ((Long)arg0).longValue();
			addr1 = ((Long)arg1).longValue();
		}

		// both +ve
		if (addr0 >= 0 && addr1 >=0) {
			if (addr0 == addr1) return 0;
			if (addr0 < addr1) return -1;
			return 1;
		}

		// both -ve 
		if (addr0 < 0 && addr1 < 0) {
			if (addr0 == addr1) return 0;
			if (addr0 < addr1) return 1;
			return -1;
		}

		if (addr0 < 0 && addr1 >=0) {
			return 1;
		}

		return -1;
	}

}

public void startElement(String uri, String localName, String qName, Attributes attributes)
            throws SAXException {
    if (delegate != null) {
        delegateStack.push(qName);
        delegate.startElement(uri, localName, qName, attributes);
    } else if (domImplementation != null) {
        //domImplementation is set so we need to start a new DOM building sub-process
        TransformerHandler handler;
        try {
            handler = tFactory.newTransformerHandler();
        } catch (TransformerConfigurationException e) {
            throw new SAXException("Error creating a new TransformerHandler", e);
        }
        Document doc = domImplementation.createDocument(uri, qName, null);
        //It's easier to work with an empty document, so remove the root element
        doc.removeChild(doc.getDocumentElement());
        handler.setResult(new DOMResult(doc));
        Area parent = (Area)areaStack.peek();
        ((ForeignObject)parent).setDocument(doc);

        //activate delegate for nested foreign document
        domImplementation = null; //Not needed anymore now
        this.delegate = handler;
        delegateStack.push(qName);
        delegate.startDocument();
        delegate.startElement(uri, localName, qName, attributes);
    } else {
        boolean handled = true;
        if ("".equals(uri)) {
            if (localName.equals("structureTree")) {

                /* The area tree parser no longer supports the structure tree. */
                delegate = new DefaultHandler();

                delegateStack.push(qName);
                delegate.startDocument();
                delegate.startElement(uri, localName, qName, attributes);
            } else {
                handled = startAreaTreeElement(localName, attributes);
            }
        } else {
            ContentHandlerFactoryRegistry registry
                    = userAgent.getContentHandlerFactoryRegistry();
            ContentHandlerFactory factory = registry.getFactory(uri);
            if (factory != null) {
                delegate = factory.createContentHandler();
                delegateStack.push(qName);
                delegate.startDocument();
                delegate.startElement(uri, localName, qName, attributes);
            } else {
                handled = false;
            }
        }
        if (!handled) {
            if (uri == null || uri.length() == 0) {
                throw new SAXException("Unhandled element " + localName
                        + " in namespace: " + uri);
            } else {
                log.warn("Unhandled element " + localName
                        + " in namespace: " + uri);
            }
        }
    }
}

public final class NamedMethodGenerator extends MethodGenerator {
    protected static final int CURRENT_INDEX  = 4;

    // The index of the first parameter (after dom/iterator/handler/current)
    private static final int PARAM_START_INDEX = 5;

    public NamedMethodGenerator(int access_flags, Type return_type,
				Type[] arg_types, String[] arg_names,
				String method_name, String class_name,
				InstructionList il, ConstantPoolGen cp) {
	super(access_flags, return_type, arg_types, arg_names, method_name, 
	      class_name, il, cp);
    }

    public int getLocalIndex(String name) {
	if (name.equals("current")) {
	    return CURRENT_INDEX;
	}
	return super.getLocalIndex(name);
    }

    public Instruction loadParameter(int index) {
        return new ALOAD(index + PARAM_START_INDEX);
    }

    public Instruction storeParameter(int index) {
        return new ASTORE(index + PARAM_START_INDEX);
    }
}

