        final String teamProject,
        final String[] qualitiesToAdd,
        final String[] qualitiesToRemove) {
        Check.notNull(buildServer, "buildServer"); //$NON-NLS-1$
        Check.notNullOrEmpty(teamProject, "teamProject"); //$NON-NLS-1$
