public class GlobbingPathHelper {

    /**
     * Converts the provided path containing glob characters <code>*</code> 
     * and <code>**</code> into a regular expression. The definition matches 
     * that of the GlobbingPathFilter with the addition that this conversion
     * also supports sub-paths which do not start with a <code>/</code>.
     * <p>
     * The rules are:
     * <ul>
     * <li>leading <code>**</code> matches <code>/foo</code> and <code>bar</code></li>
     * <li>leading <code>/**</code> matches <code>/foo</code> but not <code>bar</code></li>
     * <li>intermittent <code>**</code> matches zero or any number of path elements </li>
     * <li>trailing <code>**</code> matches anything not ending with a <code>/</code></li>
     * <li>single <code>*</code> matches anything except <code>/</code></li>
     * <li><code>?</code> is not a special character</li>
     * <li>anything not a star is wrapped into <code>\Q...\E</code> pairs</li>
     * </ul>
     * @param pathWithGlobs path that can contain * and **
     * @return a regular expression
     * @see GlobbingPathFilter
     */
    public static String globPathAsRegex(String pathWithGlobs) {
        if (pathWithGlobs == null) {
            return null;
        } else if (!pathWithGlobs.contains("*")) {
            return pathWithGlobs;
        }
        List<String> elements = Lists.newLinkedList(elements(pathWithGlobs));
        StringBuffer sb = new StringBuffer();
        sb.append("\\Q");
        if (pathWithGlobs.startsWith("/")) {
            sb.append("/");
        }
        if (elements.get(0).equals("**")) {
            sb.append("\\E[^/]*(/[^/]*)*\\Q");
            elements.remove(0);
        }
        int size = elements.size();
        boolean endsWithStarStar = size == 0 ? false : elements.get(size - 1).equals("**");
        if (endsWithStarStar) {
            elements.remove(size - 1);
        }
        boolean addSlash = false;
        for(int i=0; i<elements.size(); i++) {
            String pathElem = elements.get(i);
            if (addSlash) {
                sb.append("/");
            }
            if (pathElem.equals("**")) {
                addSlash = false;
                sb.append("\\E([^/]*/)*\\Q");
            } else {
                sb.append(pathElem.replace("*", "\\E[^/]*\\Q"));
                addSlash = true;
            }
        }
        if (endsWithStarStar) {
            sb.append("\\E(/[^/]*)*");
        } else if (pathWithGlobs.endsWith("/")) {
            sb.append("/\\E");
        } else {
            sb.append("\\E");
        }
        return sb.toString();
    }

}

@Component
@Service
@Reference(name = "provider", strategy = ReferenceStrategy.EVENT, policy = ReferencePolicy.DYNAMIC,
    referenceInterface = CloudProvider.class, cardinality = ReferenceCardinality.OPTIONAL_MULTIPLE)
public class CloudOperationsImpl implements CloudOperations {

  private List<CloudProvider> providers = new ArrayList<CloudProvider>();
  private List<CloudProviderId> providersId = null;

  @Reference
  private ProjectOperations projectOperations;

  @Override
  public boolean isSetupCommandAvailable() {
    return projectOperations.isProjectAvailable(projectOperations.getFocusedModuleName());
  }

  @Override
  public void installProvider(CloudProviderId prov, String configuration) {
    CloudProvider provider = null;
    for (CloudProvider tmpProvider : providers) {
      if (prov.is(tmpProvider)) {
        provider = tmpProvider;
        break;
      }
    }
    if (provider == null) {
      throw new RuntimeException("Provider '".concat(prov.getId()).concat("' not found'"));
    }
    provider.setup(configuration);

  }

  /**
   * This method gets providerId using name
   */
  @Override
  public CloudProviderId getProviderIdByName(String name) {
    CloudProviderId provider = null;
    for (CloudProvider tmpProvider : providers) {
      if (tmpProvider.getName().equals(name)) {
        provider = new CloudProviderId(tmpProvider);
      }
    }
    return provider;
  }

  /**
   * This method load new providers
   * 
   * @param provider
   */
  protected void bindProvider(final CloudProvider provider) {
    providers.add(provider);
  }

  /**
   * This method remove providers
   * 
   * @param provider
   */
  protected void unbindProvider(final CloudProvider provider) {
    providers.remove(provider);
  }

  /**
   * This method gets a List of available providers
   */
  @Override
  public List<CloudProviderId> getProvidersId() {
    if (providersId == null) {
      providersId = new ArrayList<CloudProviderId>();
      for (CloudProvider tmpProvider : providers) {
        providersId.add(new CloudProviderId(tmpProvider));
      }
      providersId = Collections.unmodifiableList(providersId);
    }
    return providersId;
  }
}

private class SampleMap implements SimpleMap {

  private SimpleMap map;
  private SimpleMap sample;

  public SampleMap(SimpleMap map, SimpleMap sampleMap) {
    this.map = map;
    this.sample = sampleMap;
  }

  @Override
  public int size() {
    return map.size();
  }

  @Override
  public InterruptibleIterator skvIterator(SamplerConfigurationImpl samplerConfig) {
    if (samplerConfig == null)
      return map.skvIterator(null);
    else {
      Pair<SamplerConfigurationImpl,Sampler> samplerAndConf = samplerRef.get();
      if (samplerAndConf == null) {
        return EmptyIterator.EMPTY_ITERATOR;
      } else if (samplerAndConf.getFirst() != null
          && samplerAndConf.getFirst().equals(samplerConfig)) {
        return sample.skvIterator(null);
      } else {
        throw new SampleNotPresentException();
      }
    }
  }

  @Override
  public void delete() {
    map.delete();
    sample.delete();
  }

  @Override
  public long getMemoryUsed() {
    return map.getMemoryUsed() + sample.getMemoryUsed();
  }

  @Override
  public void mutate(List<Mutation> mutations, int kvCount) {
    map.mutate(mutations, kvCount);

    Sampler sampler = getOrCreateSampler();
    if (sampler != null) {
      List<Mutation> sampleMutations = null;

      for (Mutation m : mutations) {
        List<ColumnUpdate> colUpdates = m.getUpdates();
        List<ColumnUpdate> sampleColUpdates = null;
        for (ColumnUpdate cvp : colUpdates) {
          Key k = new Key(m.getRow(), cvp.getColumnFamily(), cvp.getColumnQualifier(),
              cvp.getColumnVisibility(), cvp.getTimestamp(), cvp.isDeleted(), false);
          if (sampler.accept(k)) {
            if (sampleColUpdates == null) {
              sampleColUpdates = new ArrayList<>();
            }
            sampleColUpdates.add(cvp);
          }
        }

        if (sampleColUpdates != null) {
          if (sampleMutations == null) {
            sampleMutations = new ArrayList<>();
          }

          sampleMutations
              .add(new LocalityGroupUtil.PartitionedMutation(m.getRow(), sampleColUpdates));
        }
      }

      if (sampleMutations != null) {
        sample.mutate(sampleMutations, kvCount);
      }
    }
  }
}

