static class DelayedTimer implements Delayed {
    // most of it copied from
    // java.util.concurrent.ScheduledThreadPoolExecutor

    /**
     * Sequence number to break scheduling ties, and in turn to
     * guarantee FIFO order among tied entries.
     */
    private static final AtomicLong sequencer = new AtomicLong(0);

    /** Sequence number to break ties FIFO */
    private final long sequenceNumber;


    /** The time the task is enabled to execute in nanoTime units */
    private volatile long time;

    private final Timer timer;

    DelayedTimer(Timer timer, long nanos) {
        this.timer = timer;
        time = nanos;
        sequenceNumber = sequencer.getAndIncrement();
    }


    public final long getDelay(TimeUnit unit) {
        return  unit.convert(time - now(), TimeUnit.NANOSECONDS);
    }

    final void setTime(long nanos) {
        time = nanos;
    }

    final Timer getTimer() {
        return timer;
    }

    public int compareTo(Delayed other) {
        if (other == this) { // compare zero ONLY if same object
            return 0;
        }
        if (other instanceof DelayedTimer) {
            DelayedTimer x = (DelayedTimer)other;
            long diff = time - x.time;
            if (diff < 0) {
                return -1;
            } else if (diff > 0) {
                return 1;
            } else if (sequenceNumber < x.sequenceNumber) {
                return -1;
            }  else {
                return 1;
            }
        }
        long d = (getDelay(TimeUnit.NANOSECONDS) -
                  other.getDelay(TimeUnit.NANOSECONDS));
        return (d == 0) ? 0 : ((d < 0) ? -1 : 1);
    }
}

public class ZookeeperServerCnxnFactory {
    private static final Logger LOG = LoggerFactory.getLogger(ZookeeperServerCnxnFactory.class);
    int _port;
    NIOServerCnxnFactory _factory;

    public ZookeeperServerCnxnFactory(int port, int maxClientCnxns) {
        // port range
        int max;
        if (port <= 0) {
            _port = 2000;
            max = 65535;
        } else {
            _port = port;
            max = port;
        }

        try {
            _factory = new NIOServerCnxnFactory();
        } catch (IOException e) {
            _port = 0;
            _factory = null;
            e.printStackTrace();
            throw new RuntimeException(e.getMessage());
        }

        // look for available port
        for (; _port <= max; _port++) {
            try {
                _factory.configure(new InetSocketAddress(_port), maxClientCnxns);
                LOG.debug("Zookeeper server successfully binded at port " + _port);
                break;
            } catch (BindException e1) {
            } catch (IOException e2) {
                _port = 0;
                _factory = null;
                e2.printStackTrace();
                throw new RuntimeException(e2.getMessage());
            }
        }

        if (_port > max) {
            _port = 0;
            _factory = null;
            LOG.error("Failed to find a port for Zookeeper");
            throw new RuntimeException("No port is available to launch an inprocess zookeeper.");
        }
    }

    public int port() {
        return _port;
    }

    public NIOServerCnxnFactory factory() {
        return _factory;
    }
}

