private TtmlRegion parseRegionAttributes(
    XmlPullParser xmlParser, CellResolution cellResolution, TtsExtent ttsExtent) {
  String regionId = XmlPullParserUtil.getAttributeValue(xmlParser, TtmlNode.ATTR_ID);
  if (regionId == null) {
    return null;
  }

  float position;
  float line;

  String regionOrigin = XmlPullParserUtil.getAttributeValue(xmlParser, TtmlNode.ATTR_TTS_ORIGIN);
  if (regionOrigin != null) {
    Matcher originPercentageMatcher = PERCENTAGE_COORDINATES.matcher(regionOrigin);
    Matcher originPixelMatcher = PIXEL_COORDINATES.matcher(regionOrigin);
    if (originPercentageMatcher.matches()) {
      try {
        position = Float.parseFloat(originPercentageMatcher.group(1)) / 100f;
        line = Float.parseFloat(originPercentageMatcher.group(2)) / 100f;
      } catch (NumberFormatException e) {
        Log.w(TAG, "Ignoring region with malformed origin: " + regionOrigin);
        return null;
      }
    } else if (originPixelMatcher.matches()) {
      if (ttsExtent == null) {
        Log.w(TAG, "Ignoring region with missing tts:extent: " + regionOrigin);
        return null;
      }
      try {
        int width = Integer.parseInt(originPixelMatcher.group(1));
        int height = Integer.parseInt(originPixelMatcher.group(2));
        // Convert pixel values to fractions.
        position = width / (float) ttsExtent.width;
        line = height / (float) ttsExtent.height;
      } catch (NumberFormatException e) {
        Log.w(TAG, "Ignoring region with malformed origin: " + regionOrigin);
        return null;
      }
    } else {
      Log.w(TAG, "Ignoring region with unsupported origin: " + regionOrigin);
      return null;
    }
  } else {
    Log.w(TAG, "Ignoring region without an origin");
    return null;
    // TODO: Should default to top left as below in this case, but need to fix
    // https://github.com/google/ExoPlayer/issues/2953 first.
    // Origin is omitted. Default to top left.
    // position = 0;
    // line = 0;
  }

  float width;
  float height;
  String regionExtent = XmlPullParserUtil.getAttributeValue(xmlParser, TtmlNode.ATTR_TTS_EXTENT);
  if (regionExtent != null) {
    Matcher extentPercentageMatcher = PERCENTAGE_COORDINATES.matcher(regionExtent);
    Matcher extentPixelMatcher = PIXEL_COORDINATES.matcher(regionExtent);
    if (extentPercentageMatcher.matches()) {
      try {
        width = Float.parseFloat(extentPercentageMatcher.group(1)) / 100f;
        height = Float.parseFloat(extentPercentageMatcher.group(2)) / 100f;
      } catch (NumberFormatException e) {
        Log.w(TAG, "Ignoring region with malformed extent: " + regionOrigin);
        return null;
      }
    } else if (extentPixelMatcher.matches()) {
      if (ttsExtent == null) {
        Log.w(TAG, "Ignoring region with missing tts:extent: " + regionOrigin);
        return null;
      }
      try {
        int extentWidth = Integer.parseInt(extentPixelMatcher.group(1));
        int extentHeight = Integer.parseInt(extentPixelMatcher.group(2));
        // Convert pixel values to fractions.
        width = extentWidth / (float) ttsExtent.width;
        height = extentHeight / (float) ttsExtent.height;
      } catch (NumberFormatException e) {
        Log.w(TAG, "Ignoring region with malformed extent: " + regionOrigin);
        return null;
      }
    } else {
      Log.w(TAG, "Ignoring region with unsupported extent: " + regionOrigin);
      return null;
    }
  } else {
    Log.w(TAG, "Ignoring region without an extent");
    return null;
    // TODO: Should default to extent of parent as below in this case, but need to fix
    // https://github.com/google/ExoPlayer/issues/2953 first.
    // Extent is omitted. Default to extent of parent.
    // width = 1;
    // height = 1;
  }

  @Cue.AnchorType int lineAnchor = Cue.ANCHOR_TYPE_START;
  String displayAlign = XmlPullParserUtil.getAttributeValue(xmlParser,
      TtmlNode.ATTR_TTS_DISPLAY_ALIGN);
  if (displayAlign != null) {
    switch (Util.toLowerInvariant(displayAlign)) {
      case "center":
        lineAnchor = Cue.ANCHOR_TYPE_MIDDLE;
        line += height / 2;
        break;
      case "after":
        lineAnchor = Cue.ANCHOR_TYPE_END;
        line += height;
        break;
      default:
        // Default "before" case. Do nothing.
        break;
    }
  }

  float regionTextHeight = 1.0f / cellResolution.rows;
  return new TtmlRegion(
      regionId,
      position,
      line,
      /* lineType= */ Cue.LINE_TYPE_FRACTION,
      lineAnchor,
      width,
      /* textSizeType= */ Cue.TEXT_SIZE_TYPE_FRACTIONAL_IGNORE_PADDING,
      /* textSize= */ regionTextHeight);
}

class CompoundHorizontalPlacement extends HorizontalPlacement {

	class LeftRight {
		// $TODO Delete and use NodePair class, equivalent
		Object left, right;

		LeftRight(Object l, Object r) {
			left = l;
			right = r;
		}

		public boolean equals(Object obj) {
			LeftRight entry = (LeftRight) obj;
			return entry.left.equals(left) && entry.right.equals(right);
		}

		public int hashCode() {
			return left.hashCode() ^ right.hashCode();
		}
	}

	Set entries = new HashSet();

	/**
	 * @see org.eclipse.graph.HorizontalPlacement#applyGPrime()
	 */
	void applyGPrime() {
		super.applyGPrime();
		NodeList subgraphs = ((CompoundDirectedGraph) graph).subgraphs;
		for (int i = 0; i < subgraphs.size(); i++) {
			Subgraph s = (Subgraph) subgraphs.get(i);
			s.x = s.left.x;
			s.width = s.right.x + s.right.width - s.x;
		}
	}

	/**
	 * @see HorizontalPlacement#buildRankSeparators(RankList)
	 */
	void buildRankSeparators(RankList ranks) {
		CompoundDirectedGraph g = (CompoundDirectedGraph) graph;

		Rank rank;
		for (int row = 0; row < g.ranks.size(); row++) {
			rank = g.ranks.getRank(row);
			Node n = null, prev = null;
			for (int j = 0; j < rank.size(); j++) {
				n = rank.getNode(j);
				if (prev == null) {
					Node left = addSeparatorsLeft(n, null);
					if (left != null) {
						Edge e = new Edge(graphLeft, getPrime(left), 0, 0);
						prime.edges.add(e);
						e.delta = graph.getPadding(n).left
								+ graph.getMargin().left;
					}

				} else {
					Subgraph s = GraphUtilities.getCommonAncestor(prev, n);
					Node left = addSeparatorsRight(prev, s);
					Node right = addSeparatorsLeft(n, s);
					createEdge(left, right);
				}
				prev = n;
			}
			if (n != null)
				addSeparatorsRight(n, null);
		}
	}

	void createEdge(Node left, Node right) {
		LeftRight entry = new LeftRight(left, right);
		if (entries.contains(entry))
			return;
		entries.add(entry);
		int separation = left.width + graph.getPadding(left).right
				+ graph.getPadding(right).left;
		prime.edges
				.add(new Edge(getPrime(left), getPrime(right), separation, 0));
	}

	Node addSeparatorsLeft(Node n, Subgraph graph) {
		Subgraph parent = n.getParent();
		while (parent != graph && parent != null) {
			createEdge(getLeft(parent), n);
			n = parent.left;
			parent = parent.getParent();
		}
		return n;
	}

	Node addSeparatorsRight(Node n, Subgraph graph) {
		Subgraph parent = n.getParent();
		while (parent != graph && parent != null) {
			createEdge(n, getRight(parent));
			n = parent.right;
			parent = parent.getParent();
		}
		return n;
	}

	Node getLeft(Subgraph s) {
		if (s.left == null) {
			s.left = new SubgraphBoundary(s, graph.getPadding(s), 1);
			s.left.rank = (s.head.rank + s.tail.rank) / 2;

			Node head = getPrime(s.head);
			Node tail = getPrime(s.tail);
			Node left = getPrime(s.left);
			Node right = getPrime(getRight(s));
			prime.edges.add(new Edge(left, right, s.width, 0));
			prime.edges.add(new Edge(left, head, 0, 1));
			prime.edges.add(new Edge(head, right, 0, 1));
			prime.edges.add(new Edge(left, tail, 0, 1));
			prime.edges.add(new Edge(tail, right, 0, 1));
		}
		return s.left;
	}

	Node getRight(Subgraph s) {
		if (s.right == null) {
			s.right = new SubgraphBoundary(s, graph.getPadding(s), 3);
			s.right.rank = (s.head.rank + s.tail.rank) / 2;
		}
		return s.right;
	}

	Node getPrime(Node n) {
		Node nPrime = get(n);
		if (nPrime == null) {
			nPrime = new Node(n);
			prime.nodes.add(nPrime);
			map(n, nPrime);
		}
		return nPrime;
	}

	public void visit(DirectedGraph g) {
		super.visit(g);
	}

}

@Deprecated
public class AsynchronousRunner
    implements RunnerScheduler
{
    private final List<Future<Object>> futures = Collections.synchronizedList( new ArrayList<Future<Object>>() );

    private final ExecutorService fService;

    public AsynchronousRunner( ExecutorService fService )
    {
        this.fService = fService;
    }

    @Override
    public void schedule( final Runnable childStatement )
    {
        futures.add( fService.submit( Executors.callable( childStatement ) ) );
    }


    @Override
    public void finished()
    {
        try
        {
            waitForCompletion();
        }
        catch ( ExecutionException e )
        {
            throw new RuntimeException( e );
        }
    }

    public void waitForCompletion()
        throws ExecutionException
    {
        for ( Future<Object> each : futures )
        {
            try
            {
                each.get();
            }
            catch ( InterruptedException e )
            {
                throw new RuntimeException( e );
            }
        }
    }
}

@InterfaceAudience.Public
@InterfaceStability.Stable
public class RegexMapper<K> extends Mapper<K, Text, Text, LongWritable> {

  public static String PATTERN = "mapreduce.mapper.regex";
  public static String GROUP = "mapreduce.mapper.regexmapper..group";
  private Pattern pattern;
  private int group;

  public void setup(Context context) {
    Configuration conf = context.getConfiguration();
    pattern = Pattern.compile(conf.get(PATTERN));
    group = conf.getInt(GROUP, 0);
  }

  public void map(K key, Text value,
                  Context context)
    throws IOException, InterruptedException {
    String text = value.toString();
    Matcher matcher = pattern.matcher(text);
    while (matcher.find()) {
      context.write(new Text(matcher.group(group)), new LongWritable(1));
    }
  }
}

